The physical observables can be extracted by differentiating Eq.~(\ref{eq:ope}) with respect to $-1/T$, yielding
\begin{eqnarray}
\overline{\Lambda}(\omega_c, T)
&=& \frac{1}{\Pi(\omega_c, T)} \cdot \frac{\partial \Pi(\omega_c, T)}{\partial(-1/T)} \, ,
\label{eq:mass}
\\
f(\omega_c, T)^2
&=& \Pi(\omega_c, T) \cdot e^{\overline{\Lambda}(\omega_c, T) / T} \, .
\label{eq:coupling}
\end{eqnarray}
There are two free parameters in these expressions: the threshold value $\omega_c$ and the Borel mass $T$. To determine their reliable working windows, we impose three standard criteria. Throughout this analysis, we adopt the following values for the QCD input parameters~\cite{pdg,Yang:1993bp,Narison:2011xe,Narison:2018dcr,Gimenez:2005nt,Jamin:2002ev,Ioffe:2002be,Ovchinnikov:1988gk,Colangelo:2000dp}:
\begin{eqnarray}
\nonumber \langle \bar{q} q \rangle &=& -(0.240~\mathrm{GeV})^3 \, , 
\\ \nonumber \langle \bar{s} s \rangle &=& (0.8 \pm 0.1) \times \langle \bar{q} q \rangle \, , 
\\ \nonumber \langle g_s \bar{q} \sigma G q \rangle &=& - M_0^2 \times \langle \bar{q} q \rangle \, , 
\\ \langle g_s \bar{s} \sigma G s \rangle &=& - M_0^2 \times \langle \bar{s} s \rangle \, ,
\label{eq:condensate}
\\ \nonumber M_0^2 &=& (0.8 \pm 0.2)~\mathrm{GeV}^2 \, , 
\\ \nonumber \langle g_s^2 G^2 \rangle &=& (6.35 \pm 0.35) \times 10^{-2}~\mathrm{GeV}^4 \, , 
\\ \nonumber m_s &=& 119 \pm 1~\mathrm{MeV} \, ,
\\ \nonumber m_q &\approx& m_u \approx m_d \approx 5.3~\mathrm{MeV} \, .
\end{eqnarray}
In particular, we adopt the pole mass of the strange quark, $m_s^{\mathrm{pole}}$, at the renormalization scale $\mu = 2~\mathrm{GeV}$. This quantity is derived from the perturbative relation connecting the pole mass to the $\overline{\mathrm{MS}}$ mass $m_s^{\overline{\mathrm{MS}}}(\mu)$~\cite{pdg,Melnikov:2000qh,Chetyrkin:1999ys,Broadhurst:1991fy,Gray:1990yh}:
\begin{eqnarray} 
m_s^{\mathrm{pole}} &=& m_s^{\overline{\mathrm{MS}}}(\mu) \times \Bigg\{ 1 + \frac{4}{3} \cdot \frac{\bar{\alpha}_s(\mu)}{\pi} \\
&+& \frac{\bar{\alpha}_s(\mu)^2}{\pi^2} \Big(-1.0414\,n_f + 13.4434\Big) \nonumber \\ \nonumber
&+& \frac{\bar{\alpha}_s(\mu)^3}{\pi^3} \Big(0.6527\,n_f^2 - 26.655\,n_f + 190.595\Big) \Bigg\} \, ,
\end{eqnarray}
where $\bar{\alpha}_s(\mu)$ represents the QCD running coupling constant in the $\overline{\mathrm{MS}}$ scheme.

The first criterion requires that the high-dimensional power corrections contribute less than 20\% of the total correlator:
\begin{equation}
\label{eq_convergence}
\mathrm{CVG} \equiv \left| \frac{ \Pi^{\text{high-order}}(\omega_c, T) }{ \Pi(\omega_c, T) } \right| \leq 20\% \, .
\end{equation}
As shown in Fig.~\ref{fig:pole}(a), this sets the lower bound of the Borel mass as $T_{\min} = 0.30~\mathrm{GeV}$.

The second criterion requires the pole contribution (PC) to be no less than 20\%:
\begin{equation}
\label{eq_pole}
\mathrm{PC} \equiv \frac{ \Pi(\omega_c, T) }{ \Pi(\infty, T) } \geq 20\% \, .
\end{equation}
As shown in Fig.~\ref{fig:pole}(b), this determines the upper bound $T_{\max} = 0.49~\mathrm{GeV}$ for $\omega_c = 1.87~\mathrm{GeV}$. Together, these two conditions define a preliminary Borel window:
\begin{equation}
0.30~\mathrm{GeV} < T < 0.49~\mathrm{GeV} \, .
\end{equation}

To further refine this range, we analyze the $T$-dependence of the extracted parameters $\overline{\Lambda}$ and $f$, as shown in Fig.~\ref{fig:leading}. The convergence ratio CVG peaks near $T_{\rm peak} = 0.43~\mathrm{GeV}$, above which the extracted results become significantly more stable. Below this point, both $\overline{\Lambda}$ and $f$ exhibit strong sensitivity to $T$, violating the stability requirement. Therefore, the third criterion—Borel stability—restricts the working region to
\begin{equation}
0.43~\mathrm{GeV} < T < 0.49~\mathrm{GeV} \, .
\end{equation}
Within this refined Borel window, the extracted numerical values are
\begin{eqnarray}
\overline{\Lambda}_{ \Xi^\prime_t} &=& 1.38_{-0.15}^{+0.15}~\mathrm{GeV} \, , \\
f_{ \Xi^\prime_t} &=& 0.094_{-0.024}^{+0.030}~\mathrm{GeV}^3 \, ,
\end{eqnarray}
where the central values correspond to $T = 0.46~\mathrm{GeV}$ and $\omega_c = 1.87~\mathrm{GeV}$.


\section{Results at the ${\mathcal O}(1/m_Q)$ order}
\label{sec:nexttoleading}

In this section we extend the analysis to include ${\mathcal O}(1/m_Q)$ corrections~\cite{Dai:1996qx,Dai:2003yg}. To this end, we employ the effective Lagrangian of HQET:
\begin{eqnarray}
\mathcal{L}_{\rm eff} = \overline{h}_{v} i v \cdot D\, h_{v} + \frac{1}{2m_t} \mathcal{K} + \frac{1}{2m_t} \mathcal{S} \, ,
\label{eq:next}
\end{eqnarray}
where $\mathcal{K}$ denotes the nonrelativistic kinetic energy operator,
\begin{eqnarray}
\mathcal{K} = \overline{h}_{v} (i D_{t})^{2} h_{v} \, ,
\end{eqnarray}
and $\mathcal{S}$ represents the Pauli term describing the chromomagnetic interaction,
\begin{eqnarray}
\mathcal{S} = \frac{g_s}{2} C_{\rm mag} \left( \frac{m_t}{\mu} \right) \overline{h}_{v} \sigma_{\mu\nu} G^{\mu\nu} h_{v} \, ,
\end{eqnarray}
with the Wilson coefficient
\begin{eqnarray}
C_{\rm mag} \left( \frac{m_t}{\mu} \right) = \left[ \frac{\overline{\alpha}_s(m_t)}{\overline{\alpha}_s(\mu)} \right]^{3/\beta_0} \, ,
\end{eqnarray}
and $\beta_0 = 11 - \frac{2}{3} n_f$. At the renormalization scale $\mu = 2~\mathrm{GeV}$, this coefficient evaluates to $C_{\rm mag}(\mu) \approx 0.6$ for the top quark.

The pole term can then be expanded up to ${\mathcal O}(1/m_t)$ as
\begin{eqnarray}
\Pi(\omega) &=& \frac{(f + \delta f)^2}{\overline{\Lambda} + \delta m - \omega}
\label{eq:correction}
\\ \nonumber &=& \frac{f^2}{\overline{\Lambda} - \omega} - \frac{\delta m f^2}{(\overline{\Lambda} - \omega)^2} + \frac{2f \delta f}{\overline{\Lambda} - \omega} \, ,
\end{eqnarray}
where $\delta m$ and $\delta f$ denote the ${\mathcal O}(1/m_t)$ corrections to the baryon mass $m_{\Xi^\prime_t}$ and the decay constant $f$, respectively.

To evaluate $\delta m$, we consider the following three-point correlation functions:
\begin{eqnarray}
\delta_O \Pi(\omega, \omega^\prime)
&=& i^2 \int d^4x\, d^4y\, e^{i k \cdot x - i k^\prime \cdot y}
\label{eq:nextpi}
\\ \nonumber && ~~~~~ \times \langle 0 | T[J_{\Xi^\prime_t}(x)\, O(0)\, \bar{J}_{\Xi^\prime_t}(y)] | 0 \rangle \, ,
\end{eqnarray}
where $O = \mathcal{K}$ or $\mathcal{S}$. Based on the effective Lagrangian in Eq.~(\ref{eq:next}), the above correlators can be expressed at the hadron level as
\begin{eqnarray}
\delta_{\mathcal{K}} \Pi(\omega, \omega^\prime) &=& \frac{f^2 K}{(\overline{\Lambda} - \omega)(\overline{\Lambda} - \omega^\prime)} + \cdots \, ,
\label{eq:K}
\\
\delta_{\mathcal{S}} \Pi(\omega, \omega^\prime) &=& \frac{d_M f^2 \Sigma}{(\overline{\Lambda} - \omega)(\overline{\Lambda} - \omega^\prime)} + \cdots \, ,
\label{eq:S}
\end{eqnarray}
where $K$, $\Sigma$, and $d_M$ are defined as
\begin{eqnarray}
K &\equiv& \langle \Xi^\prime_t | \overline{h}_v (i D_\perp)^2 h_v | \Xi^\prime_t \rangle \, ,
\\
d_M \Sigma &\equiv& \left\langle \Xi^\prime_t \left| \frac{g_s}{2} \overline{h}_v \sigma_{\mu\nu} G^{\mu\nu} h_v \right| \Xi^\prime_t \right\rangle \, ,
\\
d_M &\equiv& d_{j, j_l} \, ,
\\
d_{j_l - 1/2, j_l} &=& 2 j_l + 2 \, ,
\\
d_{j_l + 1/2, j_l} &=& -2 j_l \, .
\end{eqnarray}
Setting $\omega = \omega^\prime$ and combining Eqs.~(\ref{eq:correction}), (\ref{eq:K}), and (\ref{eq:S}), we obtain
\begin{eqnarray}
\delta m = -\frac{1}{2 m_t} \left( K + d_M C_{\rm mag} \Sigma \right) \, .
\label{eq:more}
\end{eqnarray}

