&&f^2 K\, e^{-\overline{\Lambda} / T}
\nonumber\\&=&-\Bigg\{\int_{s_<}^{\omega_c}
\bigg[\frac{396 \, \omega^7}{7! \, \pi^4}
-\frac{18 \, \omega^5}{5! \, \pi^4}(4m_q^2 + 4m_s^2 - 3m_q m_s)
\nonumber\\&& -\frac{\langle g^2 GG \rangle \, \omega^3}{384 \, \pi^4}
+\frac{ \, \omega^3}{4 \, \pi^2}
\Big(5m_q \langle \bar{q} q \rangle + 5m_s \langle \bar{s} s \rangle
\nonumber\\&& -6m_s \langle \bar{q} q \rangle - 6m_q \langle \bar{s} s \rangle \Big)
+\frac{11 \, \omega}{256 \, \pi^2}
\Big(m_q \langle g_s \bar{q} \sigma G q \rangle
\nonumber\\&& + m_s \langle g_s \bar{s} \sigma G s \rangle \Big)
\bigg] e^{-\omega/T} \, d\omega
\nonumber\\&&
-\frac{3}{16} \Big( \langle \bar{q} q \rangle \langle g_s \bar{s} \sigma G s \rangle
+ \langle \bar{s} s \rangle \langle g_s \bar{q} \sigma G q \rangle \Big)\Bigg\},
\label{eq:Kc}
\\
&&f^2 d_M \Sigma\, e^{-\overline{\Lambda} / T}
\nonumber\\&=& \int_{s_<}^{\omega_c}
\Bigg[
\frac{4 g_s^2 \, \omega^7}{105 \, \pi^6}
+ \frac{\langle g^2 GG \rangle \, \omega^3}{48 \, \pi^4}
\nonumber\\&&
- \frac{\omega}{16 \, \pi^2}
\Big(m_q \langle g_s \bar{q} \sigma G q \rangle + m_s \langle g_s \bar{s} \sigma G s \rangle
\nonumber\\&&
- 2m_s \langle g_s \bar{q} \sigma G q \rangle - 2m_q \langle g_s \bar{s} \sigma G s \rangle \Big)
\Bigg] e^{-\omega/T} \, d\omega
\nonumber\\&&
- \frac{1}{24} \Big(
\langle \bar{q} q \rangle \langle g_s \bar{s} \sigma G s \rangle
+ \langle \bar{s} s \rangle \langle g_s \bar{q} \sigma G q \rangle \Big) \, .
