\section{Method}
% \subsection{Orientation and indicator function's Recovering in $\mathbb{R}^2$}

% \subsection{Orientation and Surface Reconstruction in $\mathbb{R}^3$}
\label{sec:method}

A critical and popular way to reconstruct the surfaces from the unoriented point clouds is by calculating the indicator function $\chi$ of target region. In detail,
let $\Omega \subset \mathbb{R}^{3}$ be an open and bounded region with the smooth boundary $\partial \Omega$ and the input oriented points are $\mathcal{P}=\{\bm{p}_i\}_{i=1}^{M}$ on the target surface $\partial \Omega$. Then,
\begin{equation}\label{12}
	\chi(\bm{x})=\begin{cases}
	1, & \mbox{if  } \bm{x} \in \Omega\\
	0,  & \mbox{if  } \bm{x} \notin \overline{\Omega},
\end{cases}
\end{equation}
where $\overline{\Omega}$ is the closure of $\Omega$, and we can use the indicator function to distinguish between inside and outside the region and find the position of surface.

% Then, we use the established  set of Db4 wavelet bases $B_{i}(\bm{x}) \in \{\varphi_{\bm{k}}(x,y,z), \psi^{\bm{e}}_{j,\bm{k}}(x,y,z),j\in\mathbb{N}\}$ to represent the indicator function. 

% and Db4 wavelet bases are continuous throughout the entire three-dimensional space

% \paragraph*{\textbf{Mollified Indicator Function}}
\subsection{\textbf{Mollified Indicator Function}}
However, the indicator function $\chi(\bm{x})$  is discontinuous at the boundary of region and its value  is independent of the distance to the boundary, near the boundary. It greatly reduces the accuracy of generating surface meshes. Hence, we modify it to make it continue and contain the information of distance near the surface.  That is
\begin{align*}
    \overline{\chi}(\bm{x})=\int_{\mathbb{R}^3}\overline{K}_{\varepsilon}(\bm{x}-\bm{y})\chi(\bm{y}) \text{d} \bm{y},
    \end{align*}
    where: $\overline{K}_{\varepsilon}(\bm{x})$ is a mollifier function in three-dimension, and $\overline{\chi}(\bm{x})$ is the mollified indicator function and it can be continuous throughout the entire three-dimensional space. Taking any function $B(\bm{x})$ in three-dimensional space as the test function and employing the divergence theorem, its inner product with the mollified indicator function $\overline{\chi}(\bm{x})$ can be calculated as

    \begin{equation}\label{1}
	\begin{aligned}
		c_{i}=\langle \overline{\chi}(\bm{x}),B(\bm{x}) \rangle&=
		\int_{\mathbb{R}^{3}}\overline{\chi}(\bm{x})\cdot B(\bm{x}) \d \bm{x} =\int_{\mathbb{R}^3}\int_{\mathbb{R}^3}\overline{K}_{\varepsilon}(\bm{x}-\bm{y})\chi(\bm{y})\  \d \bm{y} \ B(\bm{x}) \d \bm{x} \\
        &=\int_{\mathbb{R}^3}\int_{\mathbb{R}^3}\overline{K}_{\varepsilon}(\bm{x}-\bm{y})\chi(\bm{y}) \ B(\bm{x}) \  \d \bm{y} \d \bm{x}\\
        &=\int_{\mathbb{R}^3}\int_{\mathbb{R}^3}\overline{K}_{\varepsilon}(\bm{y}-\bm{x})\chi(\bm{x}) \ B(\bm{y}) \  \d \bm{y} \d \bm{x}\\
        &=\int_{\mathbb{R}^3}\chi(\bm{x})\int_{\mathbb{R}^3}\overline{K}_{\varepsilon}(\bm{y}-\bm{x}) \ B(\bm{y}) \  \d \bm{y} \d \bm{x}\\
        &=\int_{\mathbb{R}^3}\chi(\bm{x})\overline{B}_{\varepsilon}(\bm{x}) \d \bm{x}=\int_{\Omega} \overline{B}_{\varepsilon}(\bm{x}) \d \bm{x} \\
        &=\int_{\partial \Omega}\bm{\overline{F}}_{\varepsilon}(\bm{x}) \cdot \bm{n}(\bm{x}) \d S,
        % \approx\sum_{\bm{p}_{j} \in \text{supp} \bm{\overline{F}}_{\varepsilon,i} \cap \partial \Omega}\bm{\overline{F}}_{\varepsilon,i}(\bm{p}_{j})\cdot \bm{n}(\bm{p}_{j})  S(\bm{p}_{j}),
	\end{aligned}
\end{equation}
where $\langle \cdot ,\cdot \rangle$ represents the $L_2$ inner product in $\mathbb{R}^3$ and  $\nabla \cdot \overline{F}_{\varepsilon}(\bm{x})=\overline{B}_{\varepsilon}(\bm{x}) $.
The mollifying has been transferred to the test function $B(\bm{x})$. We choose the Db4 wavelet bases as the test functions with the following reasons. (1) The Db4 wavelet bases exhibit orthogonality, with the corresponding theorems detailed in the Appendix \ref{Appendix}. (2) The Db4 wavelet bases has a compact support set of $7^3$ in $\mathbb{R}^3$. When $level=3$, its support becomes $(\frac{7}{2^3})^3$ fitting the normal size of octree ($[0,1]^3$) well, which can reduce computational complexity greatly.
(3) Db4 with $level=3$ is the wavelet basis function with the highest vanishing moment among the wavelet bases that can be accommodated in $[0,1]^3$. The larger the vanishing moment of a wavelet basis function, the better its smoothness.

Similar to iWSR \cite{iwsr},
we truncate the Db4's infinite term representation of the mollified indicator function to a finite term 
\begin{equation}\label{11}
	\overline{\chi}(\bm{x}) = \sum_{i=1}^{N}c_{i}B_{i}(\bm{x}).
\end{equation}

The computation of the implicit field ( $\overline{\chi} (\bm{x})$) is simplified by calculating the corresponding coefficients $c_i$ of the wavelet bases. For any fixed $i$, due to the orthogonality, 
\begin{align*}
    \langle \overline{\chi}(\bm{x}),B_i(\bm{x}) \rangle=\langle \sum_{j=1}^{N}c_{j}B_{j}(\bm{x}),B_i(\bm{x}) \rangle=\sum_{j=1}^{N}  c_{j}\langle B_{j}(\bm{x}),B_i(\bm{x}) \rangle=c_i,
\end{align*}
these coefficients can be calculated by Equation \eqref{1}. During the calculation of $c_i$, we need handle the mollifying of Db4 wavelet bases. While it is possible to mollify each basis function individually, the number of wavelet basis functions can reach millions as the number of layers increases. Consequently, this approach is impractical. To tackle this dilemma, we propose a novel mollifying strategy to accelerate the speed of computation significantly by constructing a tensor-product-based mollifying kernel function,

 \begin{align*}
    &\overline{K}_{\varepsilon}(x,y,z)=K_{\varepsilon}(x)K_{\varepsilon}(y)K_{\varepsilon}(z)\\
    &K_{\varepsilon}(x)=\dfrac{1}{\varepsilon}K(\dfrac{x}{\varepsilon}),
\end{align*}
where $\varepsilon$ is the chosen smooth width, and $K(x)$ is the mollifier function in field of partial differential equations \cite{evans2022partial} in mathematics.
\begin{equation*}
	K(x)=\begin{cases}
	\dfrac{1}{\int_{-1}^{1}\exp(\dfrac{1}{x^2-1})\text{d} x} \cdot \exp(\dfrac{1}{x^2-1}), & \mbox{if  } |x|<1\\
	0,  & \mbox{if  } |x|\geqslant 1.
\end{cases}
\end{equation*}

 We only need to mollify the one-dimensional wavelet basis functions by utilizing tensor products. Taking $B(\bm{x})=\psi^{(1,0,0)}_{j,\bm{k}}(\bm{x})=\psi_{j,k_1}(x_1)\varphi_{j,k_2}(x_2)\varphi_{j,k_3}(x_3)$ as an example  and the detailed calculation process for mollifying is shown below. 

\begin{align*}
&\overline{B}_{\varepsilon}(\bm{x})=\int_{\mathbb{R}^3}\overline{K}_{\varepsilon}(\bm{y}-\bm{x}) \ B(\bm{y}) \  \d \bm{y}\\
&=\int_{\mathbb{R}}\int_{\mathbb{R}}\int_{\mathbb{R}}K_{\varepsilon}(y_1-x_1)K_{\varepsilon}(y_2-x_2)K_{\varepsilon}(y_3-x_3)\psi_{j,k_1}(y_1)\psi_{j,k_2}(y_2)\varphi_{j,k_3}(y_3) \d y_1 \d y_2 \d y_3\\
&= \int_{\mathbb{R}}K_{\varepsilon}(y_1-x_1)\psi_{j,k_1}(y_1) \d y_1 \cdot\int_{\mathbb{R}}K_{\varepsilon}(y_2-x_2)\varphi_{j,k_2}(y_2) \d y_2 \cdot\int_{\mathbb{R}}K_{\varepsilon}(y_3-x_3)\varphi_{j,k_3}(y_3) \d y_3 \\
&= \overline{\psi}_{\varepsilon,j,k_1}(x_1) \cdot \overline{\psi}_{\varepsilon,j,k_2} (x_2)\cdot\overline{\varphi}_{\varepsilon,j,k_3}(x_3).
\end{align*}

By utilizing the multi-scale property of wavelet basis functions, we can further transform all the mollifying of different layer basis functions into scale basis functions or wavelet basis functions to accelerate. Taking the wavelet basis function with translation $k$ in level $j$ ($\psi_{j,k}$) as the example,
\begin{equation}
\begin{aligned}
\overline{\psi}_{\varepsilon,j,k}&=\int_{\mathbb{R}}K_{\varepsilon }(y)\psi_{j,k}(x-y) \d y \\
&=\int_{\mathbb{R}}K_{\varepsilon }(y) \cdot 2^{\frac{j}{2}} \cdot \psi(2^j(x-y)-k)\d y \\
&=\int_{\mathbb{R}}K_{2^j \varepsilon }(2^j y)\cdot 2^j \cdot 2^{\frac{j}{2}} \cdot  \psi(2^j x- 2^j y-k)\d y\\
&= \int_{\mathbb{R}}K_{2^j \varepsilon}(t)\cdot 2^j \cdot 2^{\frac{j}{2}} \cdot  \psi(2^j x- t -k) \cdot 2^{-j} \d t\\
&=\int_{\mathbb{R}}K_{2^j \varepsilon}(t) \cdot 2^{\frac{j}{2}} \cdot  \psi(2^j x- t -k) \d t\\
&=2^{\frac{j}{2}}\overline{\psi}_{2^j \varepsilon}(2^j x-k),
\end{aligned}
\end{equation}
 it can also be obtained by processing the standard wavelet basis function $\psi$ using mollifier function with a width of $2^j \varepsilon$.

 The corresponding vector function $\overline{\bm{F}}_{\varepsilon}(\bm{x})$ can be constructed by tensor products, taking $\bm{e}=(1,0,0)$ as the example.

\begin{align}\label{12}
\overline{\bm{F}}_{\varepsilon,j,\bm{k}}^{(1,0,0)}(x_1,x_2,x_3)=(\overline{\Psi}_{\varepsilon,j,k_1}(x_1)\overline{\varphi}_{\varepsilon,j,k_2}(x_{2})\overline{\varphi}_{\varepsilon,j,k_3}(x_3),0,0),
\end{align} 
where $\overline{\Psi}_{\varepsilon}(t)=\int_{-\infty}^{t}\overline{\psi}_{\varepsilon}(s)\d s$, and
\begin{align*}
    \overline{\Psi}_{\varepsilon,j,k}(x)&=\int_{0}^{x}\overline{\psi}_{\varepsilon,j,k_1}(t) \d t\\
    &= \int_{0}^{x} 2^{\frac{j}{2}} \cdot\overline{\psi}_{2^j \varepsilon}(2^j t-k) \d t\\
    &=\int_{0}^{2^j x-k} 2^{\frac{j}{2}} \cdot \overline{\psi}_{2^j \varepsilon}(s)\cdot 2^{-j} \d s\\
    &=2^{-\frac{j}{2}} \overline{\Psi}_{2^j \varepsilon}(2^j x-k).
\end{align*}

Thus, we have achieved rapid computation of the mollified indicator function. We select the input points $\bm{p}_{i}$ lying on the surface as the query point $\bm{x}$ in Equation \eqref{chi} sequentially. According to  $\chi(\bm{p}_{i})=\frac{1}{2},\ i=1,2,\cdots,M$, We can construct $M$ non-homogeneous equations about the target surface.

\subsection{\textbf{The Homogeneous Constraint}}
% \paragraph*{\textbf{The Homogeneous Constraint}}
Although we have constructed a series of non-homogeneous linear equations using the divergence theorem, only $M$
non-homogeneous equations are not enough, which is also shown in PGR \cite{2022PGR}. Since there are $3M$ unknowns, in order to avoid solving the underdetermined equation systems, we extensively utilize the well-known divergence theorem in vector analysis to construct additional homogeneous constraints.

For any  function $G: \mathbb{R}^3 \to \mathbb{R}^3$ with the continuous two-order partial derivatives, we denote $G=(G_x(x,y,z),G_y(x,y,z),G_z(x,y,z))$. Then, its curl field

\begin{align}\label{F}
    F=\nabla \times G=(\frac{\partial G_{z}}{\partial y}-\frac{\partial G_{y}}{\partial z},\frac{\partial G_{x}}{\partial z}-\frac{\partial G_{z}}{\partial x}
    ,\frac{\partial G_{y}}{\partial x}-\frac{\partial G_{x}}{\partial y})
\end{align} is the divergence-free vector field in three-dimension. In other words, 

\begin{align*}
    \text{div} F=\frac{\partial^{2} G_{z}}{\partial y\partial x}-\frac{\partial^{2} G_{y}}{\partial z\partial x}+\frac{\partial^{2} G_{x}}{\partial z\partial y}-\frac{\partial^{2} G_{z}}{\partial x\partial y}+\frac{\partial^{2} G_{y}}{\partial x \partial z}-\frac{\partial^{2} G_{x}}{\partial y \partial z}=0,
\end{align*}
and  
\begin{align}\label{h}
    \int_{\partial \Omega} F \cdot n \d S=\int_{\Omega} \text{div} F \d \bm{x}= \int_{\Omega} 0 \d \bm{x}=0.
\end{align}

Thus, this naturally construct more constraints on the surface. Since the target surface is closed and has no boundary, the same conclusion can be derived by the Stokes' theorem, which is shown in \cite{gotsman2024linear}. Equation \eqref{F} shows a method to construct the divergence-free function, and  any number of such homogeneous constraint can be constructed by selecting different kernel functions $G$. 

Since the linearly independent kernel functions can add the new information, we show the in-depth discussion on the selection of kernel functions $G$. We propose a novel way to constrcuting unlimited number of linearly independent functions via the  parameter $\bm{w_1}=(w_{1,1},w_{1,2},w_{1,3}) \in \mathbb{R}^3$ and $\bm{w_2}=(w_{2,1},w_{2,2},w_{2,3}) \in \mathbb{R}^3$, which are the weights of the points and functions, respectively. In detail, for any points $\bm{x}=(x_1,x_2,x_3)$, 
\begin{equation}\label{380}
\begin{aligned}
    &G_x= w_{2,1} \cdot \cos(w_{1,1}x_1+w_{1,2}x_2+w_{1,3}x_3),\\
    &G_y= w_{2,2} \cdot \sin(w_{1,1}x_1+w_{1,2}x_2+w_{1,3}x_3),\\
    &G_z= w_{2,3} \cdot \sqrt{w_{1,1}x_1+w_{1,2}x_2+w_{1,3}x_3}.\\
\end{aligned}  
\end{equation}

Although the proof that $G_x,G_y,G_z$ is a linearly independent set of functions for all $\bm{w_1}$ is difficult and complex due to their multivariate nature, it could be obvious in the one-dimension case. 
For the three-dimensional function family $G(\bm{w}_1)$, if one dimension of the function family is linearly independent (e.g. $G_x(\bm{w}_1)$) for the parameters, then $G(\bm{w}_1)$ must be linearly independent.

Actually, for $\cos(ax)$,  if $\sum_{k=1}^n c_k \cdot \cos(a_k x) = 0 \  (\forall x \in \mathbb{R})$, we take  Fourier transform on both sides of the equation in the sense of generalized function. Then,
\begin{align*}
    \mathcal{F}\left\{ \sum_{k=1}^n c_k \cdot \cos(a_k x) \right\} = \sum_{k=1}^n c_k \cdot \mathcal{F}\{\cos(a_k x)\}=0,
\end{align*}
where $\mathcal{F}$ represents the Fourier transform of function. Since
\begin{align*}
    \mathcal{F}\{\cos(a_k x)\} = \pi \left[ \delta(\omega - a_k) + \delta(\omega + a_k) \right],
\end{align*}
then,
\begin{align*}
    \sum_{k=1}^n c_k \pi \left[ \delta(\omega - a_k) + \delta(\omega + a_k) \right] = 0.
\end{align*}

The $\delta (\omega-a_k) $ corresponding to different $a_k $ do not overlap with each other in the frequency domain. In other words, in generalized function theory, $\{\delta (\omega - a_k) \}_{k=1}^{n}$ is linearly independent for any $a_k$. Hence, $\forall k$
\begin{align*}
    c_k \pi \left[ \delta(\omega - a_k) + \delta(\omega + a_k) \right] = 0. \quad 
\end{align*}

From this, it can be inferred that $c_k=0$ holds for all $k $. Hence, $G_x$ is a linearly independent set of functions about $\bm{w_1}$.   

In addition, in Equation \eqref{380}, $\bm{w_2}$ serves as a linear parameter. Its different values are selected mainly to enhance the numerical stability of the method.

We have provided an efficient method for constructing linearly independent kernel functions, but the way to generate such kernel functions is not unique. In practical applications, these homogeneous constraints can also be constructed through other different ways. For example, another way  is using the center of the function $\bm{c}=(c_1,c_2,c_3)$, let 
\begin{align*}
&G^{\bm{c}}=\left(\dfrac{1}{\bm{r}},\dfrac{1}{\bm{r}},\dfrac{1}{\bm{r}}\right),\\
    &r(x,y,z)=||(x,y,z)-(c_1,c_2,c_3)||,
\end{align*}
where $||\cdot||$ represents the $L_2$ norm in $\mathbb{R}^3$. The detail process of construction can refer to \cite{gotsman2024linear}.


\subsection{\textbf{Discretization and Constructing Linear System}}
After constructing the constraints, we then  discretize them to the linear system. From the Equation \eqref{1},
\begin{align*}
    c_i=\int_{\partial \Omega}\bm{\overline{F}}_{i;\varepsilon}(\bm{x}) \cdot \bm{n}(\bm{x}) \d S \approx \sum_{j=1}^{M}\bm{\overline{F}}_{i;\varepsilon}(\bm{p}_j) \cdot \bm{n}_{\bm{p}_j} \sigma_{\bm{p}_j}.
\end{align*}


 In the sum, $\bm{\overline{F}}_{i;\varepsilon}(\bm{p}_i) $ are known variables, and \textbf{the only unknowns are the normal $\bm{n}_{\bm{p}_{j}}$ and area elements $\sigma_{\bm{p}_{j}}$}, which is similar to \cite{2022PGR}.  We denote the $3$-dimensional vector
\begin{equation}\label{LSE}
    \bm{\mu}_{j}=(\mu_{j,1},\mu_{j,2},\mu_{j,3})  \triangleq \bm{n}_{\bm{p}_{j}} \sigma_{\bm{p}_{j}}
\end{equation}
to estimate area and normal information of $ \bm{p}_{j}$, called linearized surface element (LSE). Then, the calculation of coefficients $c_i$ has a discrete form $A\bm{\mu}$ and the indicator function can be represented as
\begin{align}\label{chi}
    \overline{\chi}(\bm{x})=\sum_{j,k}\psi^{\bm{e}}_{j,k}(\bm{x}) \cdot \left(\sum_{i=1}^{M}\bm{\overline{F}}^{\bm{e}}_{\varepsilon,j,k}(\bm{x}_i)\cdot\bm{\mu}_i \right).
\end{align}

Although the lack of outward normals prevents a direct estimation of $\bm{\mu}_{i}$, we can take them as unknown variables. Therefore, for an input point cloud of $M$ points, the number of unknown parameters is $3M$.

Firstly, the property that the indicator function is $\frac{1}{2}$ at input points can be discretized to construct the non-homogeneous constraints. We denote it as
\begin{align*}
    B_{f}(\mathcal{P}) A(\bm{p}_i;\mathcal{P})\bm{\mu}_i=\dfrac{1}{2}, \ i=1,2,\cdots M.
\end{align*}

In response to the insufficient quantity, we construct more homogeneous constraints based on the previous analysis in Equation \eqref{h}. In detail, we randomly select $N_{h}$ different sets of parameters $\bm{w_1}=(w_{1,1},w_{1,2},w_{1,3}) \in \mathbb{R}^3$,  $\bm{w_2}=(w_{2,1},w_{2,2},w_{2,3}) \in \mathbb{R}^3$ and take $\bm{\mu_{i}}$ as unknown variables and the constraints can be represented as 
\begin{align*}
    H_{G}(\bm{w}_{1}^{j},\bm{w}_{2}^{j}) \bm{\mu}_i=0, \ i=1,2,\cdots M ,\ j=1,2,\cdots N_{h}.
\end{align*}

By combining the above constraints, we can obtain the final equation system
\begin{align}\label{BA}
    \begin{bmatrix}
        B_{f}A\\
         H_{G}
    \end{bmatrix}\bm{\mu}=\begin{bmatrix}
                    \bm{b}_1\\
                    \bm{0}
                \end{bmatrix},
\end{align}
where $\bm{b}_1$=$\dfrac{1}{2}\in \mathbb{R}^{M\times 1}$
and denote it as $B\bm{\mu}=\bm{b}$ for brevity.

\subsection{\textbf{Solving the Linear System}}
After determining the strategy for constructing equations, the following subsection explains how to obtain the point cloud’s normal and complete the reconstruction task.

\paragraph{$N_{h} < 2 M$}
Under such circumstances, the matrix $B$  is not a square and the system \eqref{BA} is under-determined. The solution is not unique. Then, we try to find the minimal-norm solution:

\begin{align}\label{min}
\mathop{ \min }\limits_{\bm{\mu}} ||\bm{\mu}||_{2}^2 \quad  \text{subject to } B\bm{\mu}=\bm{b}.
\end{align}

In addition, $B$ may be ill-conditioned and lead to a numerically unstable solution. Since the solution of optimization problem  \eqref{min} is $B^T(BB^T)^{-1}\bm{b}$, we first assume $\bm{\mu}$ has the form $\bm{\mu}=B^T\bm{\xi}$. Then, the  optimization problem  \eqref{min} can be equivalently written as

\begin{align}\label{min2}
\mathop{ \min }\limits_{\bm{\mu}',\bm{\xi}} ||\bm{\mu}'-B^T\bm{\xi}||_{2}^2 \quad  \text{subject to } B\bm{\mu}'=\bm{b},\bm{\mu}=B^T\bm{\xi}.
\end{align}

To avoid the numerical instability mentioned above and to alleviate the possible interference of noise, we
apply regularization to the intermediate variable $\bm{\xi}$ based on the formulation \eqref{min2}:

\begin{align}\label{min3}
\mathop{ \min }\limits_{\bm{\mu}',\bm{\xi}} ||\bm{\mu}'-B^T\bm{\xi}||_{2}^2 + +||\Gamma \bm{\xi}||_{2}^{2}  \quad  \text{subject to } B\bm{\mu}'=\bm{b},\bm{\mu}=B^T\bm{\xi},
\end{align}
where $\Gamma$ is a matrix with $M$ columns, intended for regularization.

\begin{theorem}[\textbf{minimal-norm solution}]\label{TH3}
	The solution for optimization problem \eqref{min3} needs to satisfy $\bm{\xi}=(BB^T+\Gamma^T\Gamma)^{-1}\bm{b}$, and $\bm{\mu}=B^T\bm{\xi}$.
\end{theorem}
  \begin{proof}
  The equivalence can be  proved by the Lagrange multiplier method (LMM) \cite{bertsekas2014constrained}, and let 
  \begin{align*}
      f(\bm{\lambda},\bm{\xi},\bm{\mu})=\dfrac{1}{2}(||\bm{\mu}-B^T\bm{\xi}||^2_2+||\Gamma\bm{\xi}||_{2}^{2})+\bm{\lambda}^T(B\bm{\mu}-\bm{b}),
  \end{align*}
  then the KKT condition of optimization problem \eqref{min3} is
  \begin{equation}
  \begin{cases}
      &\dfrac{\partial f}{\partial \bm{\lambda}}=B\bm{\mu}'-\bm{b}=0\\
       &\dfrac{\partial f}{\partial \bm{\xi}}=BB^T\bm{\xi}-B\bm{\mu}'+\Gamma^T\Gamma\bm{\xi}\\
        &\dfrac{\partial f}{\partial \bm{\mu}'}=\bm{\mu}'-B^T\bm{\xi}+B^T\bm{\lambda}.\\
    \end{cases}
  \end{equation}

  From the first and second lines, we can get $(BB^T+\Gamma^T\Gamma)\bm{\xi}=\bm{b}$. Hence, $\bm{\xi}=(BB^T+\Gamma^T\Gamma)^{-1}\bm{b}$. 
  \end{proof}

  Thus, we construct the equations and can solve it using the conjugate gradient method \cite{nazareth2009conjugate} to avoid the calculations of matrix inversion. 

