\paragraph{\textbf{$N_{h} \geqslant 2 M$}}
At this point, the equation system becomes determined or even overdetermined. Hence, we seek the least squares solution of it. That is

\begin{align}\label{LSS}
\mathop{ \min }\limits_{\bm{\mu}} ||B\bm{\mu}-\bm{b}||_{2}^{2}.
\end{align}  

To avoid the numerical instability mentioned above and to alleviate the possible influence of noise, we
apply regularization to optimization problem \eqref{LSS} and to be
\begin{align}\label{LSS2}
\mathop{ \min }\limits_{\bm{\mu}} ||B\bm{\mu}-\bm{b}||_{2}^{2}+||\Gamma \bm{\mu}||_{2}^{2}.
\end{align}   

\begin{theorem}[\textbf{least-squares solution}]\label{TH4}
	The solution for  optimization problem  \eqref{LSS} is $\bm{\mu}=(B^TB+\Gamma^T\Gamma)^{-1}B^T\bm{b}$.
\end{theorem}
  \begin{proof}
  Let $f(\mu)=||B\bm{\mu}-\bm{b}||_{2}^{2}+||\Gamma \bm{\mu}||_{2}^{2}$, then $\nabla f=0$:
  \begin{align*}
      &B^{T}(B\bm{\mu}-\bm{b})+\Gamma^T\Gamma\bm{\mu}=0\\
      &(B^TB+\Gamma^T\Gamma)\bm{\mu}=B^T\bm{b}.
  \end{align*}

  Hence,
  \begin{align*}
      \bm{\mu}=(B^TB+\Gamma^T\Gamma)^{-1}B^T\bm{b}.
  \end{align*}

  On the other hand, $\forall \bm{y} \in \mathbb{R}^{3M}$,
  \begin{align*}
      &||B(\bm{\mu}+\bm{y})-\bm{b}||_{2}^2+||\Gamma(\bm{\mu}+\bm{y})||_{2}^2\\
      &=||B\bm{\mu}-\bm{b}||_{2}^{2}+2\bm{y}^TB^T(B\bm{\mu}-\bm{b})+||B\bm{y}||_{2}^{2}+||\Gamma \bm{\mu}||_{2}^{2}+||\Gamma \bm{y}||_{2}^{2}+2\bm{y}^T\Gamma^T\Gamma\bm{\mu}\\
      &=||B\bm{\mu}-\bm{b}||_{2}^{2}+||\Gamma \bm{\mu}||_{2}^{2}+||B\bm{y}||_{2}^{2}+||\Gamma \bm{y}||_{2}^{2}+2\bm{y}^T(B^TB\bm{\mu}+\Gamma^T\Gamma\bm{\mu}-B^T\bm{b})\\
      &=||B\bm{\mu}-\bm{b}||_{2}^{2}+||\Gamma \bm{\mu}||_{2}^{2}+||B\bm{y}||_{2}^{2}+||\Gamma \bm{y}||_{2}^{2}\\
      &\geqslant ||B\bm{\mu}-\bm{b}||_{2}^{2}+||\Gamma \bm{\mu}||_{2}^{2}.
  \end{align*}
  \end{proof}  

Given that the coefficient matrix is symmetric, we can employ the conjugate gradient method for its solution instead of calculating the inverse matrix. Like PGR, we use $N_{h}=2M$ to solve the problem and  the formulation \eqref{LSS2} is equal to the formulation \eqref{min3} in this situation.
Uniform regularization does not work well with nonuniform sampling. We discover choosing $\Gamma^T\Gamma$ as a multiple of the diagonal of $B^T B$ adapts to varying sampling density
\begin{align*}
    \Gamma^T\Gamma=\alpha\cdot 10M \cdot \diag(B^TB),
    \end{align*}
where $\alpha$ is a hyperparameter and $M$ is the number of input point clouds.    
Adding such regularization can lead to the better orientations and reconstructions, which is shown in \cref{5.2}.

