\begin{algorithm}[htbp]
\caption{Wavelet-based Global Orientation and Surface Reconstruction}
\label{algorithm2}
\textbf{Input:} Unoriented point cloud $\mathcal{P}$, wavelet function's maximum depth $D_{\max}$, smooth width $\varepsilon$, the number of homogeneous constraint $N_{h}$, regularization factor $\alpha$. \\
\textbf{Output:} Oriented point cloud $(\mathcal{P},\mathcal{N})$, a watertight surface $M$ approximating the points.
\begin{enumerate}
\item Initialize $\bm{\mu}=\bm{0}$, $\bm{b}_1=\frac{\mathbbm{1}}{2}$.
\item \textit{// Mollify the wavelet basis functions}
\item For $j = 1$ to $D_{\max}$:
\begin{enumerate}
\item Calculate the mollifying kernel function $K_{2^j \varepsilon}(t)$;
\item Calculate $\overline{\psi}_{\varepsilon,j}=2^{\frac{j}{2}}\overline{\psi}_{2^j \varepsilon}(2^j x)$;
\end{enumerate}
\item \textit{// The homogeneous and non-homogeneous constraint}
\item Construct the homogeneous constraints $H\bm{\mu}=\bm{b}_2$, $\bm{b}_2=\bm{0}$ by Equation \eqref{BA};
\item Construct the non-homogeneous constraints $B_{f}A \bm{\mu}=\bm{b}_1$;
\item Let $B=\begin{bmatrix} B_{f}A \\ H \end{bmatrix}$, $\bm{b}=\begin{bmatrix} \bm{b}_1 \\ \bm{b}_2 \end{bmatrix}$;
\item \textit{// Conjugate gradient (CG) for the LSE}
\item If $N_{h}\leqslant 2|\mathcal{P}|$:
\begin{enumerate}
\item Calculate $B_{c}=BB^{T}+\text{diag}(BB^T)$;
\item Solve $B_{c}\bm{\xi}=\bm{b}$ for $\bm{\xi}$ using conjugate gradient method;
\item Set $\bm{\mu}= B^T \bm{\xi}$
\end{enumerate}
\item Else:
\begin{enumerate}
\item Calculate $B_{c}=B^TB+\text{diag}(B^TB)$;
\item Calculate $\bm{d}=B^T\bm{b}$;
\item Solve $B\bm{\mu}=\bm{d}$ for $\bm{\mu}$ using conjugate gradient method;
\end{enumerate}
\item \textit{// Orientation and surface reconstruction}
\item Calculate normals $\bm{n}_{i}=\dfrac{\bm{\mu}_i}{||\bm{\mu}_i||_{2}}$, and output oriented points $(\mathcal{P},\mathcal{N})$;
\item Calculate the iso-value as $v_{\text{iso}} = \text{average}\left(A(\mathcal{P}; \mathcal{P})\bm{\mu}\right)$;
\item Obtain the values of query points as $\mathcal{Q}.\text{value} =A(\mathcal{Q}; \mathcal{P})\bm{\mu}$;
\item Reconstruct surface $M$ using marching cubes by $\mathcal{Q}.\text{value}$ and $v_{\text{iso}}$.
\end{enumerate}
\end{algorithm}

