\section{The compact support and orthogonality of Db4 wavelet bases}
\label{Appendix}
\begin{theorem}[\textbf{Construction orthonormal wavelet sequences}]\label{th1}
	Let $\{V_{j}\}$ be an $MRA$ with scaling function $\varphi(x)$ and scaling filter $h(k)$, where $V_{j}=\{f(x):f(x)=2^{\frac{j}{2}}\varphi_{0}(2^{j}x-k),\varphi_{0}(x)\in V_{0}\}$, $V_{0}=\overline{\text{span}}\{\varphi(x-n)\},n \in \mathbb{Z}$.
	Define the wavelet filter $g(k)$ by $g(k)=(-1)^{k}\overline{h}(1-k)$, and the wavelet $\psi(x)$ by 
	$\psi(x)=\sum_{k}g(k)2^{1/2}\varphi(2x-k)$. Then $\{\psi_{j,k}(x)\}_{j,k \in \mathbb{Z}}$ is a set of one-dimensional orthogonal sequences, where $\psi_{j,k}(x)=2^{\frac{j}{2}}\psi(2^{j}x-k)$.  Alternatively, given any $J \in \mathbb{Z}$,$\{\varphi_{J,k}(x)\}_{k \in \mathbb{Z}} \bigcup \{\psi_{j,k}(x)\}_{k \in \mathbb{Z},j\geqslant J}$ is a set of one-dimensional orthogonal sequences, where $\varphi_{j,k}(x)=2^{\frac{j}{2}}\varphi(2^{j}x-k)$.
	\end{theorem}

	\begin{theorem}[\textbf{The support of the scaling function}]\label{th12}
	Suppose that $h(k)$ is a finite QMF, let $m_{0}(\gamma)$ be given by $m_{0}(\gamma)=\frac{1}{\sqrt{2}}\sum_{k}h(k)e^{-2\pi \mathrm{i} k \gamma}$, and holds that there is a number $c > 0$ such that $|m_{0}|(\gamma) \geqslant c $ for $|\gamma| \leqslant \frac{1}{4}$. Suppose that for some $N\in \mathbb{N}$, $h(k)$ has length $2N$. Then, the scaling function $\varphi(x)$ defined by the two-scale expansion equation is supported in an interval of length $2N- 1$.
	\end{theorem}
