\begin{example} \label{ex5.4}
	This example illustrates the performance of the proposed RBTLSE method compared with the existing RBLSE method~\cite{ahmad2024solutions} in solving inconsistent equality-constrained reduced biquaternion matrix equations (RBMEs). 

	Specifically, we generate exact real and complex solutions to consistent equality-constrained RBMEs. Perturbations are then introduced to simulate inconsistencies, and we compute approximate solutions using both RBTLSE and RBLSE methods. The quality of the computed solutions is assessed using the Frobenius norm error with respect to the original exact solution. 

	The testing is carried out under two scenarios for each setting:  
	\begin{itemize}
	\item perturbations in both the coefficient and right-hand side matrices, and  
	\item perturbations only in the right-hand side matrix.  
	\end{itemize}
	The errors are recorded for increasing problem sizes to compare the performance of the two methods.
	\begin{enumerate}
		\item[\rm (i)] \textbf{Real solutions:}

		Let $E= E_0+E_1\i+E_2\j+E_3\k \in \QR^{m \times 50}$ with $(m>50)$, where each component matrix is defined as $E_i= \texttt{randn}(m,50) \in \R^{m \times 50}$. Similarly, define $C= C_0+C_1\i+C_2\j+C_3\k \in \QR^{10 \times 50}$, where $C_i= \texttt{randn}(10,50) \in \R^{10 \times 50}$ for $i=0,1,2,3$. Let $X_1$ be a randomly generated real matrix given by $X_1 = \texttt{randn}(50,35) \in \R^{50 \times 35}$.

		Using these matrices, we construct $F=E_0X_1+E_1X_1\i+E_2X_1\j+E_3X_1\k$ and $D=C_0X_1+C_1X_1\i+C_2X_1\j+C_3X_1\k$. Clearly, the equality-constrained RBME
		\begin{equation*}
			EX = F, ~ \textrm{subject to} ~ CX=D
		\end{equation*}
		is consistent, with $X_1$ being its exact real solution.

		To evaluate solution accuracy under inconsistencies, we perturb $E$ and $F$ to obtain:
		\[
		AX \approx B, ~ \text{subject to} ~ CX = D,
		\]
		where $A = E + dE$, $B = F + dF$, and $X \in \R^{50 \times 35}$.

		\textbf{Case 1:} Perturbations in both $E$ and $F$.

		Generate $G = \texttt{rand}(85,85)$ and set $H = 0.01 \cdot \texttt{rand}(m,85) \cdot G$. Define
		\begin{align*}
			dE &= H(:,1\!:\!50) + H(:,1\!:\!50)\i + H(:,1\!:\!50)\j + H(:,1\!:\!50)\k, \\
			dF &= H(:,51\!:\!85) + H(:,51\!:\!85)\i + H(:,51\!:\!85)\j + H(:,51\!:\!85)\k.
		\end{align*}

		\textbf{Case 2:} Perturbation only in $F$.

		Generate $G = \texttt{rand}(35,35)$ and set $H = 0.01 \cdot \texttt{rand}(m,35) \cdot G$. Define
		\begin{align*}
			dE &= 0, \\
			dF &= H + H\i + H\j + H\k.
		\end{align*}

		In both cases, we compute approximate real solutions $X_{RT}$ and $X_{RL}$ using the RBTLSE (Algorithm~\ref{alg3}) and RBLSE methods~\cite[Algorithm $1$]{ahmad2024solutions}, respectively.

		\item[\rm (ii)] \textbf{Complex solutions:}

		Let $M=M_1+M_2\mathbf{j} \in \QR^{m \times 50}$ with $(m>50)$, where each component matrix is defined as $M_i=\texttt{randn}(m,50)+\texttt{randn}(m,50)\mathbf{i}$ for $i=1,2$. Similarly, define $R= R_1+R_2\mathbf{j} \in \QR^{10 \times 50}$, where $R_i=\texttt{randn}(10,50)+\texttt{randn}(10,50)\mathbf{i}$ for $i=1,2$. Let $X_2$ be a randomly generated complex matrix given by $X_2 = \texttt{randn}(50,35)+\texttt{randn}(50,35)\mathbf{i} \in \mathbb{C}^{50 \times 35}$. 

		Using these matrices, we construct $N=M_1X_2+M_2X_2 \j$ and $S=R_1X_2+R_2X_2 \j$. Clearly, the equality-constrained RBME
		\begin{equation*}
			MX = N, ~ \textrm{subject to} ~ RX=S
		\end{equation*}
		is consistent, with $X_2$ being its exact complex solution.

		Perturb $M$ and $N$ to obtain the inconsistent system:
		\[
		PX \approx Q, ~ \text{subject to} ~ RX = S,
		\]
		where $P = M + dM$, $Q = N + dN$, and $X \in \C^{50 \times 35}$.

		\textbf{Case 1:} Perturbations in both $M$ and $N$.

		Generate $T = \texttt{rand}(85,85) + \texttt{rand}(85,85)\i$, $I = \texttt{rand}(m,85) + \texttt{rand}(m,85)\i$, and set $J = 0.01 \cdot IT$. Define
		\begin{align*}
			dM &= J(:,1\!:\!50) + J(:,1\!:\!50)\j, \\
			dN &= J(:,51\!:\!85) + J(:,51\!:\!85)\j.
		\end{align*}

		\textbf{Case 2:} Perturbation only in $N$.

		Generate $T = \texttt{rand}(35,35) + \texttt{rand}(35,35)\i$, $I = \texttt{rand}(m,35) + \texttt{rand}(m,35)\i$, and set $J = 0.01 \cdot IT$. Define
		\begin{align*}
			dM &= 0, \\
			dN &= J + J\j.
		\end{align*}

		For both scenarios, we compute the complex solutions $X_{CT}$ and $X_{CL}$ using the RBTLSE (Algorithm~\ref{alg1}) and RBLSE methods~\cite[Algorithm $2$]{ahmad2024solutions}, respectively.
	\end{enumerate}

	\textbf{Note:} $X_1$ and $X_2$ represent the most accurate real and complex solutions for the original consistent systems. For evaluation, we define the error metrics:
	\[
	\epsilon_{RT} = \|X_{RT} - X_1\|_F, ~
	\epsilon_{RL} = \|X_{RL} - X_1\|_F, ~
	\epsilon_{CT} = \|X_{CT} - X_2\|_F, ~
	\epsilon_{CL} = \|X_{CL} - X_2\|_F.
	\]
	We report these metrics for varying values of $m$ by averaging results over 20 independent trials for each $m$.
\end{example}

