\section{Calculation of the annihilation amplitude integral}\label{app1}
This appendix contains an outline of the procedure followed to evaluate the annihilation amplitude in the independent particle approximation, $A^{(0)}_{n\varepsilon}(\mathbf{P})$. 
Substituting the Gaussian expansions of the electron and positron wavefunctions from Equations \ref{eq:gaussian_expn} in Equation~\ref{eq:ann_amp} yields the following expression for the annihilation amplitude:
\begin{equation}
A^{(0)}_{n\varepsilon}(\mathbf{P}) = \sum_i \sum_j C_i^{\varepsilon} C^{(n)}_j \prod_{\mu=x,y,z} I^{(\mu)}_{n; i j}(P_\mu) , \label{eq5}
\end{equation}
where total momentum $\mathbf{P}=(P_x,P_y,P_z)$, the product over $\mu = x,y,z$ accounts for the components of the wavefunction in each of the three Cartesian directions, the sum over $i$ ($j$) runs over all positron (electron) basis functions, $C_i^{\varepsilon}$ and $C_j^{(n)}$ are expansion coefficients, and
\begin{align}
I^{(\mu)}_{n; i j}(P_\mu)&=\!\!\int_{-\infty}^\infty \!\!\!(\mu\!-\!\mu_i)^{n^\mu_i}\! (\mu\!-\!\mu_j)^{n^\mu_j} e^{-iP_\mu\mu} e^{-\zeta_i(\mu\!-\!\mu_i)^2}e^{-\zeta_j(\mu\!-\!\mu_j)^2}\!d\mu, \\
&=\!e^{-\lambda_{ij}(\mu_i\!-\!\mu_j)^2}\int_{-\infty}^\infty \!(\mu\!-\!\mu_i)^{n^\mu_i} \!(\mu\!-\!\mu_j)^{n^\mu_j} e^{-iP_\mu\mu}  e^{-(\zeta_i+\zeta_j)(\mu\!-\!\mu_{ij})^2}\!d\mu,
\label{def_int_i}\end{align}
where $n_i^{\mu}$ are angular momentum components, $\zeta_i$ are Gaussian exponents, $\mu_i$ are components of the centres of the Gaussian functions, and the last equation is obtained using the Gaussian product rule with
\begin{equation}
\lambda_{ij}=\frac{\zeta_i\zeta_j}{\zeta_i+\zeta_j},\qquad \mu_{ij}=\frac{\zeta_i\mu_i+\zeta_j\mu_j}{\zeta_i+\zeta_j}.
\end{equation}

To solve the integral in Equation~\ref{def_int_i}, we make a Hermite expansion of the polynomial factors:
\begin{align}\label{eq:hermite_expansion}
(\mu-\mu_i)^{n^\mu_i} (\mu-\mu_j)^{n^\mu_j}   = \sum_{s^\mu_{ij}=0}^{n^\mu_i+n^\mu_j} E_{s^\mu_{ij}}^{n^\mu_i n^\mu_j} \Lambda_{s^\mu_{ij}}(\mu-\mu_{ij};\zeta_i+\zeta_j),
\end{align}
where 
\begin{equation}
    \Lambda_{s^\mu_{ij}}(\mu-\mu_{ij};\zeta_i+\zeta_j)=(\zeta_i+\zeta_j)^{s^\mu_{ij}/2} H_{s^\mu_{ij}}\left[(\zeta_i+\zeta_j)^{1/2}(\mu-\mu_{ij})\right]
\end{equation}
and $H_k$ is the $k^{\rm th}$ Hermite polynomial:
\begin{align}
H_k(z)=(-1)^k e^{z^2} \frac{d^k}{dz^k} e^{-z^2}.
\end{align}
The expansion coefficients $E_{s^\mu_{ij}}^{n^\mu_i n^\mu_j}$  satisfy the McMurchie-Davidson recurrence relations \cite{McMurchie1978}:
\begin{align}
E_{s^\mu_{ij}}^{n^\mu_i+1, n^\mu_j}=\frac{1}{2(\zeta_i+\zeta_j)} E_{s^\mu_{ij}-1}^{n^\mu_i n^\mu_j} + (\mu_{ij}-\mu_i) E_{s^\mu_{ij}}^{n^\mu_i n^\mu_j} + (s^\mu_{ij}+1) E_{s^\mu_{ij}+1}^{n^\mu_i n^\mu_j} , \\
E_{s^\mu_{ij}}^{n^\mu_i, n^\mu_j+1}=\frac{1}{2(\zeta_i+\zeta_j)} E_{s^\mu_{ij}-1}^{n^\mu_i n^\mu_j} + (\mu_{ij}-\mu_j) E_{s^\mu_{ij}}^{n^\mu_i n^\mu_j} + (s^\mu_{ij}+1) E_{s^\mu_{ij}+1}^{n^\mu_i n^\mu_j} , 
\end{align}
with $E^{00}_0=1$.
Substituting Equation~\ref{eq:hermite_expansion} into Equation~\ref{def_int_i} yields
\begin{align}
I^{(\mu)}_{n; i j}(P_\mu)
&= e^{-\lambda_{ij}(\mu_i-\mu_j)^2}\sum_{s^\mu_{ij}=0}^{n^\mu_i+n^\mu_j} E_{s^\mu_{ij}}^{n^\mu_i n^\mu_j} 
\int_{-\infty}^\infty  e^{-iP_\mu\mu}   \Lambda_{s^\mu_{ij}}(\mu-\mu_{ij};\zeta_i+\zeta_j)e^{-(\zeta_i+\zeta_j)(\mu-\mu_{ij})^2} \,d\mu. \label{eq:tfygv}
\end{align}

Now, a further transformation can be made using the identity
\begin{align}
 \Lambda_{s^\mu_{ij}}(\mu-\mu_{ij};\zeta_i+\zeta_j)e^{-(\zeta_i+\zeta_j)(\mu-\mu_{ij})^2}= \left( \frac{\partial}{\partial\mu_{ij}} \right)^{s^\mu_{ij}}e^{-(\zeta_i+\zeta_j)(\mu-\mu_{ij})^2},\label{eq:Lambda_deriv}
\end{align}
so that we can rewrite Equation~\ref{eq:tfygv} as
\begin{align}
I^{(\mu)}_{n; i j}(P_\mu)
&=e^{-\lambda_{ij}(\mu_i-\mu_j)^2} \sum_{s^\mu_{ij}=0}^{n^\mu_i+n^\mu_j} E_{s^\mu_{ij}}^{n^\mu_i n^\mu_j} \left( \frac{\partial}{\partial\mu_{ij}} \right)^{s^\mu_{ij}} 
\int_{-\infty}^\infty  e^{-iP_\mu\mu}  e^{-(\zeta_i+\zeta_j)(\mu-\mu_{ij})^2}\,d\mu .\label{eq:ann_amp_int1}
\end{align}
We now make a slight modification to the integral in Equation \ref{eq:ann_amp_int1} to match the form of a common integral encountered in quantum field theory by taking a constant factor of $\exp(-iP_{\mu}\mu_{ij})$ outside of the integral:
\begin{align}
I^{(\mu)}_{n; i j}(P_\mu)
&=e^{-\lambda_{ij}(\mu_i-\mu_j)^2}\sum_{s^\mu_{ij}=0}^{n^\mu_i+n^\mu_j} E_{s^\mu_{ij}}^{n^\mu_i n^\mu_j} \left( \frac{\partial}{\partial\mu_{ij}} \right)^{s^\mu_{ij}} 
e^{-iP_\mu \mu_{ij}}
\int_{-\infty}^\infty  e^{-iP_\mu(\mu-\mu_{ij})}  e^{-(\zeta_i+\zeta_j)(\mu-\mu_{ij})^2}\,d\mu .
\end{align}
Now the integral can be solved using the identity
\begin{gather}
\int_{-\infty}^\infty  e^{-iP_\mu\xi}  e^{-(\zeta_i+\zeta_j)\xi^2}\,d\xi = \sqrt{\frac{\pi}{\zeta_i+\zeta_j}}\, e^{-P_\mu^2/4(\zeta_i+\zeta_j)},
\end{gather}
and we have
\begin{align}
I^{(\mu)}_{n; i j}(P_\mu) = 
 \sqrt{\frac{\pi}{\zeta_i+\zeta_j}} \,
e^{-\lambda_{ij}(\mu_i-\mu_j)^2}
e^{-P_\mu^2/4(\zeta_i+\zeta_j)}
 \sum_{s^\mu_{ij}=0}^{n^\mu_i+n^\mu_j} E_{s^\mu_{ij}}^{n^\mu_i n^\mu_j} 
\left( \frac{\partial}{\partial\mu_{ij}} \right)^{s^\mu_{ij}} 
e^{-iP_\mu \mu_{ij}} . \label{eq:ctvybunh}
\end{align}

Finally, we substitute Equation~\ref{eq:ctvybunh} into Equation~\ref{eq5} to obtain the expression for the annihilation amplitude:
\begin{equation}
A_{n\varepsilon}^{(0)}(\mathbf P) = \sum_i \sum_j C_i^{\varepsilon} C^{(n)}_j \prod_{\mu=x,y,z} \sqrt{\frac{\pi}{\zeta_i+\zeta_j}} \,
e^{-\lambda_{ij}(\mu_i-\mu_j)^2}
e^{-P_\mu^2/4(\zeta_i+\zeta_j)}
 \sum_{s^\mu_{ij}=0}^{n^\mu_i+n^\mu_j} E_{s^\mu_{ij}}^{n^\mu_i n^\mu_j} 
\left( \frac{\partial}{\partial\mu_{ij}} \right)^{s^\mu_{ij}} 
e^{-iP_\mu \mu_{ij}}. \label{ann_amp}
\end{equation}


\section{Calculating the {$\gamma$} spectrum}\label{app:gammaspectrum}

This appendix outlines the solution of the integral in Equation (\ref{eqn:gamspec}). First, we take the square modulus of Equation~\ref{ann_amp} and integrate over solid angle  $\Omega_{\mathbf P}$:
\begin{align}
\int\lvert A^{(0)}_{n\varepsilon}(\mathbf{P})\rvert^2 \,d\Omega_{\mathbf P}
&= \sum_{i,j,i',j'} C_i^{\varepsilon} C_j^{(n)} C_{i'}^{\varepsilon *} C_{j'}^{(n)*}
\int I^{(x)}_{n;ij}(P_x) I^{(y)}_{n;ij}(P_y) I^{(z)}_{n;ij}(P_z) 
I^{(x)*}_{n;i'j'}(P_x) I^{(y)*}_{n;i'j'}(P_y) I^{(z)*}_{n;i'j'}(P_z)\,d\Omega_{\mathbf P} \notag\\
&= \sum_{i,j,i',j'} C_i^{\varepsilon} C_j^{(n)} C_{i'}^{\varepsilon *} C_{j'}^{(n)*}
\frac{\pi^3}{[(\zeta_i+\zeta_j)(\zeta_{i'}+\zeta_{j'})]^{3/2}} 
e^{-\lambda_{ij}\lvert \mathbf r_i-\mathbf r_j\rvert^2}
e^{-\lambda_{i'j'}\lvert \mathbf r_{i'}-\mathbf r_{j'}\rvert^2} 
\notag\\
&\quad{}\times e^{-P^2/4(\zeta_i+\zeta_j)} e^{-P^2/4(\zeta_{i'}+\zeta_{j'})}\notag\\
&\quad{}\times \sum_{\substack{s^x_{ij},s^y_{ij},s^z_{ij},\\ s^x_{i'j'},s^y_{i'j'},s^z_{i'j'}}}
E_{s^x_{ij}}^{n^x_i n^x_j} 
E_{s^y_{ij}}^{n^y_i n^y_j} 
E_{s^z_{ij}}^{n^z_i n^z_j} 
E_{s^x_{i'j'}}^{n^x_{i'} n^x_{j'}} 
E_{s^y_{i'j'}}^{n^y_{i'} n^y_{j'}} 
E_{s^z_{i'j'}}^{n^z_{i'} n^z_{j'}} \notag\\
&\quad{}\times 
\left( \frac{\partial}{\partial x_{ij}} \right)^{s^x_{ij}} 
\left( \frac{\partial}{\partial y_{ij}} \right)^{s^y_{ij}} 
\left( \frac{\partial}{\partial z_{ij}} \right)^{s^z_{ij}} 
\left( \frac{\partial}{\partial x_{i'j'}} \right)^{s^x_{i'j'}} 
\left( \frac{\partial}{\partial y_{i'j'}} \right)^{s^y_{i'j'}} 
\left( \frac{\partial}{\partial z_{i'j'}} \right)^{s^z_{i'j'}} \notag\\
&\quad{}\times 
\int \exp(-i \mathbf P \cdot \mathbf R_{iji'j'})\,d\Omega_{\mathbf P}, \label{eq:hsfhnfbg}
\end{align}
where $P^2=P_x^2+P_y^2+P_z^2$ and $\mathbf R_{iji'j'}=\mathbf r_{ij}-\mathbf r_{i'j'}=(x_{ij}-x_{i'j'},y_{ij}-y_{i'j'},z_{ij}-z_{i'j'})$.
For $\mathbf R_{iji'j'}=\boldsymbol 0$, the integral at the end of Equation~\ref{eq:hsfhnfbg} is
\begin{align}
\int \exp(-i \mathbf P \cdot \mathbf R_{iji'j'})\,d\Omega_{\mathbf P} = \int d\Omega_{\mathbf P}=4\pi.
\end{align}

For $\mathbf R_{iji'j'}\neq\boldsymbol 0$ the integration is carried out analytically in spherical polar coordinates. The integrand depends only on the angle between $\mathbf{P}$ and $\mathbf{R}_{iji'j'}$, so we can choose to align the polar axis with $\mathbf R_{iji'j'}$:
\begin{align}
\int \exp (-i\mathbf P \cdot \mathbf R_{iji'j'})\,d\Omega_{\mathbf P} 
&= \int_0^{2\pi}\!\! \int_0^\pi \exp(-iPR_{iji'j'}\cos\theta_{\mathbf P}) \sin\theta_{\mathbf P} \, d\theta_{\mathbf P} \, d\phi_{\mathbf P}, \notag\\
&=2\pi \int_0^\pi \exp(-iPR_{iji'j'}\cos\theta_{\mathbf P}) \sin\theta_{\mathbf P} \, d\theta_{\mathbf P},\notag
\\&= \frac{4\pi}{PR_{iji'j'}} \sin PR_{iji'j'} ,
\end{align}
where $R_{iji'j'}=\lvert \mathbf R_{iji'j'} \rvert$.
Using the fact that the zeroth spherical Bessel function $j_0$ is given by $j_0(0)=1$, $j_0(z)=z^{-1}\sin z$ ($\lvert z \rvert>0$), we can write in general that
\begin{align}
\int \exp (-i\mathbf P \cdot \mathbf R_{iji'j'})\,d\Omega_{\mathbf P} = 4\pi j_0(PR_{iji'j'}). \label{eq:ctvybu}
\end{align}

Having found an expression for this integral, we now turn our attention to the partial
derivatives in Eqn.~\ref{eq:hsfhnfbg}.
By definition of $\mathbf R_{iji'j'}$, we have
\begin{align}
\frac{\partial}{\partial x_{ij}} &\equiv \frac{\partial}{\partial { X}_{iji'j'}} , 
&\frac{\partial}{\partial y_{ij}} &\equiv \frac{\partial}{\partial { Y}_{iji'j'}} , 
&\frac{\partial}{\partial z_{ij}} &\equiv \frac{\partial}{\partial { Z}_{iji'j'}} , \notag\\
\frac{\partial}{\partial x_{i'j'}} &\equiv -\frac{\partial}{\partial { X}_{iji'j'}}, 
&\frac{\partial}{\partial y_{i'j'}} &\equiv -\frac{\partial}{\partial { Y}_{iji'j'}},  
&\frac{\partial}{\partial z_{i'j'}} &\equiv -\frac{\partial}{\partial { Z}_{iji'j'}}, \label{eq:ctvygb}
\end{align}
where $X_{iji'j'}=x_{ij}-x_{i'j'}$, $Y_{iji'j'}=y_{ij}-y_{i'j'}$ and $Z_{iji'j'}=z_{ij}-z_{i'j'}$.

Substituting Eqns.~\ref{eq:ctvybu} and \ref{eq:ctvygb} into Eqn.~\ref{eq:hsfhnfbg}, we find
\begin{align}
\int \lvert A^{(0)}_{n\varepsilon}(\mathbf{P})\rvert^2 \,d\Omega_{\mathbf P}
&= \sum_{i,j,i',j'} C_i^{\varepsilon} C_j^{(n)} C_{i'}^{\varepsilon *} C_{j'}^{(n)*}
\frac{4\pi^4}{[(\zeta_i+\zeta_j)(\zeta_{i'}+\zeta_{j'})]^{3/2}} 
e^{-\lambda_{ij}\lvert \mathbf r_i-\mathbf r_j\rvert^2}
e^{-\lambda_{i'j'}\lvert \mathbf r_{i'}-\mathbf r_{j'}\rvert^2} 
\notag\\
&\quad{}\times e^{-P^2/4(\zeta_i+\zeta_j)} e^{-P^2/4(\zeta_{i'}+\zeta_{j'})}\notag\\
&\quad{}\times \sum_{\substack{s^x_{ij},s^y_{ij},s^z_{ij},\\ s^x_{i'j'},s^y_{i'j'},s^z_{i'j'}}}
E_{s^x_{ij}}^{n^x_i n^x_j} 
E_{s^y_{ij}}^{n^y_i n^y_j} 
E_{s^z_{ij}}^{n^z_i n^z_j} 
E_{s^x_{i'j'}}^{n^x_{i'} n^x_{j'}} 
E_{s^y_{i'j'}}^{n^y_{i'} n^y_{j'}} 
E_{s^z_{i'j'}}^{n^z_{i'} n^z_{j'}}
(-1)^{s^x_{i'j'}+s^y_{i'j'}+s^z_{i'j'}} \notag\\
&\quad{}\times 
\left( \frac{\partial}{\partial X_{iji'j'}} \right)^{s^x_{ij}+s^x_{i'j'}} 
\left( \frac{\partial}{\partial Y_{iji'j'}} \right)^{s^y_{ij}+s^y_{i'j'}} 
\left( \frac{\partial}{\partial Z_{iji'j'}} \right)^{s^z_{ij}+s^z_{i'j'}} 
j_0(PR_{iji'j'}). \label{eq;nbfihufvij}
\end{align}
To evaluate the partial derivatives, we define the following quantity:
\begin{align}
\mathfrak{j}_n(P,R_{iji'j'}) = \left( \frac{P}{R_{iji'j'}}\right)^n j_n(PR_{iji'j'}),\label{eq:jfrak_def}
\end{align}
noting that for zeroth order, we have $\mathfrak j_0(P,R_{iji'j'})=j_0(PR_{iji'j'})$. 
Equation~\ref{eq;nbfihufvij} becomes
\begin{align} \label{eq:gjffjjnf}
\int \lvert A^{(0)}_{n\varepsilon}(\mathbf{P})\rvert^2 \,d\Omega_{\mathbf P}
&= \sum_{i,j,i',j'} C_i^{\varepsilon} C_j^{(n)} C_{i'}^{\varepsilon *} C_{j'}^{(n)*}
\frac{4\pi^4}{[(\zeta_i+\zeta_j)(\zeta_{i'}+\zeta_{j'})]^{3/2}} 
e^{-\lambda_{ij}\lvert \mathbf r_i-\mathbf r_j\rvert^2}
e^{-\lambda_{i'j'}\lvert \mathbf r_{i'}-\mathbf r_{j'}\rvert^2} 
\notag\\
&\quad{}\times e^{-P^2/4(\zeta_i+\zeta_j)} e^{-P^2/4(\zeta_{i'}+\zeta_{j'})}\notag\\
&\quad{}\times \sum_{\substack{s^x_{ij},s^y_{ij},s^z_{ij},\\ s^x_{i'j'},s^y_{i'j'},s^z_{i'j'}}}
E_{s^x_{ij}}^{n^x_i n^x_j} 
E_{s^y_{ij}}^{n^y_i n^y_j} 
E_{s^z_{ij}}^{n^z_i n^z_j} 
E_{s^x_{i'j'}}^{n^x_{i'} n^x_{j'}} 
E_{s^y_{i'j'}}^{n^y_{i'} n^y_{j'}} 
E_{s^z_{i'j'}}^{n^z_{i'} n^z_{j'}}
(-1)^{s^x_{i'j'}+s^y_{i'j'}+s^z_{i'j'}} \notag\\
&\quad{}\times 
\left( \frac{\partial}{\partial X_{iji'j'}} \right)^{s^x_{ij}+s^x_{i'j'}} 
\left( \frac{\partial}{\partial Y_{iji'j'}} \right)^{s^y_{ij}+s^y_{i'j'}} 
\left( \frac{\partial}{\partial Z_{iji'j'}} \right)^{s^z_{ij}+s^z_{i'j'}} 
\mathfrak j_0(P,R_{iji'j'}) .
\end{align}
Now we calculate the partial derivatives of $\mathfrak j_n(P,R_{iji'j'})$ with respect to $X_{iji'j'}$, $Y_{iji'j'}$ and $Z_{iji'j'}$.
Using the identity
\begin{align}
\frac{d}{dz}\frac{j_n(z)}{z^n}=- \frac{j_{n+1}(z)}{z^n},
\end{align}
the relation $R_{iji'j'}= \left(X_{iji'j'}^2 + Y_{iji'j'}^2 + Z_{iji'j'}^2\right)^{1/2}$
and the chain rule, we can evaluate the partial derivative of $\mathfrak j_n(P,R_{iji'j'})$ with respect to $X_{iji'j'}$ 
\begin{align}
\frac{\partial \mathfrak j_n(P,R_{iji'j'})}{\partial X_{iji'j'}}
&= \frac{\partial R_{iji'j'}}{\partial X_{iji'j'}}  \frac{\partial \mathfrak j_n(P,R_{iji'j'})}{\partial R_{iji'j'}} ,\notag\\
&= \frac{X_{iji'j'}}{R_{iji'j'}} P^n \frac{\partial}{\partial R_{iji'j'}} \left[\frac{j_n(PR_{iji'j'})}{R_{iji'j'}^n} \right], \notag\\
&= - X_{iji'j'} \left(\frac{P}{R_{iji'j'}}\right)^{n+1} j_{n+1}(PR_{iji'j'}), \notag\\
&= - X_{iji'j'} \mathfrak j_{n+1}(P,R_{iji'j'}). \label{eq:dJdX}
\end{align}
Similarly,
\begin{align}
\frac{\partial \mathfrak j_n(P,R_{iji'j'})}{\partial Y_{iji'j'}}= - Y_{iji'j'} \mathfrak j_{n+1}(P,R_{iji'j'}) , \qquad
\frac{\partial \mathfrak j_n(P,R_{iji'j'})}{\partial Z_{iji'j'}}= - Z_{iji'j'} \mathfrak j_{n+1}(P,R_{iji'j'}). \label{eq:dJdYdZ}
\end{align}


The derivatives required in Equation~\ref{eq:gjffjjnf} can be then be found recursively using the following algorithm. Let 
\begin{equation}\label{eq29}
D_{lmn}(X,Y,Z)= \left( \frac{\partial}{\partial X} \right)^l \left( \frac{\partial}{\partial Y} \right)^m \left( \frac{\partial}{\partial Z} \right)^n \mathfrak j_0,
\end{equation}
where we have simplified the notation slightly by using $X\equiv X_{iji'j'}$, $Y\equiv Y_{iji'j'}$, $Z\equiv Z_{iji'j'}$ and $\mathfrak j_0\equiv \mathfrak j_0(P,R_{iji'j'})$ (which is an implicit function of $X$, $Y$ and $Z$).
From Equations~\ref{eq:dJdX} and \ref{eq:dJdYdZ}, we note that taking a partial derivative of $\mathfrak j_k$ with respect to $X$ gives $-X\mathfrak j_{k+1}$, and similarly for $Y$ and $Z$, and thus, $D_{lmn}(X,Y,Z)$ will be a combination of $\mathfrak j_k$'s, with powers of $X$, $Y$, and $Z$ as coefficients. 
That is, we can write
\begin{align}
D_{lmn}(X,Y,Z) = \sum_{\lambda=0}^l  a^{(l)}_\lambda(X) \sum_{\mu=0}^m  b^{(m)}_\mu(Y) \sum_{\nu=0}^n    c^{(n)}_\nu(Z) \mathfrak j_{\lambda+\mu+\nu}, \label{eq:30}
\end{align}
where $a^{(l)}_\lambda$, $b^{(m)}_\mu$ and $c^{(n)}_\nu$ are polynomials of degree ${\le} l$, $m$ and $n$, respectively.
Without loss of generality, we can determine a recursion relation for the polynomials $a^{(l)}_\lambda$ by considering the case $m=n=0$. In this case, Equation~\ref{eq:30} becomes
\begin{align}
D_{l00}(X,Y,Z) = \sum_{\lambda=0}^l  a^{(l)}_\lambda(X) \mathfrak j_{\lambda}. \label{eq:31}
\end{align}
Differentiating Equation~\ref{eq:31} with respect to $X$ gives
\begin{align}
D_{l+1,00}\equiv\frac{\partial}{\partial X} D_{l00}
&=\frac{\partial}{\partial X}\sum_{\lambda=0}^l  a^{(l)}_\lambda \mathfrak j_{\lambda} 
= \sum_{\lambda=0}^l \left( \frac{\partial a^{(l)}_\lambda}{\partial X}\mathfrak j_\lambda+a^{(l)}_\lambda \frac{\partial\mathfrak j_\lambda}{\partial X}\right),\notag\\
&=\sum_{\lambda=0}^l \left( \frac{\partial a^{(l)}_\lambda}{\partial X}\mathfrak j_\lambda-a^{(l)}_\lambda X \mathfrak j_{\lambda+1}\right). \label{eq:32}
\end{align}
By changing $l\rightarrow l+1$ in Equation~\ref{eq:31} we have a second expression for $D_{l+1,00}$:
\begin{align}
D_{l+1,00} = \sum_{\lambda=0}^{l+1}a^{(l+1)}_\lambda\mathfrak j_\lambda. \label{eq:33}
\end{align}
Setting these two expressions for $D_{l+1,00}$ equal yields
\begin{align}
\sum_{\lambda=0}^{l+1}a^{(l+1)}_\lambda\mathfrak j_\lambda 
- \sum_{\lambda=0}^l  \frac{\partial a^{(l)}_\lambda}{\partial X}\mathfrak j_\lambda
 + \sum_{\lambda=0}^l a^{(l)}_\lambda X \mathfrak j_{\lambda+1} = 0.
\end{align}
Next, we seek to rearrange this equation to obtain recurrence relations for the coefficients. By setting $a^{(l)}_\lambda\equiv 0$ if $\lambda>l$, we may rewrite the second term as a sum up to $l+1$, and %${-}\sum_{\lambda=0}^{l+1}(\partial a^{(l)}_\lambda/\partial X)\mathfrak j_\lambda$. Also, 
the third term can be reindexed as $\sum_{\lambda=1}^{l+1} a^{(l)}_{\lambda-1}X\mathfrak j_\lambda$:
\begin{align}
\phantom{\implies} & \sum_{\lambda=0}^{l+1}a^{(l+1)}_\lambda\mathfrak j_\lambda 
- \sum_{\lambda=0}^{l+1}  \frac{\partial a^{(l)}_\lambda}{\partial X}\mathfrak j_\lambda
+ \sum_{\lambda=1}^{l+1} a^{(l)}_{\lambda-1}X\mathfrak j_\lambda = 0, \notag\\
\implies & \left(a^{(l+1)}_0 - \frac{\partial a^{(l)}_0}{\partial X}\right)\mathfrak j_0
+ \sum_{\lambda=1}^{l+1}
\left(a^{(l+1)}_\lambda\mathfrak 
-   \frac{\partial a^{(l)}_\lambda}{\partial X}
+  a^{(l)}_{\lambda-1}X
\right)\mathfrak j_\lambda=0,
\end{align}
where the last expression is obtained by separating the $\lambda=0$ terms from the first two sums.

The functions $\{ \mathfrak j_\lambda \}_{\lambda=0}^{l+1}$ are linearly independent, which leads us to the recurrence relations
\begin{align}\label{eq:rec_rel_a}
a^{(l+1)}_0(X) &= \frac{\partial }{\partial X} a^{(l)}_0(X) , \notag \\
a^{(l+1)}_\lambda(X) &= \frac{\partial }{\partial X}a^{(l)}_\lambda(X) - Xa^{(l)}_{\lambda-1}(X) \qquad(\lambda\ge1),
\end{align}
with $a^{(0)}_0=1$.  The other coefficients are defined similarly:
\begin{align}
b^{(m+1)}_0 &= \frac{\partial b^{(m)}_0}{\partial Y} ,\nonumber \\
b^{(m+1)}_\mu &= \frac{\partial b^{(m)}_\mu}{\partial Y} - b^{(m)}_{\mu-1}Y\qquad(\mu\ge1), \\
c^{(n+1)}_0 &= \frac{\partial c^{(n)}_0}{\partial Z} , \nonumber\\
c^{(n+1)}_\nu &= \frac{\partial c^{(n)}_\nu}{\partial Z} - c^{(n)}_{\nu-1}Z\qquad(\nu\ge1),
\end{align}
with $b^{(0)}_0=c^{(0)}_0=1$. 
