Putting all of this together in Equation \ref{eq:gjffjjnf}, we have an expression for $\int \left|A^{(0)}_{n\varepsilon}(\mathbf{P})\right|^2d\Omega_{\mathbf{P}}$:
\begin{align}
    \int \left|A^{(0)}_{n\varepsilon}(\mathbf{P})\right|^2&d\Omega_{\mathbf{P}} 
    =\nonumber
    \sum_{i,j,i',j'}C_i^{\varepsilon} C^{(n)}_j C^{\varepsilon *}_{i'} C^{(n)*}_{j'} 
    e^{-\lambda_{ij}|\mathbf{r}_i-\mathbf{r}_j|^2} e^{-\lambda_{i'j'}|\mathbf{r}_{i'}-\mathbf{r}_{j'}|^2}
    \frac{4\pi^4}{[(\zeta_i+\zeta_j)(\zeta_{i'}+\zeta_{j'})]^{3/2}}\, 
    \\\nonumber
    &\times  e^{-P^2/4(\zeta_i+\zeta_j)} e^{-P^2/4(\zeta_{i'}+\zeta_{j'})}  \\\nonumber
&\times \sum_{\substack{s^x_{ij},s^y_{ij},s^z_{ij},\\ s^x_{i'j'},s^y_{i'j'},s^z_{i'j'}}}
E_{s^x_{ij}}^{n^x_i n^x_j} 
E_{s^y_{ij}}^{n^y_i n^y_j} 
E_{s^z_{ij}}^{n^z_i n^z_j} 
E_{s^x_{i'j'}}^{n^x_{i'} n^x_{j'}} 
E_{s^y_{i'j'}}^{n^y_{i'} n^y_{j'}} 
E_{s^z_{i'j'}}^{n^z_{i'} n^z_{j'}}
(-1)^{s^x_{i'j'}+s^y_{i'j'}+s^z_{i'j'}}
   \\ 
&\times 
\!\!\!\sum_{\lambda=0}^{s^x_{ij}+s^x_{i'j'}} \!\!\!a^{(s^x_{ij}+s^x_{i'j'})}_\lambda(X_{iji'j'})
\!\!\!\sum_{\mu=0}^{s^y_{ij}+s^y_{i'j'}} \!\!\!b^{(s^y_{ij}+s^y_{i'j'})}_\mu(Y_{iji'j'}) 
\!\!\!\sum_{\nu=0}^{s^z_{ij}+s^z_{i'j'}}   \!\!\!c^{({s^z_{ij}+s^z_{i'j'}})}_\nu(Z_{iji'j'}) 
\mathfrak j_{\lambda+\mu+\nu}(P,R_{iji'j'}).
\label{eq:ann_amp_int_final}\end{align}





%%%%%%% from here, we're looking at a new integral
Here, we have explicitly written the complex conjugates of the expansion coefficients $C^{\varepsilon *}_{i'}$ and $C^{(n)*}_{j'}$, but in practice our basis functions are real and the corresponding expansion coefficients are real as well so the complex conjugate is not required. We now turn our attention to the final integral over $P$ in Equation~\ref{eqn:gamspec}.
Substituting Equation \ref{eq:ann_amp_int_final} into Equation~\ref{eqn:gamspec}, we have
\begin{equation}
w^{(0)}_{n \varepsilon}(\epsilon) = 
\sum_{i,i',j,j'}
C^{\varepsilon}_{i}
C^{\varepsilon}_{i'}
C^{n}_{j}
C^{n}_{j'}
[\gamma(\epsilon)]_{i',j'}^{i,j},
\label{eq:gamma_expansion}
\end{equation}
where we introduce the \emph{$\gamma$-spectrum matrix}
\begin{align}
[\gamma(\epsilon)]_{i',j'}^{i,j}&= %w_n(\epsilon)&=
\frac{1}{(2\pi)^3c} 
\frac{4\pi^4}{[(\zeta_i+\zeta_j)(\zeta_{i'}+\zeta_{j'})]^{3/2}} 
e^{-\lambda_{ij}\lvert \mathbf r_i-\mathbf r_j\rvert^2}
e^{-\lambda_{i'j'}\lvert \mathbf r_{i'}-\mathbf r_{j'}\rvert^2} 
\notag\\
&\quad{}\times \sum_{\substack{s^x_{ij},s^y_{ij},s^z_{ij},\\ s^x_{i'j'},s^y_{i'j'},s^z_{i'j'}}}
E_{s^x_{ij}}^{n^x_i n^x_j} 
E_{s^y_{ij}}^{n^y_i n^y_j} 
E_{s^z_{ij}}^{n^z_i n^z_j} 
E_{s^x_{i'j'}}^{n^x_{i'} n^x_{j'}} 
E_{s^y_{i'j'}}^{n^y_{i'} n^y_{j'}} 
E_{s^z_{i'j'}}^{n^z_{i'} n^z_{j'}}
(-1)^{s^x_{i'j'}+s^y_{i'j'}+s^z_{i'j'}} \notag\\
&\quad{} \times \sum_{\lambda=0}^{s^x_{ij}+s^x_{i'j'}}a^{(s^x_{ij}+s^x_{i'j'})}_\lambda (X_{iji'j'})
 \sum_{\mu=0}^{s^y_{ij}+s^y_{i'j'}} b^{(s^y_{ij}+s^y_{i'j'})}_\mu  (Y_{iji'j'})
 \sum_{
 \nu=0}^{s^z_{ij}+s^z_{i'j'}}   c^{(s^z_{ij}+s^z_{i'j'})}_{\nu} (Z_{iji'j'})
\mathfrak I^{(\lambda\mu \nu)}_{iji'j'}(\epsilon) ,
\end{align}
where
\begin{align}
\mathfrak I^{(\lambda\mu \nu)}_{iji'j'}(\epsilon) = 
\int_{2\lvert\epsilon\rvert/c}^\infty P \exp\left[-\frac{P^2}{4}\left(\frac{1}{\zeta_i+\zeta_j}+\frac{1}{\zeta_{i'}+\zeta_{j'}}\right)\right] \mathfrak j_{\lambda+\mu+\nu}(P,R_{iji'j'})\,dP.\label{eq53}
\end{align}
The integral in Equation~\ref{eq53} is computed numerically using Gauss-Legendre quadrature. To do this, an appropriate finite upper limit for the integral, $P_{\text{max}}$, must be chosen based on the decay of the integrand as $P\rightarrow\infty$. The long-range behaviour of the integrand is dominated by the decaying Gaussian factor, so $P_\text{max}$ is chosen such that
$P_\text{max}^2[1/(\zeta_i+\zeta_j)+1/(\zeta_{i'}+\zeta_{j'})]/4\gg1$, i.e., $P_\text{max}\gg2/[1/(\zeta_i+\zeta_j)+1/(\zeta_{i'}+\zeta_{j'})]^{1/2}$. In practice, we use the limit
\begin{equation}
P_\text{max}=10/[1/(\zeta_i+\zeta_j)+1/(\zeta_{i'}+\zeta_{j'})]^{1/2}.
\end{equation}

