\section{Expanded forms of the PMNS matrix in 9 rotation parameterisations \label{sec:fullPMNS}}

Here we present the full form of the PMNS matrix under the 9 (6 Tait-Bryan and 3 Euler rotations) parameterisations considered in this analysis. Up to relabeling of the mixing angles and sign of the complex phase, six of these are equivalent to the parameterisations derived in~\cite{Denton} by considering different products of the matrices $R_{23}$, $\Gamma_\delta^\dagger R_{13}\Gamma_\delta,$ and $ R_{12}$. For example, $U_{\nu_\mu\nu_\tau / \nu_1\nu_3} \equiv P_{\mathbb{I}} \times U_{R} \times P_{-}$ is structurally equivalent to the Tait-Bryan rotation $R_{23}\times R_{12} \times \Gamma_\delta^\dagger \times R_{13}\times \Gamma_\delta$. Using the construction below, the intrinsic flavour and mass symmetries of each parameterisation become more obvious. The ordering of the parameterisations mirrors the label in Figure \ref{fig:1Dposterior}, and expression \ref{mutau12} is the canonical form. The correspondences with the parameterisations in ~\cite{Denton} may be identified by spotting the position of the single-angle element. The 9 matrices are generated by identifying  $X_1$ and $X_2$ with one of the three $3\times 3$ even permutation matrices (i.e. the action of the alternating group $A_3$):

\[
P_{\mathbb{I}} = \begin{pmatrix}
1 & 0 & 0 \\
0 & 1 & 0 \\
0 & 0 & 1 \\
\end{pmatrix}, \quad
P_+ = \begin{pmatrix}
0 & 1 & 0 \\
0 & 0 & 1 \\
1 & 0 & 0 \\
\end{pmatrix}, \quad
P_- = \begin{pmatrix}
0 & 0 & 1 \\
1 & 0 & 0 \\
0 & 1 & 0 \\
\end{pmatrix}.
\]

\begin{strip}
\begin{align}
U_{\nu_\mu\nu_\tau / \nu_1\nu_2} &= P_{\mathbb{I}} \times U_{R} \times P_{\mathbb{I}} = \begin{pmatrix}
      c_{12}c_{13} & s_{12}c_{13} &   s_{13}e^{-i \delta_{CP}}    \\
     -s_{12}c_{23} - c_{12}s_{23}s_{13}e^{i \delta_{CP}} &  c_{12}c_{23} - s_{12}s_{23}s_{13}e^{i \delta_{CP}} &        s_{23}c_{13}    \\
      s_{12}s_{23} - c_{12}c_{23}s_{13}e^{i \delta_{CP}} & -c_{12}s_{23} - s_{12}c_{23}s_{13}e^{i \delta_{CP}} &
      c_{23}c_{13}
    \end{pmatrix} \label{mutau12} \\[1.5em]
U_{\nu_\mu\nu_\tau / \nu_2\nu_3} &= P_{\mathbb{I}} \times U_{R} \times P_+ = \begin{pmatrix}
      s_{13}e^{-i \delta_{CP}} & c_{12}c_{13} & s_{12}c_{13}     \\
      s_{23}c_{13} & -s_{12}c_{23} - c_{12}s_{23}s_{13}e^{i \delta_{CP}} &  c_{12}c_{23} - s_{12}s_{23}s_{13}e^{i \delta_{CP}} \\
      c_{23}c_{13} & s_{12}s_{23} - c_{12}c_{23}s_{13}e^{i \delta_{CP}} & -c_{12}s_{23} - s_{12}c_{23}s_{13}e^{i \delta_{CP}} 
    \end{pmatrix} \label{mutau23} \\[1.5em]
U_{\nu_\mu\nu_\tau / \nu_1\nu_3} &= P_{\mathbb{I}} \times U_{R} \times P_- = \begin{pmatrix}
      c_{12}c_{13}  &   s_{13}e^{-i \delta_{CP}}  & s_{12}c_{13}  \\
     -s_{12}c_{23} - c_{12}s_{23}s_{13}e^{i \delta_{CP}}  & s_{23}c_{13} &  c_{12}c_{23} - s_{12}s_{23}s_{13}e^{i \delta_{CP}}   \\
      s_{12}s_{23} - c_{12}c_{23}s_{13}e^{i \delta_{CP}} & c_{23}c_{13} & -c_{12}s_{23} - s_{12}c_{23}s_{13}e^{i \delta_{CP}} 
    \end{pmatrix} \label{mutau13} \\[1.5em]
U_{\nu_e\nu_\tau / \nu_1\nu_2} &= P_- \times U_{R} \times P_{\mathbb{I}} = \begin{pmatrix}
     -s_{12}c_{23} - c_{12}s_{23}s_{13}e^{i \delta_{CP}} &  c_{12}c_{23} - s_{12}s_{23}s_{13}e^{i \delta_{CP}} &        s_{23}c_{13}    \\
      c_{12}c_{13} & s_{12}c_{13} &   s_{13}e^{-i \delta_{CP}}    \\
      s_{12}s_{23} - c_{12}c_{23}s_{13}e^{i \delta_{CP}} & -c_{12}s_{23} - s_{12}c_{23}s_{13}e^{i \delta_{CP}} &
      c_{23}c_{13}
    \end{pmatrix} \label{etau12} \\[1.5em] 
U_{\nu_e\nu_\tau / \nu_2\nu_3} &= P_+ \times U_{R} \times P_- = \begin{pmatrix}
      s_{23}c_{13} & -s_{12}c_{23} - c_{12}s_{23}s_{13}e^{i \delta_{CP}} &  c_{12}c_{23} - s_{12}s_{23}s_{13}e^{i \delta_{CP}}      \\
      s_{13}e^{-i \delta_{CP}} & c_{12}c_{13} & s_{12}c_{13}       \\
      c_{23}c_{13} & s_{12}s_{23} - c_{12}c_{23}s_{13}e^{i \delta_{CP}} & -c_{12}s_{23} - s_{12}c_{23}s_{13}e^{i \delta_{CP}} 
    \end{pmatrix} \\[1.5em]
U_{\nu_e\nu_\tau / \nu_1\nu_3} &= P_- \times U_{R} \times P_- = \begin{pmatrix}
     -s_{12}c_{23} - c_{12}s_{23}s_{13}e^{i \delta_{CP}} &        s_{23}c_{13}   &  c_{12}c_{23} - s_{12}s_{23}s_{13}e^{i \delta_{CP}}  \\
      c_{12}c_{13} &   s_{13}e^{-i \delta_{CP}}  & s_{12}c_{13}   \\
      s_{12}s_{23} - c_{12}c_{23}s_{13}e^{i\delta_{CP}}  & c_{23}c_{13}  & -c_{12}s_{23} - s_{12}c_{23}s_{13}e^{i \delta_{CP}}
    \end{pmatrix} \\[1.5em]
U_{\nu_e\nu_\mu / \nu_1\nu_2} &= P_+ \times U_{R} \times P_{\mathbb{I}} = \begin{pmatrix}
     -s_{12}c_{23} - c_{12}s_{23}s_{13}e^{i \delta_{CP}} &  c_{12}c_{23} - s_{12}s_{23}s_{13}e^{i \delta_{CP}} &        s_{23}c_{13}    \\
      s_{12}s_{23} - c_{12}c_{23}s_{13}e^{i \delta_{CP}} & -c_{12}s_{23} - s_{12}c_{23}s_{13}e^{i \delta_{CP}} &
      c_{23}c_{13} \\
      c_{12}c_{13} & s_{12}c_{13} &   s_{13}e^{-i \delta_{CP}}   
    \end{pmatrix} \label{emu12} \\[1.5em]
U_{\nu_e\nu_\mu / \nu_2\nu_3} &= P_+ \times U_{R} \times P_+ = \begin{pmatrix}
      s_{23}c_{13} & -s_{12}c_{23} - c_{12}s_{23}s_{13}e^{i \delta_{CP}} &  c_{12}c_{23} - s_{12}s_{23}s_{13}e^{i \delta_{CP}}   \\
      c_{23}c_{13} & s_{12}s_{23} - c_{12}c_{23}s_{13}e^{i \delta_{CP}} & -c_{12}s_{23} - s_{12}c_{23}s_{13}e^{i \delta_{CP}}  \\
      s_{13}e^{-i \delta_{CP}} & c_{12}c_{13} & s_{12}c_{13}   s_{13}e^{-i \delta_{CP}}   
    \end{pmatrix} \label{emu23} \\[1.5em] 
U_{\nu_e\nu_\mu / \nu_1\nu_3} &= P_+ \times U_{R} \times P_- = \begin{pmatrix}
     -s_{12}c_{23} - c_{12}s_{23}s_{13}e^{i \delta_{CP}} &   s_{23}c_{13}  &  c_{12}c_{23} - s_{12}s_{23}s_{13}e^{i \delta_{CP}}   \\
      s_{12}s_{23} - c_{12}c_{23}s_{13}e^{i \delta_{CP}} & c_{23}c_{13}  & -c_{12}s_{23} - s_{12}c_{23}s_{13}e^{i \delta_{CP}} \\
      c_{12}c_{13} &   s_{13}e^{-i \delta_{CP}}  & s_{12}c_{13}   
    \end{pmatrix} \label{emu13}
\end{align}
\end{strip}

\section{Fake data results \label{sec:fakeResults}}
To test whether the main results in section \ref{sec:results} are due to the robustness of T2K's constraining power or due to the particular shape of the likelihood in the favoured area of parameter space, we run the same analysis on chains generated from two Asimov datasets~\cite{Asimov} at points Asimov A and Asimov B of the phase space (defined in table \ref{tab:asimov}). Asimov A is chosen to recreate posteriors similar to the data fit, and Asimov B is chosen to represent a scenario with no CP violation and true lower octant.

Figures \ref{fig:1DposteriorAsimovA} and \ref{fig:1DposteriorAsimovB} show the 1D marginalised posteriors for Asimov points A and B, and reweighted with the Tait-Bryan priors. The results are consistent with the conclusions of section \ref{sec:results}: the $\theta_{23}$ octant preference vanishes for some priors but the constraints remain largely the same. Although the posteriors for $\delta_{CP}$ vary substantially (Asimov B experiences a shift of the highest posterior density from 0 to $\pm\pi$), the constraints on the amount of CP violation as given by the Jarlskog invariant show sub-percent change within the $2\sigma$ range. This falls in line with the fact that T2K has good sensitivity to the observable $J_{CP}$, which is a more robust measure of CP-violation than a prior-dependent extraction to $\delta_{CP}$.

