\begin{thrm}\label{dt0}
Let $(M,g,J,\Psi)$ be a 6-dimensional  ACYT manifold with  constant norm of the Nijenhuis tensor  and the  curvature of the torsion connection $\sb$   is an $SU(3)$-instanton. %with instanton curvature. 

If the Lee form is $\sb$-parallel then $d^{\sb}T=0$.
\end{thrm}
\begin{proof}
We calculate from \eqref{dh}
\begin{multline}\label{inst3}
d^{\sb}T_{pjkl}\Phi_{jkli}=\sb_pT_{jkl}\Phi_{jkli}-3\sb_lT_{jkp}\Phi_{jkli}=6\sb_p\theta_i-3\sb_lT_{jkp}\Big[F_{jk}F_{li}+F_{kl}F_{ji}+F_{lj}F_{ki}\Big]\\=
6\sb_p\theta_i+6\sb_l\theta_sF_{sp}F_{li}-6\sb_lT_{kjp}F_{lk}F_{ji}=0,
\end{multline}
where we used $\sb\theta=0$ and \eqref{inst2} to get the last equality.

We have from \eqref{rr} using \eqref{1bi1}, \eqref{tit} and \eqref{dh}   the following %Ricci tensor $Ric$ of  $\sb$ is given by
%\begin{equation}\label{ricdt}
%Ric_{ij}=\frac12R_{iabc}\Phi_{jabc}=\frac16\Big[R_{iabc}+R_{ibca}+R_{icab} \Big]\Phi_{jabc}%=\frac1{12}dT_{iabc}\Phi_{jabc}+\frac16\sb_iT_{abc}\Phi_{jabc}
%=\frac1{12}dT_{iabc}\Phi_{jabc}-\sb_i\theta_j.
%\end{equation}
%This completes the proof of the first identity in \eqref{ricg2}.
%Similarly, we have
\begin{equation}\label{ricnew}
\begin{split}0=R_{iabc}\ps_{abc}=\frac13\Big[R_{iabc}+R_{ibca}+R_{icab} \Big]\ps_{abc}%=\frac16dT_{iabc}\ps_{abc}+\frac13\sb_iT_{abc}\ps_{abc}
=\frac16dT_{iabc}\ps_{abc}+2\sb_i\lambda,\\
0=R_{iabc}\sp_{abc}=\frac13\Big[R_{iabc}+R_{ibca}+R_{icab} \Big]\sp_{abc}%=\frac16dT_{iabc}\sp_{abc}+\frac13\sb_iT_{abc}\sp_{abc}
=\frac16dT_{iabc}\sp_{abc}+2\sb_i\mu.\end{split}
\end{equation}

Since $M$ is of constant type then $d\lambda=d\mu=0$ and we get from \eqref{ricnew} that 
\begin{equation}\label{inst4}
dT_{iabc}\ps_{abc}=dT_{iabc}\sp_{abc}=0.
\end{equation}
The  $SU(3)$--instanton condition \eqref{rr1} together with \eqref{rr} applied to \eqref{gen} yield
\begin{equation}\label{inst5}
0=\Big[R_{abci}+R_{bcai}+R_{cabi}-R_{iabc}-R_{ibca}-R_{icab}  \Big]\Psi^{\pm}_{abc}=\Big[\frac32dT_{abci}-\sigma^T_{abci}\Big]\Psi^{\pm}_{abc}=-\sigma^T_{abci}\Psi^{\pm}_{abc},
\end{equation}
where we used \eqref{inst4} to achieve the last equality.



Now, \eqref{dh} together with \eqref{inst4} and \eqref{inst5} implies
\begin{equation}\label{inst6}
0=dT_{iabc}\Psi^{\pm}_{abc}=d^{\sb}T_{iabc}\Psi^{\pm}_{abc}+2\sigma^T_{iabc}\Psi^{\pm}_{abc}=d^{\sb}T_{iabc}\Psi^{\pm}_{abc}.
\end{equation}
The identities \eqref{inst3} and \eqref{inst6} show that for any vector field $X$ the 3-form $(X\lrcorner d^{\sb}T)\in \Lambda^3_{12}$. Then the 4-form $d^{\sb}T=0$ due to Proposition~\ref{4-for}.
\end{proof}
In view of $d^{\sb}T=0$ we get from  \eqref{dh} 
\begin{equation}\label{inst8}
dT=2\sigma^T
\end{equation}
and we can write \eqref{inst1} in the form
\begin{multline}\label{inst7}
R(X,Y,Z,V)-R(Z,V,X,Y)\\=(\sb_XT)(Y,Z,V)-(\sb_YT)(X,Z,V)=-(\sb_ZT)(X,Y,V)+(\sb_VT)(X,Y,Z).
\end{multline}
Substitute \eqref{inst8} into \eqref{1bi} and  into \eqref{1bi1} to get
\begin{equation}\label{inst9}
\begin{split}
R(X,Y,Z,V)+R(Y,Z,X,V)+R(Z,X,Y,V)=\sigma^T(X,Y,Z,V)+(\sb_VT)(X,Y,Z);\\
R(V,X,Y,Z)+R(V,Y,Z,X)+R(V,Z,X,Y)=-\sigma^T(X,Y,Z,V)+(\sb_VT)(X,Y,Z).
\end{split}
\end{equation}
The sum of the two identities in \eqref{inst9} yields
\begin{multline}\label{inst10}
R(X,Y,Z,V)+R(Y,Z,X,V)+R(Z,X,Y,V)+R(V,X,Y,Z)+R(V,Y,Z,X)+R(V,Z,X,Y)\\=2(\sb_VT)(X,Y,Z).
\end{multline}
Using the fact that the curvature is (1,1) with respect to the first and the second pairs, we get from \eqref{inst10}
\begin{equation}\label{inst11}
(\sb_VT)(Z,JX,JY)=(\sb_{JV}T)(JZ,X,Y).
\end{equation}

Applying \eqref{rr} and \eqref{instt2} to \eqref{inst7}, we obtain 
\begin{equation}\label{inst12}
(\sb_XT)(Y,Z,V)-(\sb_XT)(Y,JZ,JV)=(\sb_YT)(X,Z,V)-(\sb_YT)(X,JZ,JV).
\end{equation}
Define the tensor $C$ as follows
\begin{equation}\label{cht}
2C(Z;X,Y)=T^+(Z,JX,JY)-T^+(Z,X,Y),
\end{equation}
where $T^+$ denotes the (1,2)+(2,1)-part of the torsion 3-form $T$. 

From  equation \eqref{cy2} we get  $T^+=-dF^+(J,J,J),\quad T^-=\frac14N$.
It is easy to check applying \eqref{12} 
\begin{equation}\label{tch}
\begin{split}
T^+(Z,X,Y)=-C(Z;X,Y)-C(X;Y,Z)-C(Y;Z,X); \\ C(JZ;X,Y)=-C(Z;JX,Y)=-C(Z;X,JY).
\end{split}
\end{equation}
Note that in the complex case, $N=0$, the tensor $C$ is precisely the torsion of the Chern connection.

It follows from \eqref{cht} and \eqref{tch} that the condition $\sb C=0$ is equivalent to  $\sb T^+=0$. Since the Nijenhuis tensor $N=4T^-$ is $\sb$-parallel  we get  that $\sb C=0$ exactly when $ \sb T=0$.
%then 
%\begin{equation}\label{inst15}
%(\sb_VC)(JZ;X,Y)=-(\sb_VC)(Z;JX,Y)=-(\sb_VC)(Z;X,JY).
%\end{equation}

Now, equality \eqref{inst11} yields
\begin{equation}\label{inst14}
(\sb_VC)(Z;X,Y)=-(\sb_{JV}C)(JZ;X,Y).
\end{equation}
We can write \eqref{inst12} in the form
\begin{equation}\label{inst13}
(\sb_XC)(Y;Z,V)=(\sb_YC)(X;Z,V).
\end{equation}
We use the complex basis $E_{\alpha}=e_a-iJe_a,\quad \bar{E_a}=E_{\bar{\alpha}}=e_a+iJe_a$.


We obtain from \eqref{tch}, \eqref{inst14} and \eqref{inst13} that 
\begin{equation}\label{propch}
\begin{split}
C_{\bar\alpha;\bar\beta\gamma}=C_{\bar\alpha;\bar\beta\bar\gamma}=C_{\alpha\beta\gamma}=C_{\alpha;\beta\bar\gamma}=0 \,,\quad T^+_{\bar\alpha\beta\gamma}=-T^+_{\beta\bar\alpha\gamma}=-C_{\bar\alpha;\beta\gamma}=C_{\bar\alpha;\gamma\beta} \,,\\
\sb_{\alpha}C_{\bar\beta;\gamma\mu}=\sb_{\bar\alpha}C_{\beta;\bar\gamma\bar\mu}=0 \,, \quad \sb_{\alpha}C_{\beta;\bar\gamma\bar\mu}=\sb_{\beta}C_{\alpha;\bar\gamma\bar\mu} \,, \quad  \sb_{\bar\alpha}C_{\bar\beta;\gamma\mu}=\sb_{\bar\beta}C_{\bar\alpha;\gamma\mu} \,.
\end{split}
\end{equation}
\begin{lemma}\label{instl} 
If $\sb$ is an $SU(3)$--instanton connection with parallel Lee form, then it holds
\[
\begin{split}
\sb_{\bar\alpha}\sb_{\bar\beta}C_{\bar\gamma;\mu\nu}-\sb_{\bar\beta}\sb_{\bar\alpha}C_{\bar\gamma;\mu\nu}=-T^+_{\bar\alpha\bar\beta\sigma}\sb_{\bar\sigma}C_{\bar\gamma;\mu\nu}; \\ 2\sb_{\bar\alpha}\sb_{\bar\beta}C_{\bar\gamma;\alpha\beta}=-T^+_{\bar\alpha\bar\beta\sigma}\sb_{\bar\gamma}C_{\bar\sigma;\alpha\beta}=\frac12\sb_{\bar\gamma}||C||^2; \\ \sb_{\bar\alpha}\sb_{\bar\beta}C_{\bar\gamma;\alpha\beta}=0.
\end{split}
\]
In particular, the norm of the torsion is a constant.
\end{lemma}
\begin{proof}
The instanton condition yields the curvature 2-form $R_{\bar a\bar b}=0$. Therefore,
\[0=R_{\bar\alpha\bar\beta}\times C_{\bar\gamma;\mu\nu}=R_{\bar\alpha,\bar\beta,\bar\gamma,\sigma}C_{\bar\sigma;\mu\nu}+R_{\bar\alpha,\bar\beta,\mu,\sigma}C_{\bar\gamma;\sigma\nu}+R_{\bar\alpha,\bar\beta,\nu,\sigma}C_{\bar\gamma;\mu\sigma}.\]
The Ricci identity for $\sb$ reads with the help of \eqref{cy2} 
\[\sb_{\bar\alpha}\sb_{\bar\beta}C_{\bar\gamma;\mu\nu}-\sb_{\bar\beta}\sb_{\bar\alpha}C_{\bar\gamma;\mu\nu}=-R_{\bar\alpha\bar\beta}\times C_{\bar\gamma;\mu\nu}-T^+_{\bar\alpha\bar\beta\sigma}\sb_{\bar\sigma}C_{\bar\gamma;\mu\nu}%=-T^+_{\bar\alpha\bar\beta\sigma}\sb_{\bar\sigma}C_{\bar\gamma;\mu\nu} %-T^+_{\bar a\bar b s}\sb_{\bar s}C_{\bar c;lm}
-\frac14N_{\bar\alpha\bar\beta\bar\sigma}\sb_{\sigma}C_{\bar\gamma;\mu\nu}=-T^+_{\bar\alpha\bar\beta\sigma}\sb_{\bar\sigma}C_{\bar\gamma;\mu\nu} \,, %T^+_{\bar a\bar b s}\sb_{\bar s}C_{\bar c;lm}
\]
since  $\sb_{\sigma}C_{\bar\gamma;\mu\nu}=0$ because of \eqref{propch}. This proves the  first line of the lemma.

Set $\mu=\alpha, \nu=\beta$ into the already proved first equality  we obtain the second line using  \eqref{propch}.

To show the last statement, we apply again \eqref{inst13} to get
\[ \sb_{\bar\beta}\sb_{\bar\alpha}C_{\bar\gamma;\beta\alpha}=\sb_{\bar\beta}\sb_{\bar\gamma}C_{\bar\alpha;\beta\alpha}=\sb_{\bar\beta}\sb_{\bar\gamma}\theta_{\beta}=0\]
which combined with the already proved second identity of the lemma yields $\sb||C||^2=0$ and therefore $\sb||T||^2=0$ since $\sb N=0$.
\end{proof}
\subsection{Proof of Theorem~\ref{main}}
It is clear from \eqref{rr} that if \eqref{r4} holds, i.e. $\sb T$ is a 4-form due to \eqref{4form}, then   the curvature of the torsion connection $\sb$ of an ACYT manifold is an instanton.  In particular, if $\sb T=0$ then $R$ is an instanton, the Lee form is $\sb$-parallel and therefore co-closed, $\delta\theta=0$. The next result completes  the proof of Theorem~\ref{main}.% we show below that if the ACYT space is balanced, of constant type and $R$ is an instanton then the torsion is $\sb$-parallel, $\sb T=0$ and \eqref{rr} holds.
\begin{thrm}\label{main1}  Let $(M,g,J,\Psi)$ be an ACYT 6-manifold  with  constant norm of the Nijenhuis tensor and $\sb$-parallel Lee form.  If the  curvature of the torsion connection $\sb$   is an $SU(3)$-instanton   then the torsion is $\sb$-parallel, $\sb T=0$.
%Let $(M,g,J,\Psi)$ be a compact balanced ACYT 6-manifold  and $\sb$ be an instanton connection.  Then the torsion is $\sb$-parallel, $\sb T=0$.
\end{thrm}
\begin{proof} 
Since $||C||^2=const$, we have
\begin{multline}\label{inst17}
0=\sb_{\alpha}\sb_{\bar\alpha}||C||^2=\sb_{\alpha}\Big[\sb_{\bar\alpha}C_{\bar\sigma;\mu\nu}C_{\sigma;\bar\mu\bar\nu}+C_{\bar\sigma;\mu\nu}\sb_{\bar\alpha}C_{\sigma;\bar\mu\bar\nu}\Big]=\sb_{\alpha}\sb_{\bar\alpha}C_{\bar\sigma;\mu\nu}C_{\sigma;\bar\mu\bar\nu}+||\sb C||^2,
\end{multline}
where we apply \eqref{inst14} to see that $\sb_{\bar\alpha}C_{\sigma;\bar\mu\bar\nu}=0$.

The Ricci identity together with \eqref{inst14} yields 
\begin{equation}\label{ricid}
\begin{split}
\sb_{\alpha}\sb_{\bar\alpha}C_{\bar\gamma;\mu\nu}=\sb_{\bar\alpha}\sb_{ \alpha}C_{\bar\gamma;\mu\nu}-R_{\alpha\bar\alpha}\times C_{\bar\gamma;\mu\nu}-T_{\alpha\bar 
\alpha\sigma}\sb_{\bar\sigma}C_{\bar\gamma;\mu\nu}- T_{\alpha\bar 
\alpha\bar\sigma}\sb_{\sigma}C_{\bar\gamma;\mu\nu}\\ =2\theta_{\sigma}\sb_{\bar\sigma}C_{\bar\gamma;\mu\nu}=2\theta_{\sigma}\sb_{\bar\gamma}C_{\bar\sigma;\mu\nu}=2\sb_{\bar\gamma}(\theta_{\sigma}C_{\bar\sigma;\mu\nu}),
\end{split}
\end{equation}
 where the first and the fourth terms in the right hand side vanishes because of \eqref{inst14}, the second term is zero since $R$ is an instanton, $R_{\alpha\bar\alpha}=0$, and for the third term we used the identity $T_{\alpha\bar\alpha\gamma}=-2\theta_{\gamma}$. The last two equalities  we obtain because of the symmetries in \eqref{propch} and the condition $\sb\theta=0$.

Using Lemma~\ref{insu4},  \eqref{cy2} and \eqref{cht},  we obtain
\[ 2C(\theta;X,Y)=T^+(\theta,JX,JY)-T^+T(\theta,X,Y)=T(\theta,JX,JY)-T(\theta,X,Y)-\frac12N(\theta,X,Y)=-\frac12N(\theta,X,Y),\]
which yields 
\begin{equation}\label{par}
(\sb_ZC)(\theta;X,Y)=0, \quad since \quad \sb N=\sb\theta=0.
\end{equation}
Now, \eqref{par}, \eqref{ricid} and \eqref{inst17} imply $||\sb T||^2=||\sb C||^2=0$ which completes the proof of Theorem~\ref{main}.
\end{proof}

\subsection{Proof of Theorem~\ref{mainc}}
It is known from \cite[Theorem~2.4]{IS1} that on any compact 6-dimensional ACYT the Nijenhuis tensor is $\sb$-parallel.  In this case we may replace the condition $\sb\theta=0$ in Theorem~\ref{main} with the weaker condition $\delta\theta=0$ due to the next result
\begin{thrm}\label{gaud}
 Let $(M,g,J,\Psi)$ be a compact ACYT 6-manifold  with  co-closed Lee form, $\delta\theta=0$.  If the  curvature of the torsion connection $\sb$   is an $SU(3)$-instanton   then the Lee form is $\sb$-parallel. %the torsion is $\sb$-parallel, $\sb T=0$.}
\end{thrm}
\begin{proof} We start with the next identity
\begin{equation}\label{iii}
\sb_i\delta T_{ij}=\frac12\delta T_{ia}T_{iaj} \,,
\end{equation}
 shown in \cite[Proposition~3.2]{IS} for any metric connection with a totally skew-symmetric torsion. %We give here a proof  of \eqref{iii} for completeness.  The identity $\delta^2=0$ together with \eqref{tsym}  imply 
%$$0=\delta^2 T_k=\LC_i\LC_jT_{ijk}=\LC_i\sb_jT_{ijk}=\sb_i\delta T_{ik}+\frac12T_{iks}\delta T_{is}=\sb_i\delta T_{ik}-\frac12\delta T_{is}T_{isk}.$$

We calculate the left-hand side  of \eqref{iii} applying Lemma~\ref{insu3} as follows
\begin{equation}\label{ntss}
\begin{split}
\sb_i\delta T_{ij}=\sb_id^{\sb}\theta_{ij}=%\sb_i\sb_i\theta_j-\sb_i\sb_j\theta_i-\frac12(\sb_i\sb_t-\sb_t\sb_i)\lambda\p_{tij}\\=
\sb_i\sb_i\theta_j-\sb_i\sb_j\theta_i.%-\frac12T_{tis}\sb_s\lambda\p_{tij},
\end{split}
\end{equation}
%where we applied $d^2\lambda=0$ and \eqref{tsym} to get the last term.
Substitute \eqref{ntss} into \eqref{iii} %using \eqref{deltaT} 
to get
\begin{equation}\label{ntss1}
\sb_i\sb_i\theta_j-\sb_i\sb_j\theta_i=\frac12d^{\sb}\theta_{ab}T_{abj}.
\end{equation}
The Ricci identity  
$\sb_i\sb_j\theta_i=%\sb_j\sb_i\theta_i-R_{ijis}\theta_s-T_{ija}\sb_a\theta_i=
\sb_j\sb_i\theta_i+Ric_{js}\theta_s-\frac12d^{\sb}\theta_{ai}T_{aij}$ substituted into \eqref{ntss1} yields
\begin{equation}\label{gafin}
\sb_i\sb_i\theta_j+\sb_j\delta\theta-Ric_{js}\theta_s=0.
\end{equation}
Multiply the both sides of \eqref{gafin} with $\theta_j$, use  $\delta\theta=0$ together with the identity 
$$\frac12\Delta||\theta|^2=-\frac12\LC_i\LC_i||\theta||^2=-\frac12\sb_i\sb_i||\theta||^2=-\theta_j\sb_i\sb_i\theta_j-||\sb\theta||^2$$ 
to get
\begin{equation}\label{gafinf}
-\frac12\Delta||\theta||^2-Ric(\theta,\theta)-||\sb\theta||^2=0.
\end{equation}
We obtain from \eqref{ins4} that 
\begin{equation}\label{rdt1}
\sb_aT_{bci}\ph_{abcj}=-2\sb_i\theta_j-4\sb_j\theta_i.
\end{equation}
We get from \eqref{ricdt} applying \eqref{dh} and \eqref{rdt1}
\begin{equation}\label{rdt}
\begin{split}
Ric_{ij}\theta_i\theta_j=\frac1{12}dT_{abci}\ph_{abcj}\theta_i\theta_j-\theta_i\theta_j\sb_i\theta_j\\=
\frac1{12}\Big[3\sb_aT_{bci}\ph_{abcj}-6\sb_i\theta_j +2\sigma^T_{abci}\ph_{abcj} \Big]\theta_i\theta_j-\theta_i\theta_j\sb_i\theta_j=-\frac32\theta_i\sb_i||\theta||^2 +\frac16\sigma^T_{abci}\ph_{abcj} \theta_i\theta_j.
\end{split}
\end{equation}
We will show that the last term in \eqref{rdt} vanishes.

Indeed, we have from Corollary~\ref{insu4} that  $\theta\lrcorner T=d\theta-\delta T\in \Lambda^2_8\cong\frak{su}(3)$.% yielding $\sigma^T_{abci}\ph_{abcj}\theta_i\theta_j=0$.

We calculate from \eqref{sigma} applying the first identity in \eqref{iden} and \eqref{tetor}
\begin{multline}\label{pres}
\frac13\sigma^T(e_a,e_b,e_c,\theta)\ph(e_a,e_b,e_c,\theta)=T(e_a,e_b,e_s)T(e_s,e_c,\theta)\ph(e_a,e_b,e_c,\theta)\\=T(e_a,e_b,e_s)T(e_s,e_c,\theta)\Big[F(e_a,e_b)F(e_c,\theta)+F(e_b,e_c)F(e_a,\theta)+F(e_c,e_a)F(e_b,\theta)    \Big]\\=T(Je_b,e_b,e_s)T(e_s,J\theta,\theta)+T(J\theta,Je_c,e_s)T(e_s,e_c,\theta)-T(Je_c,J\theta,e_s)T(e_s,e_c,\theta)\\=-T(Je_b,e_b,e_s)T(Je_s,\theta,\theta)+2T(J\theta,Je_c,e_s)T(e_s,e_c,\theta) =2T(J\theta,Je_c,e_s)T(e_s,e_c,\theta).
\end{multline}
Applying  \eqref{tetor}, we have
\[
\begin{split}T(J\theta,Je_c,e_s)T(e_s,e_c,\theta) =-T(J\theta,e_c,e_s)T(e_s,Je_c,\theta)=T(J\theta,e_c,e_s)T(Je_s,e_c,\theta)\\
=-T(J\theta,e_c,Je_s)T(e_s,e_c,\theta)=-T(J\theta,Je_s,e_c)T(e_s,e_c,\theta).
\end{split}\]
Hence, $T(J\theta,Je_c,e_s)T(e_s,e_c,\theta)=0$ and  \eqref{pres} yields $\sigma^T_{abci}\ph_{abcj} \theta_i\theta_j=0$ which substituted into \eqref{rdt} gives
\begin{equation}\label{rdt2}
Ric_{ij}\theta_i\theta_j=-\frac32\theta_i\sb_i||\theta||^2.
\end{equation}
Insert \eqref{rdt2} into \eqref{gafinf} to get 
\begin{equation}\label{gafinf1}
\Delta||\theta||^2+3\theta_i\sb_i||\theta||^2=-||\sb\theta||^2\le 0.
\end{equation}
We  apply  the strong maximum principle to \eqref{gafinf1} (see e.g. \cite{YB,GFS}) to achieve $d||\theta||^2=\sb\theta=0$.
\end{proof}
The proof of Theorem~\ref{mainc} follows from  Theorem~\ref{main} and Theorem~\ref{gaud}.

