	\title{ Improved bound of graph energy in terms of vertex cover number}
\author{Aniruddha Samanta \thanks{Theoretical Statistics and Mathematics Unit, Indian Statistical Institute, Kolkata-700108, India. Email: aniruddha.sam@gmail.com}}

