\section{Definitions, notation and preliminary results}\label{prelim}

Let $ G $ be an undirected simple graph with vertex set $ V(G)=\{ v_1, v_2, \dots, v_n\} $ and edge set $ E(G) $. A subset $ S $ of the edge set $ E(G) $ is called a \textit{cut set} of $ G $ if the deletion of all edges of $ S $ from $ G $ increase the number of connected components of $ G $. If $ S $ is a cut set of $ G $ then $ G-S $ denotes the resulting graph after deletion of all edges of $ S $ from $ G $ and it is defined as $ G-S:=G_1\oplus G_2 \oplus \cdots\oplus G_r$, where $ G_i's  $ are the connected components in $ G-S $. For a vertex $ v $ in $ G $, we denote $ G-v $ as an induced subgraph of $ G $ with vertex set $ V(G)\setminus{v} $. A vertex $ v \in V(G) $ is said to be a \textit{cut vertex} of $ G $ if $ G-v $ increases the number of connected components. A \textit{block} of the graph $ G $ is a maximal connected subgraph of $ G $ that has no cut-vertex. For an edge $ e \in E(G) $, we denote $ G-[e] $ as an induce subgraph of $ G $ obtained by removing $ e $, edges adjacent with $ e $ and the vertices joining $ e $. We denote a complete graph and a cycle with $ n $ vertices as $ K_n $ and $ C_n $, respectively. A complete bipartite graph with vertex partition size $p$ and $ q $ is denoted by $ K_{p,q} $. Let us first present the following bound which we are going to improve in this article for several classes of graphs. 


%Let $ G $ be a connected graph with vertex set $ V(G)=\{ v_1, v_2, \dots, v_n\} $. For a vertex $ v_i $, we denote $ G-v_i $ as a subgraph of $ G $ after removing the vertex $ v_i $ and its adjacent edges from $ G $. A vertex $ v_i \in V(G) $ is called a \textit{cut-vertex} of $ G $ if $ G-v_i $ is disconnected graph. A \textit{block} of the graph $ G $ is a maximal connected subgraph of $ G $ that has no cut-vertex


\begin{theorem}\cite[Theorem 4.2]{Wang-Ma}
	Let $ G $ be a graph with vertex cover number $ \tau$ and number of odd cycles $ c$. Then $ \mathcal{E}(G)\geq 2\tau-2c$. Equality occurs if and only if $ G $ is the disjoint union of some $ K_{p,p} $, for some $ p $ and isolated vertices.
\end{theorem}

%Many authors extended the above bound for signed graphs, mixed graphs, gain graphs \cite{Energybound1}, etc.  
The following two results we use frequently in the later sections. 
\begin{theorem}\cite[Theorem 3.4]{Day-So}\label{Th1}
	If $ G $ is a graph with a simple cut set $ E $, then $ \mathcal{E}(G)\geq \mathcal{E}(G-E) $.
\end{theorem}

\begin{theorem}\cite[Theorem 3.6]{Day-So}\label{Th2}
	If $ E $ is a cut set between complimentary induced subgraphs $ M $ and $ N $ of $ G $.  Suppose the edges of $ E $ form a star, then $ \mathcal{E}(G)>\mathcal{E}(G-E) $.
\end{theorem}


\begin{lemma}\label{lm2.1}
	For any cycle $ C_n $ with $ n $ vertices, \begin{equation*}
		\mathcal{E}(C_n)= \left\{ \begin{array}{ccc}
			4\frac{\cos\frac{\pi}{n}}{\sin \frac{\pi}{n}} & \mbox{for} & n\equiv 0 \mbox{ mod 4}\\
			\frac{4}{\sin \frac{\pi}{n}} & \mbox{for} & n\equiv 2 \mbox{ mod 4}\\
			\frac{2}{\sin \frac{\pi}{2n}} & \mbox{for} & n\equiv 1 \mbox{ mod 2}.
		\end{array}
		\right.
	\end{equation*}
\end{lemma}
