\section{Graph energy in terms of the vertex cover number}

We begin this section with some basic class of graphs $ G $ for which $ \mathcal{E}(G)\geq 2\tau(G)$ holds.


\begin{prop}\label{prop3.1}
	\begin{itemize}
		\item[(1)] Let $ G $ be a complete graph. Then $ \mathcal{E}(G)=2\tau(G) $.
		\item[(2)] Let $ G $ be a bipartite graph. Then $ \mathcal{E}(G)\geq 2\tau(G) $.
		\item [(3)] Let $ G $ be a cycle. Then $ \mathcal{E}(G)\geq 2\tau(G) $.
	\end{itemize}
\end{prop}

\begin{proof}
	Part $ (1) $ and $ (2) $ are easy to observe.\\
	$ (3) $ If $ n $ is even, then $ C_n $ is bipartite. Then $ \mathcal{E}(C_n)\geq 2\mu(C_n)=2\tau(C_n) $. If $ n $ is odd. Then $ n\equiv 1 $ mod $ 2 $. That is $ n=2k+1 $, for $ k=1,2, \cdots $. Now $ \frac{\pi}{2n}< \frac{\pi}{4} $, so $ \sin x<x $. Therefore, $ \sin \frac{\pi}{2n}<\frac{\pi}{2n} $. Now by Lemma \ref{lm2.1}, $ \mathcal{E}(C_n)=\frac{2}{\sin \frac{\pi}{2n}} > \frac{2}{\pi/2n}=\frac{4n}{\pi}$. If \begin{equation}\label{eq1}
		\frac{4n}{\pi}\geq 2\tau(C_n),
	\end{equation} where $ \tau(C_n)=\frac{n+1}{2}=k+1 $. Now $\eqref{eq1} $ is true if and only if $ \frac{4(2k+1)}{\pi}\geq 2(k+1) $, i.e., $ k\geq 2 $. For $ k=1 $, $ C_3 $ is complete. Thus the result follows.
\end{proof}


\begin{lemma}
	Let $ u$ be a quasi-pendent vertex of $ G $ and $ \mathcal{E}(G-u)\geq 2\tau(G-u) $. Then $ \mathcal{E}(G)\geq 2\tau(G) $.
\end{lemma}

\begin{proof} 
	Let $v$ be a pendent vertex of $G$ such that  $ u\sim v $. Then any minimum vertex cover, say $ U $ of $ G $ must contain either $ u $ or $ v $. If it contains $ v $, then we can replace $ v $ by $ u $, and it will be still a minimum vertex cover of $ G $. Now we remove vertex $ u $, then $ \tau(G-u) =\tau(G)-1$. Let $ E $ be the edges from $ u $ to other vertices of $ V(G)\setminus\{v\} $. Then $ \mathcal{E}(G)\geq \mathcal{E}(G-E)=\mathcal{E}(G-u)\oplus[e_{u,v}] \geq 2\tau(G-u)+2=2\tau(G)$.	
\end{proof}



