\section{Structural amenability and the Signature method}\label{ap:smethod}~
\nc\calF{\mathcal{F}}
\nc\calX{\mathcal{X}}

\subsection*{Context}
For details and proofs of what is outlined here, see \cite{Pryce2001a}.
Roughly stated, a DAE is \Same if structural analysis (SA) of its sparsity \term{succeeds}: then it tells you how to solve the DAE numerically.
SA in this sense (electric circuit theory has a complementary kind of SA) began with the Pantelides algorithm \cite{Pant88b}, shown in \cite{Pryce2001a} to be equivalent to the \Smethod.

Pantelides's method is built into environments such as Modelica, gProms and EMSO \cite{openmodelica, gpromsUG, EMSO2010}, so any use of these popular systems tacitly assumes S-amenability.

\subsection*{The method}
The \Smethod applies to a DAE \rf{maindae}, of size $n$.
It has the following steps and basic ideas.

\begin{enumerate}[$\Sigma$1.]
\item\label{it:Sig1}
Form the $n\x n$ {\em signature matrix} $\Sigma=(\sij)$ where $\sij$ is the highest order of derivative of $x_j$ occurring in $\f_i$, or $\ninf$ if $x_j$ does not occur in $\f_i$.

\item\label{it:Sig2}
 A \term{transversal} is a set $\calT$ of $n$ positions $(i,j)$ in $\Sigma$ with exactly one in each row and each column.
It can be enumerated e.g.\ as $\calT= \{(1,j_1),(2,j_2),\dots,(n,j_n)\}$ where $(j_1,\dots,j_n)$ is a permutation of $1\:n$.
Its \term{value}, a finite integer or $\ninf$, is
\[\Val(\calT) :=\sum_{(i,j)\in\calT}\sij.\]

\item\label{it:Sig3}
 If a $\calT$ of finite value exists---i.e.\ no $\sij$ on it is $\ninf$---the DAE is \term{structurally well-posed} (SWP).
It then has at least one \term{highest-value transversal} (HVT), a $\calT$ of largest value, and we define the (finite) \term{value of $\Sigma$} to be $\Val(\Sigma) = \Val(\calT)$.

\item\label{it:Sig4}
 A pair of \term{offsets} is two integer vectors $c=(c_i,\ldots,c_n)$ and $d=(d_i,\ldots,d_n)$.
They are \term{weakly valid} if
\begin{align}\label{eq:offsets}
  d_j-c_i\ge\sij \quad\text{for all $i,\range j1n$},
\end{align}
and \term{valid} if also equality holds in \rf{offsets} for all $(i,j)$ on some transversal $\calT$.
In the latter case, $\calT$ is a HVT and equality holds on all HVTs, \cite[Lemma 3.3]{Pryce2001a}.

Adding the same constant to all $c_i$ and $d_j$ does not change the truth of \rf{offsets}, so without loss, weakly valid offsets can be \term{normalised}, meaning $\min_i c_i=0$.

\item\label{it:Sig5}
If valid offsets exist then necessarily the DAE is SWP, $\calT$ is an HVT, and $\Val(\Sigma)$ is also equal to $\sum_j d_j - \sum_i c_i$.

\item\label{it:Sig6}
If $c,d$ are weakly valid they define an $n\x n$ {\em \sysJ} $\~J(c,d) = (\~J_{ij})$ where (the two formulas are equivalent)
  \begin{align}\label{eq:sysJ}
    \~J_{ij}=
    \begin{cases*}
    \ds\tdbd{\f_i}{x_j^{(\sij)}} & if $d_j{-}c_i{=}\sij$, \\
      0 & otherwise
    \end{cases*}
  =
  \begin{cases*}
    \ds\tdbd{\f_i}{x_j^{(d_j-c_i)}} & if $d_j{-}c_i{\ge}0$, \\
     0 &otherwise.
  \end{cases*}
  \end{align}
  The \Smethod \term{succeeds}, and the DAE is \term{\Same}, if $\~J$ is nonsingular somewhere, see \cite{Pryce2001a} for a precise definition of ``somewhere''.
  Then $\Val(\Sigma)$ is the number of degrees of freedom $\dof$ of the DAE.

  If a nonsingular $\~J$ is found then pair $c,d$ must be valid by \lmref{valid_cd}.
  ``Success'' is independent of the valid $c,d$ chosen, since they all give the same $\det\~J$ value, \cite[Theorem 5.1]{nedialkov2005solving}.

\item\label{it:Sig7}
An SWP DAE has \term{canonical offsets}, for which the $c_i$ are elementwise smallest subject to being normalised.
  In case of success we define the \term{structural index} $\nu_s$ of the DAE to be the largest $c_i$ of the canonical offsets.

\item\label{it:Sig8} In case of success we have, for any normalised valid $(c,d)$, a {\em standard solution scheme} (SSS) as follows.
If a different $(c,d)$ exists, it just schedules the same operations in a different order, see \cite[Subsection 5.1]{nedialkov2005solving}.

\noindent For $k = k_d := -\max d_j$ to some maximum order $p$
\vspace{-2ex}
\begin{align}\label{eq:SSS}
\begin{aligned}
&  \text{solve the equations} &&\der{\f_i}{k+c_i}=0 &&\text{for those $i$ such that $k+c_i\ge0$} \\[-.75ex]
&  \text{for the unknowns} &&\der{x_j}{k+d_j} &&\text{for those $j$ such that $k+d_j\ge0$}
\end{aligned}\biggr\}\; .
\end{align}
For $k<0$ the SSS applies IVs; for $k\ge0$ it finds the TS to order $p$.

In this paper, the fact that the recurrence defined by \sodes coincides with what the SSS does, is our key to proving that \sodes are a sound approach.
\end{enumerate}
\smallskip

%\subsection*{A result}
\ssref{extract} uses the following, which we think is not proved elsewhere:
\begin{lemma}\label{lm:valid_cd}
  If offsets are weakly valid and give a nonsingular $\~J$, they are valid.
\end{lemma}
\begin{proof}
  We have $\det\~J\ne0$.
  By the formula for $\det\~J$ as a sum of $\pm$(product of $\~J_{ij}$ values on a transversal $\calT$), there is at least one $\calT$ on which all $\~J_{ij}\ne0$.
  By assumption, the offsets have $d_j-c_i\ge\sij$ for all $(i,j)$.
  Any $(i,j)$ where strict inequality holds gives $\~J_{ij}=0$ in \rf{sysJ}, so $d_j{-}c_i=\sij$ must hold on $\calT$, whence $\calT$ is an HVT.
\end{proof}

\begin{remark}
To find an HVT, one solves a linear assignment problem, e.g.\ by the Jonker--Volgenant algorithm \cite{JonkerVolgenant1987}.
This is a kind of linear programming (LP); many basic \Smethod objects/facts exemplify LP {\em duality}: \eg transversal = primal-feasible; HVT = primal-optimal; weakly valid = dual-feasible; valid = dual-optimal.

\end{remark}

\begin{remark}
  Structural index $\nu_s$ differs from the traditional differentiation index $\nu_d$.
  It is the least number of derivatives of any equation needed, to reduce to an ODE---in some subset of the $n$ variables $x_j$ but whose solution determines all of them.
  E.g., the system $0=\f_1 = x_1-\sin(t), 0=\f_2 = \xp_1-x_2$ needs 1 differentiation of $\f_1$ to find $(x_1,x_2)=(\sin(t),\cos(t))$, so $\nu_s = 1$.
  The ODE is of size zero in this case.
  But $\nu_d=2$, since one must differentiate again to get an ODE for $x_2$.
\end{remark}

