\label{fig: ptycho layout}
\end{figure}

To retrieve the phase from the ptychograms, we need the probe detunings relative to the object, which is given by the Doppler drive velocities. Before the experiment, the drive velocity at each MCS6A channel is calibrated using a known probe and object. The detuning for the \(j\)-th channel is given by:
\[
D_j = \frac{\omega_0}{c \Gamma}  \left( \vvv_{\text{max}} \cdot \cos \left( 2 \pi \cdot \frac{j - j_0}{1024} \right) + \vvv_{\text{iso}} \right),
\]
where \(\hbar \omega_0 = 14.41 \, \text{keV}\) and \(\Gamma = 4.66 \, \text{neV}\) for \(\Fe\), \(\vvv_{\text{max}}\) is the maximum velocity, and \(j_0\) corresponds to the channel with maximum velocity. We have also included a term $\vvv_\mathrm{iso}$ to capture the isomer shift between the two samples. The calibration is done by simulating the ptychogram using the detunings with Poisson sampling such that we get the same number of total counts as the experiment. The velocity parameters are then fitted via least squares. The process is outlined in Algorithm \ref{algo: v_calibration}, where the simulated photon counts are compared to the measured counts. The algorithm starts with initial guesses for \(\vvv_{\text{max}}\) and \(\vvv_{\text{iso}}\), and iterates until the best-fit values are obtained.
To start the algorithm, we initialized $(\vvv_\mathrm{max},\vvv_\mathrm{iso}, j_0)$= (25 mm s$^{-1}$, 0 mm s$^{-1}$, 1).
Using the parameters of the pre-characterized stainless steel and \(\Fe\) foils for simulations, we find \(\vvv_{\text{max}} = 20.70(3)\, \text{mm s$^{-1}$}\) and \(\vvv_{\text{iso}} = -0.10(1)\, \text{mm s$^{-1}$}\).

\begin{algorithm}
\caption{Velocity Calibration}
\label{algo: v_calibration}
\begin{algorithmic}[1]
\State \textbf{Input:} Photon counts $\{c_0, c_1, \dots, c_{M-1}\}$, energy domain responses $\zO^*$, $\zP^*$, initial guesses for maximum velocity $\vvv_\mathrm{max}$, isomer shift $\vvv_\mathrm{iso}$, and channel $j_0$
\State \textbf{Output:} Calibrated $\vvv_\mathrm{max}$, $\vvv_\mathrm{iso}$

\State \textbf{Step 1:} Calculate detunings $D_0, D_1, \dots, D_{M-1}$ using current guesses for $\vvv_\mathrm{max}$, $\vvv_\mathrm{iso}$, and $j_0$:\\
 \hspace{1cm} $D_0, D_1, \dots, D_{M-1} \gets \mathrm{CALC\_DETUNINGS}(\vvv_\mathrm{max}, \vvv_\mathrm{iso}, j_0)$

\State \textbf{Step 2:} Simulate the ptychogram using the calculated detunings and object/probe responses:\\
 \hspace{1cm} $\{\zb'_0, \zb'_1, \dots, \zb'_{M-1}\} \gets \mathrm{SIM\_HISTOGRAM}(\zO^*,\zP^*, D_0, D_1, \dots, D_{M-1})$

\State \textbf{Step 3:} Calculate the photon counts from the simulated ptychogram:\\
 \hspace{1cm} $c'_0, c'_1, \dots, c'_{M-1} \gets \sum_{q} \zb'_0, \sum_{q} \zb'_1, \dots, \sum_{q} \zb'_{M-1}$

\State \textbf{Step 4:} Perform least squares fitting to update $\vvv_\mathrm{max}$ and $\vvv_\mathrm{iso}$:\\
\hspace{1cm} $(\vvv'_\mathrm{max}, \vvv'_\mathrm{iso}) \gets \mathrm{LSQFIT}(\{c_0, c_1, \dots, c_{M-1}\}, \{c'_0, c'_1, \dots, c'_{M-1}\}, \vvv_\mathrm{max}, \vvv_\mathrm{iso})$

\State \textbf{Step 5:} Update the velocity parameters:\\
 \hspace{1cm} $\vvv_\mathrm{max} \gets \vvv'_\mathrm{max}, \vvv_\mathrm{iso} \gets \vvv'_\mathrm{iso}$

\State \textbf{Step 6:} Return calibrated $\vvv_\mathrm{max}$, $\vvv_\mathrm{iso}$

\end{algorithmic}
\end{algorithm}

For the phase reconstruction, a stepsize of 0.001 and momentum 0.66 were chosen to run the NuPty gradient descent algorithm.

