\title{A short note on application of $G$-theory on Epimorphism Problem in Affine Geometry } 
\author{Parnashree Ghosh \\ \small School of Mathematics, Tata Institute of Fundamental Research, Mumbai 400005, India \\ \small \texttt{pmaths@math.tifr.res.in, ghoshparnashree@gmail.com}}


\begin{document}

	\date{}
		\maketitle

	\begin{abstract}
		In this note we show application of $G$ theory in the Epimorphsm Problem for hypersurfaces in $\A^n$, by exhibiting a family of hypersurfaces satisfying Abhyankar-Sathaye's Epimorphism conjecture. 
	\end{abstract}


	\section{Introduction}
	In this note we investigate a particular case of the Epimorphism problem which asks the following:


	\noindent
	\textbf{Question:} Let $K$ be a field and $K[x_1, \ldots, x_n]/(G) = K^{[n-1]}$. Is then
	\[
	K[x_1, \ldots, x_n] = K[G]^{[n-1]}?
	\]

	\noindent
	\smallskip
	Several cases of this problem are studied in \cite{com}, \cite{adv2}, \cite{pre}, given by polynomials of the form
	\begin{equation}\label{1}
		G = \alpha(x_1, \ldots, x_n) y + f(z, t) + h,
	\end{equation}
	where every prime divisor of $\alpha$ divides $h$. 

	In this note we investigate an exception of the class of polynomial given by \ref{1}. We consider the following family of polynomials.

	\begin{equation}\label{2}
		G = x_1^{r_1}a_1(x_1) \cdots x_{m-1}^{r_{m-1}}a_{m-1}(x_{m-1})x_m^{r_m}a_m(x_m) y + f(z, t) + x_m, 
	\end{equation}
	where $r_i \geqslant 2$.

	Note that this family of polynomials is not contained in the family of polynomial given by (\ref{1}).

	\smallskip
	\noindent
	{\ Further note that if ${f(z,t)=0}$ defines a topological manifold over $\mathbb{C}$, then the epimorphism follows directly from work of Kaliman and Zaidenberg in \cite{afmod}. We work here without any assumption on $f$ and over fields of arbitrary characteristic}.







	\section{Epimorphism of the hypersurface }

	We will use the following result subsequently:

	\begin{prop}\thlabel{thm1}
		Let  $K$ be an infinite field and $G$ be as in (\ref{2}). If
		\[
		A = \frac{K[x_1, \ldots, x_m, y, z, t]}{(G)} = K^{[m+2]},
		\]

		then, upto a change of coordinate \( f(z, t) = a_0(z) + a_1(z) t \), such that \( \gcd(a_0(z), a_1(z)) = 1 \). In particular $\{f=0\}$ is a smooth curve.
	\end{prop}
	\begin{proof}
		Since $A$ is a UFD and $A^*=K^*$, $f(z,t)$ is irreducible by \cite[Proposition 3.5]{pre}.
		Now since $\mathrm{Ml}(A)=K$, the conclusion follows from \cite[Theorem 5.22]{pre}.
	\end{proof}




	\begin{thm}
		Let $K$ be any field, $G$ be as in (\ref{2}) and 	$ A = k[x_1,\ldots,m_m,y,z,t]/(G)=K^{[m+2]}$. Then $K[x_1, \ldots, x_m, y, z, t] = K[G]^{[m+2]} .$
	\end{thm}


	\begin{proof}
		Let us first assume, $K=\overline{K}$. Recall that 
		$$
		A= \frac{K[x_1, \ldots, x_m, y, z, t]}{\langle  x_1^{r_1}a_1(x_1) \cdots x_{m-1}^{r_{m-1}}a_{m-1}(x_{m-1})x_m^{r_m}a_m(x_m) y + f(z, t) + x_m \rangle} = K^{[m+2]}.
		$$

		Let $(x_1-\lambda_{j})$, $1\leq j \leq n$ be prime divisors of $x_1^{r_1}a_1(x_1)$ in $K[x_1]$.
		Note that 
		\[
		K[x_1, \ldots, x_m] \hookrightarrow A
		\]

		is a flat extension.

		Consider the following commutative diagram:


		\adjustbox{scale=0.9,center}{
		\begin{tikzcd}[row sep=large, column sep=small]
			\cdots \arrow{r} & G_{i+1}(\frac{K[x_1]}{\prod_{j=1}^{n}(x_1-\lambda_{j})}) \arrow{r} \arrow{d}{\cong} & G_{i+1}(K[x_1])\arrow{r} \arrow{d}{\cong} & G_{i+1}(K[x_1,\prod_{j=1}^{n}(x_1-\lambda_{j})^{-1}]) \arrow{r} \arrow{d} &G_i(\frac{K[x_1]}{\prod_{j=1}^{n}(x_1-\lambda_{j})}) \arrow{r} \arrow{d} {\cong} &G_i(K[x_1])\arrow{d}{\cong}\\
			\cdots \arrow{r}& G_{i+1}(\frac{A}{\prod_{j=1}^{n}(x_1-\lambda_{j})}) \arrow{r}  & G_{i+1}(A)\arrow{r} & G_{i+1}(A[\prod_{j=1}^{n}(x_1-\lambda_{j})^{-1}]) \arrow{r} &G_i(\frac{A}{\prod_{j=1}^{n}(x_1-\lambda_{j})}) \arrow{r} &G_i(A)
		\end{tikzcd}
		}

		From here we get that the flat morphism 
		\[
		K[x_1, \prod_{j=0}^{n}(x_1-\lambda_{j})^{-1},x_2,\ldots,x_m] \to A[\prod_{j=0}^{n}(x_1-\lambda_{j})^{-1}]=A_1[x_1,\prod_{j=0}^{n}(x_1-\lambda_{j})^{-1}] \quad \text{induces isomorphism of } G_i\text{-groups}
		\]

		where
		\[
		A_1 = \frac{K[x_2, \ldots, x_m, y, z, t]}{\left\langle x_2^{r_2}a_2(x_2) \cdots x_m^{r_m}a_m(x_m) y + f(z,t) + x_m \right\rangle}.
		\]

		Let $(x_2-\mu_j)$, $1 \leq j \leq l$ be the prime factors of $x_2^{r_2}a_2(x_2)$.
		In the next step, considering the commutative diagram of localisation sequences with respect to the element $\prod_{j=1}^{l}(x_2-\mu_j)$, induced by the flat map  
		$$
		K[x_1, \prod_{j=1}^{n}(x_1-\lambda_{j})^{-1},x_2,\ldots,x_m] \to A[\prod_{j=1}^{n}(x_1-\lambda_{j})^{-1}]=A_1[x_1,\prod_{j=0}^{n}(x_1-\lambda_{j})^{-1}], 
		$$
		we obtain the following isomorphism:
		$$
		G_i(K[x_1, \prod_{j=1}^{n}(x_1-\lambda_{j})^{-1},x_2,\prod_{j=1}^{l}(x_2-\mu_j)^{-1}\ldots,x_m]) \xrightarrow{\cong} G_i(A_2[x_1,\prod_{j=1}^{n}(x_1-\lambda_{j})^{-1}, x_2, \prod_{j=1}^{l}(x_2-\mu_j)^{-1}]) 
		$$
		for all $i$, where 
		$$
		A_2= \frac{K[x_3, \ldots, x_m, y, z, t]}{\left\langle x_3^{r_3}a_3(x_3) \cdots x_m^{r_m}a_m(x_m) y + f(z,t) + x_m \right\rangle}.
		$$
		Repeating this process $m-1$ times we obtain that the flat map 
		$$
		K[x_1, \prod_{j=1}^{n}(x_1-\lambda_{j})^{-1},\ldots,x_{m-1},\prod_{j=1}^{k}(x_{m-1}-\nu_j)^{-1},x_m] \rightarrow A_{m-1}[x_1,\prod_{j=1}^{n}(x_1-\lambda_{j})^{-1},\ldots, x_{m-1}, \prod_{j=1}^{k}(x_{m-1}-\nu_j)^{-1}] 
		$$
		induces isomorphism of $G_i$ groups for all $i$, where $(x_{m-1}-\nu_j)$ are prime factors of $x_{m-1}^{r_{m-1}}a_{m-1}(x_{m-1})$ and $$A_{m-1}=\frac{K[x_m, y, z, t]}{(a_m(x_m)x_m^{r_m} y + f(z, t) + x_m)}.$$



		Let $p_1,\ldots p_n$ be prime divisors of $a_m(x_m)x_m^{r_m}$, $S=k[x_1, \prod_{j=1}^{n}(x_1-\lambda_{j})^{-1},\ldots,x_{m-1},\prod_{j=1}^{k}(x_{m-1}-\nu_j)^{-1},x_m]$, $R=S/(p_1\ldots p_n)$ and $B=A_{m-1}[x_1, \prod_{j=1}^{n}(x_1-\lambda_{j})^{-1},\ldots,x_{m-1},\prod_{j=1}^{k}(x_{m-1}-\nu_j)^{-1}]$.

		Now, consider the commutative diagram:

		\[
		\begin{tikzcd}[row sep=large, column sep=small]
			\cdots \arrow{r} & G_{j+1}(S) \arrow{r} \arrow{d}{\cong} 
			& G_{j+1}(S[(p_1\ldots p_n)^{-1}]) \arrow{r} \arrow{d}{\cong} 
			& G_{j}(R) \arrow{r} \arrow{d} 
			& G_j(S) \arrow{r} \arrow{d}{\cong} 
			& G_j(S[ (p_1\ldots p_n)^{-1}]) \arrow{d}{\cong} \\
			\cdots \arrow{r}& G_{j+1}(B) \arrow{r}  & G_{j+1}(B[(p_1 \dots p_n)^{-1}])\arrow{r} & G_{j}(B/(p_1\ldots p_n)) \arrow{r} &G_j(A_1) \arrow{r} &G_j(A_1[(p_1 \ldots p_n)^{-1}]).
		\end{tikzcd}
		\]

		Now since, $p_i$'s are pairwise comaximal, from the above commutative diagram we get isomorphisms $G_j(S/p_i) \xrightarrow{\cong}G_j(B/p_i)$ for every $i$, $1\leqslant i \leqslant n$. 


		Thus for $p_i=x_m$ using \cite[Lemma 4.6]{pre}
		\[
		G_j\left(\frac{K[z, t]}{f(z, t)}\right) = G_j(K), \quad \text{for~} j=0,1.
		\]

		Now it follows that $\mathrm{Cl}(K[z,t]/(f))=0$ and $(K[z,t]/(f))^*=K^*$. Since $\{f=0\}$ defines a smooth curve (by Proposition \ref{thm1}) $K[z,t]/(f)=K^{[1]}$. 
		Thus for any field $K$  we have $\overline{K}[z,t]/(f)=\overline{K}^{[1]}$.



		If $K$ is a perfect field, then $f(z,t)=a_0(z)+a_1(z)t$ in $\overline{K}[Z,T]$ (by \thref{thm1}). As $\overline{K}[z,t]/(f)=\overline{K}^{[1]}$ it follows that $\overline{K}[z,t]=\overline{K}[f]^{[1]}$. Since separable $\A^1$-forms over PID are polynomial rings (cf. \cite{D}), we have $K[z,t]=K[f]^{[1]}$.

		If $K$ is not perfect, then using the fact that $f(z,t)=a_0(z)+a_1(z)t$ in $K[Z,T]$ (cf. \thref{thm1}) and $\overline{K}[z,t]/(f)=\overline{K}^{[1]}$ we have $K[z,t]=K[f]^{[1]}$.

		Therefore, over any field $K$ it follows that $K[x_1,\ldots,x_m,y,z,t]=K[G]^{[m+2]}$.

	\end{proof}

