\title{Varanus: Runtime Verification for CSP}


\author[1]{Matt Luckcuck \orcidlink{0000-0002-6444-9312}}
\author[2]{Angelo Ferrando \orcidlink{0000-0002-8711-4670}}
\author[3]{Fatma Faruq}
