\subsection{Asymptotics of the Free Energy}
Similar to the work of Barbier et al. in \cite{Barbier2020}, we expect that $1 - q = \text{MSE}$, and that the true free energy can be determined by fixed-point equations. This formulation allows for a direct validation of its equivalence to the TAP representation.

Under the assumption that $P_0\sim \mathcal{N}(0,1)$, the fourth moment of $P_0$ is 3 which is finite. Also, we can check that $P_0$ satisfies the Single-Crossing Property (As the verification is technical, we include the detailed calculations in Appendix B). This satisfies \cite[Assumption II, Assumption III]{reeves2019replica}. The mutual information for the denoising model $i(\tilde{S};\tilde{Y})$ in \eqref{MI_denoising_model} can then be expressed in a simplified form as:
\begin{align}
i(\tilde{S};\tilde{Y})=
-\frac{1}{2}\ln(\frac{\Sigma^2}{\Sigma^2+1}).
\end{align}
This result facilitates the calculation of RS potential in \eqref{RS_potential}, which can be expressed as:
\begin{align}\label{RS_GS}
    -i^{\mathrm{RS}}(E;\Delta) =\frac{E}{2\Sigma^2}- \frac{1}{2}\alpha \ln(1+E/(\alpha\Delta))+\frac{1}{2}\ln(\frac{\Sigma^2}{\Sigma^2+1}).
\end{align}

By setting its derivative to zero, the above equation can be further simplified to derive the fixed-point condition for $E$. Specifically, we obtain:
\begin{align}\label{fixed_point_condition}
    E=\frac{\alpha\Delta+E}{\alpha\Delta+E+\alpha}=\frac{\Sigma^2}{\Sigma^2+1},
\end{align}
which has a unique solution for $E\in(0,1)$.
Alternatively, this can be expressed as:
\begin{align}
E_\Delta=\frac{1-\alpha-\alpha\Delta+\sqrt{(\alpha\Delta+\alpha-1)^2+4\alpha\Delta}}{2}=T(\Delta).
    \label{closed_form_solution_E}
\end{align}
This result also suggests that the assumptions in \cite{Barbier2020}, specifically that $i^{\mathrm{RS}}(E;\Delta)$ has at most three stationary points, as well as Assumption III in \cite{reeves2019replica} are valid. Consequently, the RS formula is correctly established.

The R.H.S. of \eqref{theorem} can then be written as:
\begin{align}\label{RS_free_energy}
    -\min_{E\in [0,1]} i^{\mathrm{RS}}(E;\Delta)-\frac{\alpha}{2} =-\frac{\alpha}{2}+\frac{1}{2}(1-E_\Delta)-\frac{1}{2}\alpha \ln(1+E_\Delta/(\alpha\Delta))+\frac{1}{2}\ln(E_\Delta).
\end{align}
Observing the equivalence between $E_\Delta$ and $1-q_\Delta$, we can readily derive the following conclusion. 
%{\bf why there is $\min_{E\in [0,1]}$ on the left side, but not the right side?}

%{\color{blue}
%Comparing this with the restricted TAP free energy in \eqref{restricted_TAP_free_energy}, we observe that when $E=1-q$, the two expressions are identical, consistent with the observation made at the beginning of this subsection. Equivalently, \eqref{restricted_TAP_free_energy} and \eqref{RS_free_energy} are identical. In general,
%\begin{align}
%    \max_{\|a\|^2=(1-T(\Delta))p}f_{\mathrm{TAP}}(a)=-\min_{E\in [0,1]} i^{\mathrm{RS}}(E;\Delta)-\frac{\alpha}{2}.
%\end{align}
%}

\begin{lemma}\label{lower}
Let $f_{\mathrm{TAP}}$ and $i^{\mathrm{RS}}(E;\Delta)$ be defined as \eqref{tap_equation} and \eqref{RS_GS}. Then the TAP free energy provides a lower bound matching the replica prediction with convergence in probability:
\begin{align}   \lim_{p\to\infty}\max_{\|a\|^2\le p}f_{\mathrm{TAP}}(a)
    \ge -\min_{E\in [0,1]} i^{\mathrm{RS}}(E;\Delta)-\frac{\alpha}{2}.
\end{align}
\end{lemma}
\begin{proof}
With $a_{\Delta}$ defined in \eqref{e_ridge}, by lemma \ref{lem4} and \eqref{RS_free_energy}, we have:
\begin{align}   \lim_{p\to\infty}\max_{\|a\|^2\le p}f_{\mathrm{TAP}}(a)
\ge 
\lim_{p\to\infty}f_{\mathrm{TAP}}(a_{\Delta})
=-i^{\mathrm{RS}}(E_\Delta;\Delta)-\frac{\alpha}{2}
= -\min_{E\in [0,1]} i^{\mathrm{RS}}(E;\Delta)-\frac{\alpha}{2},
\end{align}  
with the convergence in probability.
\end{proof}

\subsection{Global Maximum}
% Now that we have proved that the restricted TAP free energy is equal to the RS free energy, we aim to show that $\max_{q=1-T(\Delta)}f_{\mathrm{TAP}}(1-E_0)= \max_{q\in[0,1]} f_{\mathrm{TAP}}$, thereby establishing the TAP free energy conjecture in the spherical case for all temperatures.


%Let $E_0$ be the unique solution to the quadratic equation, 
%\begin{align}
%E^2+(\alpha\Delta+\alpha-1)E
%=\alpha\Delta,
%\label{e_quad}
%\end{align}
%i.e. \eqref{fixed_point_condition}.
The preceding analysis shows that $f=f_{\mathrm{TAP}}(1-E_\Delta)\le \max_q f_{\mathrm{TAP}}(q)$, and $q_\Delta=1-E_\Delta$ is a stationary point of $f_{\mathrm{TAP}}$.

Define 
\begin{align}
g_{\mathrm{TAP}}(q):=\max_{\|a\|^2= pq}\{-\frac1{2\Delta p}\|y-Xa\|^2
\}-\frac{\alpha}{2}\ln(1+\frac{1-q}{\Delta\alpha})
+\frac1{2}\ln(1-q).
\label{e55}
\end{align}

The goal is to show that $q_\Delta=1-E_\Delta$ is (asymptotically) the global maximizer of $g_{\mathrm{TAP}}$.
Define
\begin{align}
g(q):=\max_{\|a\|^2=pq}\{-\frac1{2\Delta p}\|y-Xa\|^2\}-\frac{q}{2}
+C,
\label{e53}
\end{align}
where $C$ is a constant chosen such that $g(1-E_\Delta)=g_{\mathrm{TAP}}(1-E_\Delta)$,
that is,
\begin{align}
C:=\frac{1-E_\Delta}{2}
-\frac{\alpha}{2}\ln(1+\frac{E_\Delta}{\Delta\alpha})
+\frac1{2}\ln E_\Delta.
\label{e_c}
\end{align}

\begin{lemma}\label{lem7}
Let $g$ and $g_{\mathrm{TAP}}$ be defined as \eqref{e53} and \eqref{e55}. Then, for any $q\in[0,1]$, $
g_{\mathrm{TAP}}(q)\le g(q)    
$.
\end{lemma}
\begin{proof}
Define 
\begin{align}
h(q):= -q/2+C+\frac{\alpha}{2}\ln(1+\frac{1-q}{\Delta\alpha})
-\frac1{2}\ln(1-q),
\end{align}
with $C$ defined in \eqref{e_c}, so $h(1-E_0)=0$ by construction. 
The equation $h'(q)=0$ is equivalent to \eqref{fixed_point_condition} which has a unique solution for $q\in(0,1)$. 
Hence $h'(1-E_0)=0$ by the definition of $E_0$.
Furthermore, we observe that $h'(0)<0$ and $\lim_{q\uparrow 1}h'(q)=+\infty$.
Therefore $h'(q)>0$ for $q\in(1-E_0,1)$ and $h'(q)<0$ for $q\in(0,1-E_0)$.
Consequently, $g(q)-g_{\mathrm{TAP}}(q)=h(q)\ge0$ for $q\in(0,1)$.
\end{proof}

We are now ready to show the following:
\begin{lemma}\label{upper}
We have the matching upper bound:
\begin{align}   \lim_{p\to\infty}\max_{\|a\|^2\le p}f_{\mathrm{TAP}}(a)
\le -\min_{E\in [0,1]} i^{\mathrm{RS}}(E;\Delta)-\frac{\alpha}{2}.
\end{align}
\end{lemma}

\begin{proof}
We have
\begin{align}
\max_{\|a\|^2\le p}f_{\mathrm{TAP}}(a)
&= \sup_{q\in[0,1]} g_{\mathrm{TAP}}(q)
\\
&\le\sup_{q\in[0,1]} g(q)
\\
&\le \sup_{a\in\mathbb{R}^p}
\{-\frac{1}{2\Delta p}\|\mathbf{y}-\mathbf{x}a\|^2-\frac1{2p}\|a\|^2\}+C
\\
&= -\frac{1}{2\Delta p}\|\mathbf{y}-\mathbf{x}a_{\Delta}\|^2-\frac1{2p}\|a_{\Delta}\|^2+C.
\end{align}

Using the expressions for \( \|a_\Delta\|^2/p \) from \eqref{q_tr} and \( \|y - \mathbf{x}a_\Delta\|^2/p \) from \eqref{first_term}, we can evaluate the asymptotic value of the upper bound. Specifically, we have:
\begin{align}
    &\lim_{p\to\infty}\{-\frac{1}{2\Delta p}\|\mathbf{y}-\mathbf{x}a_{\Delta}\|^2-\frac1{2p}\|a_{\Delta}\|^2\}= -\frac{1}{2}(T(\Delta) + \alpha-1)-\frac{1}{2}(1-T(\Delta))
    =-\frac{\alpha}{2}.
\end{align}
This matches $C-\frac{\alpha}{2}=-i^{\mathrm{RS}}(E_\Delta;\Delta)-\frac{\alpha}{2}
= -\min_{E\in [0,1]} i^{\mathrm{RS}}(E;\Delta)-\frac{\alpha}{2}$. Therefore, the upper bound converges to the desired quantity, completing the proof.
\end{proof}

Combining the lower bound in Lemma \ref{lower} with the upper bound in Lemma \ref{upper}, we can conclude that
\begin{align}
    \lim_{p \to \infty} \max_{\|a\|^2 \leq p} f_{\mathrm{TAP}}(a) = -\min_{E\in [0,1]} i^{\mathrm{RS}}(E; \Delta) - \frac{\alpha}{2},
\end{align}
which establishes the asymptotic equivalence between the TAP free energy and the replica symmetric prediction for all $\Delta > 0$ under the uniform spherical prior. Together with the asymptotic formula for the true free energy established in Section 4.3, we complete the proof of Theorem \ref{theorem_1} and establish the asymptotic validity of the TAP free energy for all $\Delta > 0$ under the uniform spherical prior.


