\title{Spherical photon orbits around the Kerr-like black hole in Einstein-Bumblebee gravity}
\author{Shi-Yu Li$^{1}$}
%\email{syliphy@163.com}
\author{Song-Shan Luo$^{1}$}
%\email{ssluophy@163.com}
