\subsection{\texorpdfstring{$k$}--vector fields and integral sections}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


Let us review the theory of $k$-vector fields, which plays a crucial role in the geometric analysis of systems of partial differential equations \cite{LSV_15}. 

\begin{definition}
A {\it $k$-vector field} on $M$ is a section $\bfX\colon M\to\boplus^k\T M$ of the vector bundle $\pr_M\colon\bigoplus^k\T M\rightarrow M$. The space of $k$-vector fields on $M$ is denoted by $\X^k(M)$.
\end{definition}

Each $k$-vector field $\bfX\in\X^k(M)$ is equivalent to a family of vector fields $X_1,\dotsc,X_k\in\X(M)$, defined by $X_\alpha = \pr_M^\alpha\circ\bfX$ for $\alpha=1,\ldots,k$. This fact justifies denoting $\bfX:= (X_1,\dotsc, X_k)$. Moreover, a $k$-vector field $\bfX$ induces a decomposable contravariant skew-symmetric tensor field, $X_1\wedge\dotsb\wedge X_k$, which is a section of the bundle $\bigwedge^k\T M\to M$, and a generalised distribution $D^\bfX\subset TM$ spanned by $X_1, \ldots, X_k$.

\begin{definition}\label{dfn:first-prolongation-k-tangent-bundle}
   Given a map $\phi\colon U\subset\R^k\to M$, its {\it first prolongation} is the map $\phi'\colon U\subset\R^k\to\boplus^k\T M$ 
    defined as follows
    $$ \phi'(t) = \left( \phi(t); \T_t\phi\left( \parder{}{t^1}\bigg\vert_t \right),\dotsc,\T_t\phi\left( \parder{}{t^k}\bigg\vert_t \right) \right) := (\phi(t); \phi'_\alpha(t))\,, \qquad t=(t^1,\ldots,t^k)\in\R^k\,.
    $$
\end{definition}

The integral sections of a $k$-vector field are defined as follows.

\begin{definition}
    Let $\bfX = (X_1,\dotsc,X_k)\in\X^k(M)$ be a $k$-vector field. An {\it integral section} of $\bfX$ is a map $\phi\colon U\subset\R^k\to M$ such that $\phi' = \bfX\circ\phi\,$, namely $\T\phi \left(\parder{}{t^\alpha}\right) = X_\alpha\circ\phi$ for $\alpha=1,\ldots,k$. A $k$-vector field $\bfX\in\X^k(M)$ is {\it integrable} if $[X_\alpha,X_\beta]=0$ for $1\leq \alpha<\beta\leq k$.
\end{definition}

Let $\bfX = (X_1,\ldots, X_k)$ be a $k$-vector field on $M$ with local expression $ X_\alpha = X_\alpha^i\parder{}{x^i}\,$ for $\alpha=1,\ldots ,k$. Then, $\phi\colon U\subset\R^k\to M$ is an integral section of $\bfX$ if, and only if, its coordinates satisfy the following system of PDEs
\begin{equation}
\label{Eq::IntegralSections}
	\parder{\phi^i}{t^\alpha} = X_\alpha^i\circ\phi\,,\qquad i=1,\ldots,n,\qquad \alpha=1,\ldots,k\,.
\end{equation}
Then, \eqref{Eq::IntegralSections} is integrable if, and only if, $[X_\alpha,X_\beta] = 0$ for $1\leq \alpha<\beta\leq k$.

To simplify the notation, let us introduce the following. Given $\bm\theta = \theta^\alpha\otimes e_\alpha\in\Omega^\ell(P,\R^k)$ and $\bfX=(X_1,\ldots, X_k)\in\mathfrak{X}^k(M)$, the inner contraction of $\bm \theta$ with $\bfX$ is
\[
    \iota_{\bfX} \bm\theta := \langle \bm\theta,\bfX\rangle =\langle \theta^\alpha,X_\alpha\rangle:=\iota_{X_\alpha}\theta^\alpha\in\Omega^{\ell-1}(M)\,.
\]

\subsection{\texorpdfstring{$k$}{}-Symplectic geometry}

This section briefly surveys the theory of $k$-symplectic manifolds (for more details see \cite{LSV_15}). 

\begin{definition}
A {\it $k$-symplectic form} on $P$ is a closed nondegenerate $\bm\omega\in\Omega^2(P,\R^k)$. The pair $(P,\boldsymbol{\omega})$ is called a {\it $k$-symplectic manifold}. If the $\mathbb{R}^k$-valued two-form $\boldsymbol{\omega}$ is exact, namely $\boldsymbol{\omega} = \d\boldsymbol{\Theta}$ for some $\boldsymbol{\Theta} \in\Omega^1(P,\R^k)$, then $\bm\omega$ is said to be an {\it exact $k$-symplectic form} and the pair $(P,\bm\Theta)$ is an {\it exact $k$-symplectic manifold}.
\end{definition}
From now on, the pair $(P,\bm\omega)$ denotes a $k$-symplectic manifold.

\begin{definition}
 A \textit{polarised $k$-symplectic manifold} is a triple $(P,\bm\omega, \mathcal{V})$ such that $(P,\bm\omega)$ is a $k$-symplectic manifold of dimension $n(1+k)$ and there exists an integrable distribution $\mathcal{V}$ of rank $nk$ with ${\bm\omega}\vert_{\mathcal{V}\times \mathcal{V}} =0$.
\end{definition}

\begin{theorem}\label{Th:kSymTh}($k$-symplectic Darboux theorem)
Let $(P,\bm \omega, \cal V)$ be a polarised $k$-symplectic manifold. There exists a local coordinate system around each $x\in P$, given by $\{x^i,y^\alpha_i\}$ with $i=1,\ldots, n$ and $\alpha=1,\ldots,k$, such that 
\[
{\bm \omega}=  \d x^i\wedge \d y^\alpha_i\otimes e_\alpha\,,\qquad  \mathcal{V} =\left\langle \frac{\partial}{\partial y^\alpha_i}\right\rangle_{\substack{i=1,\ldots,n\\\alpha=1,\ldots,k}}\,.
\]
\end{theorem}
The coordinates $\{x^i,y^\alpha_i\}$ in the $k$-symplectic Darboux theorem are called {\it $k$-symplectic Darboux coordinates} or an {\it adapted coordinate system} (see \cite{GLRR_24} and references therein). Nevertheless, they are simply called Darboux coordinates hereafter, as it does not lead to any misunderstanding.

\begin{example}[Canonical model for polarised $k$-symplectic manifolds]\label{ex:canonical-model-k-symplectic}
    Let $Q$ be a manifold of dimension $n$. A coordinate system $\{q^i\}$ in $Q$ induces a natural coordinate system $\{q^i,p_i^\alpha\}$ in $\T^*_kQ:=\boplus^k\cT Q$. Consider the canonical form $\theta\in\Omega^1(\cT Q)$ in the cotangent bundle $\T^*Q$ satisfying $\omega = \d\theta\in\Omega^2(\cT Q)$. Hence, the Whitney sum $\T^*_k Q$ has the canonical forms taking values in $\mathbb{R}^k$ given by
    \[ 
    \bm{\theta}_{\T^*_kQ} = (\pr^\alpha_Q)^\ast\theta\otimes e_\alpha\ ,\qquad \bm \omega_{\T^*_kQ} = \d\bm\theta_{\T^*_kQ}\,, 
    \]
which, in adapted coordinates $\{q^i,p^\alpha_i\}$ for $\T^*_kQ$, read
    \[
    \bm \theta_{\T^*_kQ}= p_i^\alpha\d q^i\otimes e_\alpha \ ,\qquad \bm\omega_{\T^*_kQ} =- \d q^i\wedge\d p_i^\alpha\otimes e_\alpha \,.
    \]
Taking all this into account, $\big(\T^*_kQ,\boldsymbol{\omega}_{\T^*_kQ},{\cal V}_{\T^*_kQ}\big)$, with ${\cal V}_{\T^*_kQ} = \ker\T\pr_Q$, is a polarised $k$-symplectic manifold.  The coordinates $\{q^i,p_i^\alpha\}$ in $\T^*_kQ$ are {\it $k$-symplectic Darboux coordinates}. 
\end{example}



\subsection{\texorpdfstring{$k$}--Symplectic Hamiltonian systems}


This subsection recalls the formalism for $k$-symplectic Hamiltonian systems and $k$-symplectic Hamilton--De Donder--Weyl geometric equations \cite{LSV_15}.

Given a $k$-symplectic Hamiltonian system $(P,\bm\omega,h)$, we define the surjective vector bundle morphism over $P$ given by
\[
\begin{array}{rccl}
\flat_{\bm\omega}\colon & \boplus^k \T P & \longrightarrow &\cT P\\\noalign{\medskip}
 & \bm v =(v_1,\ldots,v_k)& \longmapsto & \flat_{\bm \omega}(\bm v)= \sum^k_{\alpha=1}\inn{v_\alpha}\omega^\alpha\,.
\end{array}
\]
The above morphism induces a morphism of $\Cinfty(P)$-modules  $\flat_{\bm \omega}\colon \mathfrak{X}^k(P)\to \bigwedge^1P$ between the corresponding space of sections $\mathfrak{X}^k(P)$ and $\bigwedge^1P$.

\begin{definition}\label{dfn:k-sympl-hamiltonian-system}
    A {\it $k$-symplectic Hamiltonian system} is a family $(P,\bm\omega,h)$, where $(P,\bm\omega)$ is a $k$-symplectic manifold and $h\in\Cinfty(P)$ is called a {\it $k$-symplectic Hamiltonian function}. The \textit{$k$-symplectic Hamilton--De Donder--Weyl equation} for $(P,\bm\omega,h)$ is the equation 
    \begin{equation}\label{eq::k-sym-HDW-FE}
        \flat_{\bm \omega}(\bfX)=\d h\,.
    \end{equation}
for a $k$-vector field $\bfX=(X_1,\ldots, X_k)\in\mathfrak{X}^k(P)$.

    A {\it $k$-symplectic gauge $k$-vector field} of $(P,\bm\omega)$ is a $k$-vector field on $P$ taking values in $\ker\flat_{\bm\omega}$.

    A $k$-vector field $\bfX$ that satisfies equation \eqref{eq::k-sym-HDW-FE} for some $h\in\Cinfty(P)$ is called a \textit{$k$-symplectic Hamiltonian $k$-vector field} of the $k$-symplectic Hamiltonian system $(P,\bm \omega, h).$ We denote by $\mathfrak{X}^k_h(P)$ the space of $k$-symplectic Hamiltonian $k$-vector fields of $(P,\bm\omega,h)$. Since $\flat_{\bm \omega}$ is surjective, every $h\in \Cinfty(P)$ is related to a $k$-symplectic Hamiltonian $k$-vector field, which is unique up to a $k$-symplectic gauge $k$-vector field.
\end{definition}

In Darboux coordinates, equation \eqref{eq::k-sym-HDW-FE} implies that a
$k$-symplectic Hamiltonian $k$-vector field $\bfX = (X_1,\ldots, X_k)\in\mathfrak{X}^k_h(P)$ on a polarised $k$-symplectic manifold can be written as
\[
X_\alpha=\parder{h}{p_i^\alpha}\displaystyle\frac{\partial}{\partial q^i}+(X_\alpha)^\beta_i\displaystyle\frac{\partial}{\partial p^\beta_i}\,,\qquad   \alpha=1,\ldots,k\,.\]
 where the functions $(X_\alpha)^\beta_i$ satisfy  $(X_\alpha)^\alpha_i = - \displaystyle\parder{h}{q^i}$.

A $k$-symplectic Hamiltonian $k$-vector field is not necessarily integrable, but to obtain the solutions of the Hamilton--De Donder--Weyl equations, the existence of integral sections is relevant.

\begin{proposition}
    Let $(P,\bm \omega, h)$ be a $k$-symplectic Hamiltonian system and consider an integrable $k$-symplectic Hamiltonian $k$-vector field $\bfX=(X_1,\ldots, X_k)$ for $(P,\bm \omega, h)$. Assume also that $(P,\bm \omega,\mathcal{V})$ is polarised. If $\psi\colon U\subset \mathbb{R}^k\to M$ is an integral section of $\bfX$, then $\psi$ is a solution of \emph{the Hamilton--De Donder--Weyl field equations} given by the following system of partial differential equations \cite{LV_15}
    \begin{equation}\label{eq:local_HDW_field_eq}
         \parder{h}{p_i^\alpha}\bigg\vert_{\psi(t)}=\parder{\psi^i}{t^\alpha}\bigg\vert_{t}\,,\qquad
        \parder{h}{q^i}\bigg\vert_{\psi(t)}=-\parder{\psi^\alpha_i}{t^\alpha}\bigg\vert_{t} \,
 \end{equation}
 is some $k$-symplectic Darboux coordinates.

\end{proposition}

\subsection{\texorpdfstring{$k$}--Contact geometry}

This section briefly surveys the theory of $k$-contact manifolds \cite{GGMRR_20} and generalised subbundles and other related notions of interest \cite{Lew_23}.

\begin{definition}
    Let $E\rightarrow M$ be a vector bundle over $M$. Then, 
    \begin{itemize}
        \item A \textit{generalised subbundle} on $M$ is a subset $D\subset E$ such that $D_x = D\cap E_x$ is a vector subspace of the fibre $E_x$ of the bundle $E$ of every $x\in M$. We call $\dim E_x$ the {\it rank} of $D$ at $x\in M$.

        \item A generalised subbundle $D\in E$ is \textit{smooth} if it is locally spanned by a family of smooth sections of $E\rightarrow M$ taking values in $D$, i.e. if there exists, for every $x\in M$, a family of sections $e_1, \ldots, e_r\colon U\subset M\rightarrow E|_U$ defined in a neighbourhood $U$ of $x$ such that $D_{x'}=\langle e_1(x'), \ldots, e_r(x')\rangle$ for every $x'\in U$. 
        \item A generalised subbundle $D$ is \textit{regular} if it is smooth and has constant rank. 
    \end{itemize}
\end{definition}

If $D$ is a regular generalised subbundle of constant rank $\ell$, we write $\rk D = \ell$. If $D$ has constant corank $\widetilde{\ell}$, we will write $\cork D = \widetilde{\ell}$.  

The {\it annihilator} of a generalised subbundle $D$ is the generalised subbundle $D^\circ=\bigsqcup_{x\in M} D^\circ_x$, where $D^\circ_x$ is the annihilator of $D_x$ at $x\in M$. If $D$ is not regular, $D^\circ$ is not smooth. If not otherwise stated, all structures are hereafter considered to be smooth. Using the usual identification $E^{\ast\ast} = E$ for a finite-dimensional vector bundle $E$ over $M$,  it follows that $(D^\circ)^\circ = D$. 

A generalised subbundle of $\T M\to M$ is hereafter called a {\it distribution}, while a generalised subbundle of $\cT M\to M$ is called a {\it codistribution}. It is worth noting that our terminology may differ from that in the literature, where distributions are always assumed to be regular, whereas distributions that are not regular are called generalised distributions or Stefan-Sussmann distributions. Nevertheless, we have simplified our terminology and skipped the term 'generalised'  as this will not lead to any misunderstanding.

Consider a differential one-form $\eta\in\Omega^1(M)$. Then, $\eta$ spans a smooth co-distribution $\mathcal{C} = \langle\eta\rangle = \{\langle\eta_x\rangle\mid x\in M\}\subset\cT M$. Thus, $\mathcal{C}$ has rank one at every point where $\eta$ does not vanish. The annihilator of $\mathcal{C}$ is the distribution $\ker \eta\subset\T M$. The distribution $\mathcal{C}^\circ$ has corank one at every point where $\eta$ does not vanish and zero otherwise.


\begin{definition}\label{dfn:k-contact-manifold}
    A \textit{$k$-contact form} on an open $U\subset M$ is a differential one-form on $U$ taking values in $\mathbb{R}^k$, let us say $\bm\eta = \sum_\alpha\eta^\alpha\otimes e_\alpha \in\Omega^1(U,\mathbb{R}^k)$, such that
    \begin{enumerate}[{\rm(1)}]
        \item $0\neq\ker \bm\eta\subset\T U$ is a regular distribution of corank $k$,
        \item $\ker \d\bm\eta\subset\T U$ is a regular distribution of rank $k$,
        \item $\ker \bm\eta\cap\ker \d\bm\eta  = 0$.
    \end{enumerate}
 A pair $(M,\bm\eta)$ is called a \textit{co-oriented $k$-contact manifold}. If, in addition, $\dim M = n+nk+k$ for some $n,k\in\mathbb{N}$ and $M$ is endowed with an integrable distribution $\mathcal{V}\subset \ker \bm\eta$ with $\rk\mathcal{V} = nk$, we say that $(M,\bm\eta,\mathcal{V})$ is a \textit{polarised co-oriented $k$-contact manifold}. We call $\mathcal{V}$ a \textit{polarisation} of $(M,\bm\eta)$.
\end{definition}

It is worth noting that a one-contact manifold is a contact manifold \cite{LRS_24}. We assume that there are no one-dimensional contact manifolds as in other works \cite{GG_23}, as the contact distribution would be zero dimensional and it would be inappropriate to call it maximally non-integrable.   Every co-orientable $k$-contact manifold gives rise to the so-called {\it Reeb vector fields}, which are a key element in $k$-contact geometry \cite{LSV_15}.  

\begin{theorem}\label{thm:k-contact-Reeb}
    Let $(M,\bm\eta)$ be a co-orientable $k$-contact manifold. There exists a unique family of vector fields $R_1, \ldots, R_k\in\X(M)$, called the \textit{Reeb vector fields} of $(M, \bm\eta)$, such that
    \begin{equation}\label{eq:k-contact-Reeb}
            \inn{R_\alpha}\eta^\beta = \delta_\alpha^\beta\,,\qquad
            \inn{R_\alpha}\d\bm\eta = 0\,,
    \end{equation}
    for $\alpha,\beta = 1,\dotsc,k$. Moreover, $[R_\alpha,R_\beta] = 0$ with $\alpha,\beta = 1,\dotsc,k$, while $\ker\d\bm\eta=\langle R_1,\dotsc, R_k \rangle$, and $R_1\wedge \ldots \wedge R_k$ is non-vanishing.
\end{theorem}

\begin{definition}
    Every $(M,\bm\eta)$ defines a vector bundle morphism over $M$
\[
\begin{array}{rccl}
\flat_{\bm\eta}\colon & \boplus^k \T M & \longrightarrow &\cT M\times\R \\\noalign{\medskip}
 & \bm v =(v_1,\ldots,v_k)& \longmapsto & \flat_{\bm \eta}(\bm v)=(\sum^k_{\alpha=1}\inn{v_\alpha}\d\eta^\alpha,\sum^k_{\alpha=1}\inn{v_\alpha}\eta^\alpha).
\end{array}
\]
A {\it $\bm\eta$-gauge $k$-vector field} of $(M,
    \bm\eta)$ is a $k$-vector field on $M$ taking values in $\ker\flat_{\bm\eta}$.
\end{definition}

Let us introduce a classical example of a co-oriented polarised $k$-contact manifold.

\begin{example}\label{ex:canonical-k-contact-structure}
    The manifold $M = (\boplus^k\cT Q)\times\R^k$ has a natural $k$-contact form
    $$ 
        \bm\eta_{Q}= (\d z^\alpha - \theta^\alpha)\otimes e_\alpha\,,
    $$
    where $\{z^1,\dotsc,z^k\}$ are the pull-back to $M$ of standard linear coordinates in $\R^k$ and each $\theta^\alpha$ is the pull-back of the Liouville one-form $\theta$ of the cotangent manifold $\cT Q$ with respect to the projection $M\to\cT Q$ onto the $\alpha$-th component of $\boplus^k\cT Q$. Note also that $M$ admits a natural projection onto $Q\times \mathbb{R}^k$ and a related vertical distribution $\mathcal{V}$ of rank $k\cdot\dim Q$ contained in $\ker \bm \eta_{Q}$. Hence, $\left((\boplus^k\cT Q)\times\R^k,\bm\eta_Q,\mathcal{V}\right)$ is a polarised co-oriented $k$-contact manifold.

    Local coordinates $\{q^1,\ldots,q^n\}$ on $Q$ induce natural coordinates $\{q^i,p_i^\alpha\}$, for a fixed value of $\alpha$, on the $\alpha$-th component of $\boplus^k\cT Q$ and $\{q^i,p_i^\alpha,z^\alpha\}$, with $\alpha=1,\ldots,k$, on $M$. Then,
    $$
        \bm\eta_{Q} = \left(\d z^\alpha - p_i^\alpha\d q^i\right)\otimes e_\alpha\,,\qquad
        \ker\bm\eta_{Q} = \left\langle \parder{}{p_i^\alpha}\,,\ \parder{}{q^i} + p_i^\alpha\parder{}{z^\alpha} \right\rangle\,.
    $$
    Hence, $\d\bm\eta_{Q} = (\d q^i\wedge\d p_i^\alpha)\otimes e_\alpha$, the Reeb vector fields are $ R_\alpha = \tparder{}{z^\alpha}$ for $\alpha=1,\ldots,k$, and
    $$
        \ker \d\bm\eta_{Q} = \left\langle\parder{}{z^1},\dotsc,\parder{}{z^k}\right\rangle\,.
    $$ 
    \demo

\end{example}




\begin{theorem}[$k$-contact Darboux Theorem \cite{GGMRR_20}]
\label{Th::PolkCon}
    Consider a polarised co-orientable $k$-contact manifold $(M, \bm\eta, \V)$. Then, around every point of $M$, there exist local coordinates $\{q^i,p_i^\alpha,z^\alpha\}$, with $1\leq\alpha\leq k$ and $1\leq i\leq n$, such that
    \[
    \bm\eta = \left(\d z^\alpha - p_i^\alpha\d q^i\right)\otimes e_\alpha\, , \quad \ker\bm\eta = \left\langle \parder{}{z^\alpha}\right\rangle\,,\quad \V = \left\langle\parder{}{p_i^\alpha}\right\rangle\,. 
    \]
    These coordinates are called \textit{Darboux coordinates} of the polarised co-orientable $k$-contact manifold $(M,\bm\eta,\mathcal{V})$.
\end{theorem}

Theorem \ref{Th::PolkCon} allows us to consider the manifold introduced in Example \ref{ex:canonical-k-contact-structure} as the canonical model of polarised co-oriented $k$-contact manifolds.


\subsection{\texorpdfstring{$k$}--Contact Hamiltonian systems}
\label{sub:k-contact-Hamiltonian-systems}

Let us present the basics of the Hamiltonian $k$-contact formulation of field theories with dissipation (for more details see \cite{GGMRR_20}).

\begin{definition}\label{dfn:k-contact-Hamiltonian-system}
    A \textit{$k$-contact Hamiltonian system} is a triple $(M,\bm\eta,h)$, where $(M,\bm\eta)$ is a co-oriented $k$-contact manifold and $h\in\Cinfty(M)$ is called an $\bm\eta$-\textit{Hamiltonian function}. Consider a map $\psi\colon U\subset\R^k\to M$, where $U$ is an open subset of $\R^k$. The \textit{$k$-contact Hamilton--De Donder--Weyl equations} related to $(M,\bm\eta,h)$ have the following form
    \begin{equation}\label{eq:k-contact-HDW}
            \inn{\psi_\alpha'}\d\eta^\alpha = \left( \d h - (R_\alpha h)\eta^\alpha \right)\circ\psi\,,\qquad
            \inn{\psi_\alpha'}\eta^\alpha = -h\circ\psi\,,
    \end{equation}
    where $\psi'(t)=(\psi_1'(t),\ldots, \psi_k'(t))\in \boplus^k\T M$ denotes the first prolongation (see Definition \ref{dfn:first-prolongation-k-tangent-bundle}).
\end{definition}
In Darboux coordinates for a polarised co-oriented $k$-contact manifold, equations \eqref{eq:k-contact-HDW} become
\begin{equation}\label{eq:k-contact-HDW-Darboux-coordinates} 
        \parder{\psi^i}{t^\alpha} = \parder{h}{p_i^\alpha}\circ\psi\,,\qquad
        \parder{\psi^\alpha_i}{t^\alpha} = -\left( \parder{h}{q^i} + p_i^\alpha\parder{h}{z^\alpha} \right)\circ\psi\,,\qquad
        \parder{\psi^\alpha}{t^\alpha} = \left( p_i^\alpha\parder{h}{p_i^\alpha} - h \right)\circ\psi\,,
\end{equation}
where $\psi^i=q^i\circ \psi$, $\psi^\alpha_i=p^\alpha_i\circ \psi$ and $\psi^\alpha=z^\alpha\circ \psi$. 
\begin{definition}
    Consider a $k$-contact Hamiltonian system $(M,\bm\eta,h)$. The \textit{$k$-contact Hamilton--De Donder--Weyl equations} for a $k$-vector field $\bfX = (X_\alpha)\in\X^k(M)$ are
    \begin{equation}\label{eq:k-contact-HDW-fields}
            \inn{X_\alpha}\d\eta^\alpha = \d h - (R_\alpha h)\eta^\alpha\,,\qquad
            \inn{X_\alpha}\eta^\alpha = -h\,.
    \end{equation} 

    A $k$-vector field $\bfX$ that satisfies equations \eqref{eq:k-contact-HDW-fields} is called a \textit{$k$-contact Hamiltonian $k$-vector field}. A $k$-contact Hamiltonian system gives rise to a family of $k$-contact Hamiltonian vector fields. Indeed, $\bfX+\mathbf{Y}$ for a $\bm\eta$-gauge $k$-vector field $\mathbf{Y}$ of $(M,\bm\eta,h)$ is again a $k$-contact Hamiltonian $k$-vector field for $(M,\bm\eta,h)$.
\end{definition}

Consider a $k$-vector field $\bfX = (X_1,\dotsc,X_k)\in\X^k(M)$ in Darboux coordinates for $(M,\bm\eta,\mathcal{V})$,
\[
    X_\alpha = (X_\alpha)^i\parder{}{q^i} + (X_\alpha)^\beta_i\parder{}{p_i^\beta} + (X_\alpha)^\beta\parder{}{z^\beta}\,,\qquad\alpha=1,\ldots,k.
\]    
Then, equations \eqref{eq:k-contact-HDW-fields} are equivalent to the following relations
\begin{equation}\label{eq:k-contact-HDW-fields-Darboux-coordinates}
        (X_\alpha)^i = \parder{h}{p_i^\alpha}\,,\qquad
        (X_\alpha)^\alpha_i = -\left( \parder{h}{q^i} + p_i^\alpha\parder{h}{z^\alpha} \right)\,,\qquad
        (X_\alpha)^\alpha = p_i^\alpha\parder{h}{p_i^\alpha} - h\,.
\end{equation}

\begin{proposition}\label{prop:k-contact-equiv-fields-sections}
    Given an integrable $k$-vector field $\bfX\in\X^k(M)$, every integral section $\psi\colon U\subset\R^k\to M$ of $\bfX$ satisfies the $k$-contact Hamilton--De Donder--Weyl equation \eqref{eq:k-contact-HDW} if, and only if, $\bfX$ is a solution to \eqref{eq:k-contact-HDW-fields}.
\end{proposition}

It is worth noting that the existence of a $k$-vector field satisfying equations \eqref{eq:k-contact-HDW-fields} does not imply the existence of its integral sections in general.


\begin{proposition}
    The $k$-contact Hamilton--De Donder--Weyl equations \eqref{eq:k-contact-HDW-fields} are equivalent to
    \begin{equation}\label{eq:k-contact-HDW-alternative}
        \begin{dcases}
            \Lie_{\bfX}\bm\eta:=\Lie_{X_\alpha}\eta^\alpha=\inn{\bfX}\d\bm\eta+\d\inn{\bfX}\bm\eta = -(R_\alpha h)\eta^\alpha\,,\\
            \inn{\bfX}\bm\eta=\inn{X_\alpha}\eta^\alpha = -h\,.
        \end{dcases}
    \end{equation}
\end{proposition}

\begin{example}[The damped wave equation]

    A vibrating string can be described using a $k$-contact Hamiltonian formalism \cite{GGMRR_20}. Consider the coordinates $\{t,x\}$ for $\R^2$ and set $Q=\R$. The phase space becomes $\boplus^2\T^\ast \R\times\R^2$ and admits coordinates $(u,p^t,p^x,s^t,s^x)$. Denote by $u$ the separation of a point in the string from its equilibrium point, while $p^t$ and $p^x$ will denote the momenta of $u$ with respect to the two independent variables. We endow $\bigoplus^2\cT\R\times\R^2$ with its natural two-contact form $\bm\eta$, see Example \ref{ex:canonical-k-contact-structure}. A Hamiltonian function for the vibrating string can be chosen to be $h\in\Cinfty ( \boplus^2 \T^*\R\times \R^2)$ of the form
\begin{equation}\label{eq:Lagrangian-vibrating-string}
    h(u,p^t,p^x,s^t,s^x) = \frac{1}{2\rho}(p^t)^2 - \frac{1}{2\tau}(p^x)^2+ ks^t,
\end{equation}
where $\rho$ is the linear mass density of the string, $\tau$ is the tension of the string,  and $k>0$. We assume that $\rho, \tau, k$ are constant. Then, the two-contact Hamiltonian two-vector field $\bfX=(X^1,X^2)$ reads
\begin{align}
X^1&=\frac{p^t}{\rho}\parder{}{u}+A^1_t\parder{}{p^t}+A^1_x\parder{}{p^x}+B^1_t\parder{}{s^t}+B^1_x\parder{}{s^x},\\
X^2&=-\frac{p^x}{\tau}\parder{}{u}+A^2_t\parder{}{p^t}-(kp^t+A^1_t)\parder{}{p^x}+B^2_t\parder{}{s^t}+\left(\frac{(p^t)^2}{2\rho}-\frac{(p^x)^2}{2\tau}-ks^t-B^1_t\right)\parder{}{s^x},
\end{align}
where $A^1_t,A^1_x,B^1_t,B^1_x,A^2_t,B^2_t$ are arbitrary functions on $M$. For instance, by choosing $B^1_x$ and $B^2_t$ to be independent of $s^t$ and $s^x$, and setting $A^2_t,B^1_t,A^1_x=0$ and $A^1_t=-kp^t$, it follows that $\bfX$ becomes an integrable $k$-vector field. Thus, the Hamilton--De Donder--Weyl field equations are
\begin{equation}
 	\begin{dcases}
 		\parder{u}{t} = \frac{1}{\rho}p^t\,,\\
 		\parder{u}{x} = -\frac{1}{\tau}p^x\,,\\
 		\parder{p^t}{t} + \parder{p^x}{x} = -k p^t\,,\\
   \parder{s^t}{t}+\parder{s^x}{x}=\frac{1}{2\rho}(p^t)^2- \frac{1}{2\tau}(p^x)^2 -k s^t \,.
 	\end{dcases}
 \end{equation}
Hence, by substituting the first and second equations in the third, one obtains
$$
    \frac{\partial^2 u}{\partial t^2}-c^2 \frac{\partial^2 u}{\partial x^2} + k \frac{\partial u}{\partial t} = 0 \,,
$$
where $c^2 = \dfrac{\tau}{\rho}$, that is, the damped wave equation.
\demo
\end{example}

\section{Reduction of exact \texorpdfstring{$k$}--symplectic manifolds}\label{Sec::RedHomSym}

This section presents the modified $k$-symplectic MMW reduction for exact $k$-symplectic manifolds. As demonstrated in subsequent sections, the reduction is adjusted to retrieve the reduced $k$-contact geometric structure from the reduced $k$-symplectic one. 

\subsection{\texorpdfstring{$k$}{}-Symplectic momentum maps}
\label{Sec::SymMomentuMap}

Let us survey the theory of $k$-symplectic momentum maps, focusing on essential definitions related to the $k$-symplectic and $k$-contact MMW  reduction. In general, the presented results do not restrict to $\Ad^{*k}$-equivariant momentum maps (see \cite{LRVZ_23} for details). However, this paper focuses on $\Ad^{*k}$-equivariant momentum maps, which is justified by Proposition \ref{Prop::AdEqkCon}. Set $\mathfrak{g}^k=\mathfrak{g}\times\stackrel{k}{\dotsb}\times\mathfrak{g}$, and analogously, $(\mathfrak{g}^*)^k=\mathfrak{g}^*\times\stackrel{k}{\dotsb}\times\mathfrak{g}^*$, where $\mathfrak{g}^*$ is the dual space to the Lie algebra $\mathfrak{g}$.

Let us recall some technical notions. A {\it weak regular value} \cite{AM_78} of a map $F:M\rightarrow N$ is a point $y\in N$ such that $F^{-1}(y)$ is a submanifold of $M$ and $\T_xF^{-1}(y)=\ker\T_xF$ for every $x\in F^{-1}(y)$. Additionally, a Lie group action $\Phi: G\times M\rightarrow M$ is {\it quotientable} when the space of orbits of the Lie group action $G$ on $M$, denoted by $M/G$, is a manifold and the projection $\pi: M\rightarrow M/G$ is a submersion. If $\Phi$ is free and proper, it is quotientable \cite{Lee_12}.

This work focuses primarily on exact $k$-symplectic manifolds, which are a specific case of $k$-symplectic manifolds. Therefore, we introduce the well-known definitions adjusted to this context. Nevertheless, some of the results presented hold in a more general framework, so we also provide the definitions for $k$-symplectic manifolds in the general setting.

\begin{definition}
\label{Def::Onohomoaction}
    A Lie group action $\Phi\colon G\times P\to P$ is an \textit{exact $k$-symplectic Lie group action} relative to $(P, \bm\Theta)$ if $\Phi_g^*\boldsymbol\Theta=\boldsymbol\Theta$ for each $g\in G$, where $\Phi_g:P\ni p \mapsto \Phi_g(p):=\Phi(g,p)\in P$. In other words,
    \begin{equation}
        \Lie_{\xi_P}\bm\Theta = 0\,,\qquad \forall \xi\in\mathfrak{g}\,,
    \end{equation}
    where $\xi_P$ is the fundamental vector field of $\Phi$ related to $\xi\in\mathfrak{g}$, namely $\xi_P(p) = \restr{\frac{\d}{\d t}}{t=0}\Phi(\exp(t\xi),p)$ for any $p\in P$.
\end{definition} 

A $k$-symplectic momentum map for an exact $k$-symplectic manifold $(P,\bm\Theta)$ is defined using the exactness.

\begin{definition}
\label{Def::MomentumMap1homo}
     An {\it exact $k$-symplectic momentum map} associated with $(P,\bm\Theta)$ and an exact $k$-symplectic Lie group action $\Phi:G\times P\rightarrow P$ is a map $\mathbf{J}^\Phi_{\bm\Theta}:P\rightarrow (\mathfrak{g}^*)^k$ such that
    \begin{equation}
    \label{Eq::coMomentumMaphomo}
    \iota_{\xi_P}\bm\Theta=\langle \mathbf{J}^\Phi_{\bm\Theta},\xi\rangle,\qquad \forall \xi\in\mathfrak{g}\,.
    \end{equation}
\end{definition}
Equation \eqref{Eq::coMomentumMaphomo} implies that $\mathbf{J}^\Phi_{\bm\Theta}$ satisfies \(\inn{\boldsymbol{\xi}_P}\boldsymbol{\Theta}=\left\langle \mathbf{J}^\Phi_{\bm\Theta},\boldsymbol{\xi}\right\rangle\), where $\bm \xi=(\xi^1,\ldots,\xi^k)\in \mathfrak{g}^k$. Conversely, if $\bm \xi_P$ is the $k$-vector field on $P$ whose $k$ components are the fundamental vector fields of $\Phi:G\times P\rightarrow P$ related to the $k$ components of $\bm\xi\in\mathfrak{g}^k$, the relation above implies \eqref{Eq::coMomentumMaphomo}.

If $\Phi:G\times P\rightarrow P$ is an exact $k$-symplectic Lie group action, then 
\[
\d\iota_{\xi_P}\bm\Theta=-\iota_{\xi_P}\bm\omega,\qquad \forall \xi\in\mathfrak{g}.
\]
Thus, one obtains a $k$-symplectic momentum map defined in the standard way, as in the following definitions.

\begin{definition}
    A Lie group action $\Phi\colon G\times P\to P$ is a \textit{$k$-symplectic Lie group action} relative to $(P,\bm\omega)$ if $\Phi_g^*\boldsymbol\omega=\boldsymbol\omega$ for each $g\in G$, where $\Phi_g:P\ni p \mapsto \Phi_g(p):=\Phi(g,p)\in P$. In other words,
    \begin{equation}
        \Lie_{\xi_P}\bm\omega = 0\,,\qquad \forall \xi\in\mathfrak{g}\,,
    \end{equation}
    where $\xi_P$ is the fundamental vector field of $\Phi$ related to $\xi\in\mathfrak{g}$, namely $\xi_P(p) = \restr{\frac{\d}{\d t}}{t=0}\Phi(\exp(t\xi),p)$ for any $p\in P$.
\end{definition} 

\begin{definition}\label{Def::symMomentumMap}
    A {\it $k$-symplectic momentum map} associated with a Lie group action $\Phi: G\times P\rightarrow P$ with respect to $(P,\boldsymbol\omega)$ is a map $\mathbf{J}^\Phi:=\left(\mathbf{J}^\Phi_1,\ldots,\mathbf{J}^\Phi_k\right):P\rightarrow (\mathfrak{g}^*)^k$ such that
    \begin{equation}\label{Eq::coMomentumMap}
        \inn{\xi_P}\boldsymbol\omega=(\inn{\xi_P}\omega^\alpha)\otimes e_\alpha=-\d\left\langle \mathbf{J}^\Phi,\xi\right\rangle \,,\qquad \forall \xi\in \mathfrak{g}\,.
    \end{equation}
\end{definition}

The following definition is well-known in the literature, but $\Ad^{*k}_{g^{-1}}$ is sometimes denoted as ${\rm Coad}^k_g$. However, it has been changed to $\Ad^{*k}$ to shorten and clarify the notation.

\begin{definition}
    A $k$-symplectic momentum map $\mathbf{J}^\Phi\colon P\rightarrow (\mathfrak{g}^*)^k$ is {\it $\Ad^{*k}$\!-equivariant} if
    \[
    \mathbf{J}^\Phi\circ \Phi_g =\Ad^{*k}_{g^{-1}}\circ\,\, \mathbf{J}^\Phi\,,\qquad \forall g\in G\,,
    \]
    \begin{minipage}{11cm}
    where $\Ad^{*k}_{g^{-1}}=\Ad^*_{g^{-1}}\stackrel{}\otimes \overset{(k)}{\dotsb}\otimes \Ad^*_{g^{-1}}$ and
    \[
    \begin{array}{rccc}
    \Ad^{*k}&:G\times(\mathfrak{g}^*)^k & \longrightarrow & (\mathfrak{g}^*)^k\\
    & (g,\boldsymbol \mu) &\longmapsto & \Ad^{*k}_{g^{-1}}\boldsymbol\mu\,
    \end{array}
    \]
In other words, the diagram aside is commutative for every $g\in G$.
\end{minipage}
\begin{minipage}{4cm}
    \begin{tikzcd}
    P
    \arrow[r,"\mathbf{J}^\Phi"]
    \arrow[d,"\Phi_g"]& (\mathfrak{g}^*)^k
    \arrow[d,"\Ad^{*k}_{g^{-1}}"]\\
    P
    \arrow[r,"\mathbf{J}^\Phi"]&
    (\mathfrak{g}^*)^k.
    \end{tikzcd}
\end{minipage}
\end{definition}

\begin{proposition}
\label{Prop::AdEqkSym}
    An exact $k$-symplectic momentum map $\mathbf{J}^\Phi_{\bm\Theta}\colon P\rightarrow (\mathfrak{g}^*)^k$ associated with a Lie group action $\Phi:G\times P\rightarrow P$ related to an exact $k$-symplectic manifold $(P,\bm\Theta)$ is $\Ad^{*k}$-equivariant.
\end{proposition}
The proof amounts to showing that $\mathbf{J}^\Phi_{\bm\Theta}(\Phi_g(p))=\Ad^{*k}_{g^{-1}}\mathbf{J}^\Phi_{\bm\Theta}(p)$ for each $p\in P$ and every $g\in G$, and it follows from $\Phi_{g*}\xi_P=(\Ad^*_{g^{-1}}\xi)_P$, see \cite{AM_78}. A $k$-symplectic momentum map associated with a $k$-symplectic Lie group action is not necessarily $\Ad^{*k}$-equivariant \cite{LRVZ_23}. However, only $\Ad^{*k}$-equivariant momentum maps are relevant in this work. Therefore, it is hereafter assumed that $\mathbf{J}^\Phi: P\rightarrow (\mathfrak{g}^*)^k$ is $\Ad^{*k}$-equivariant.

\subsection{\texorpdfstring{$k$}{}-Symplectic reduction by a submanifold}

This section surveys the well-known  $k$-symplectic reduction by a submanifold \cite{MRSV_15}. To study $k$-symplectic reduction by a submanifold, it is important to consider the $k$-symplectic orthogonal notion (see \cite{LV_13} for details).

\begin{definition}
The {\it $k$-symplectic orthogonal} of $W_p\subset \T_pP$ at some point $p\in P$ with respect to $(P,\bm\omega)$ is
\[
W_p^{\perp_k} := \{v_p\in \T_p P\mid \bm\omega(w_p,v_p)=0\,,\,\, \forall w_p\in W_p\}.
\]
\end{definition}

In the $k$-symplectic setting, we will deal with a weak regular value $\bm\mu \in (\mathfrak{g}^*)^k$ of a $k$-symplectic momentum map $\mathbf{J}^\Phi: P \rightarrow (\mathfrak{g}^*)^k$. However, it is not enough to assume that $\bm\mu\in(\mathfrak{g}^*)^k$ is a weak regular value since it is crucial that for each of the components of the momentum map, $\mathbf{J}^{\Phi-1}_\alpha(\mu^\alpha)$ is a submanifold of $P$. Therefore, we say that $\bm\mu \in (\mathfrak{g}^*)^k$ is a {\it weak regular $k$-value} of $\mathbf{J}^\Phi$, if $\mu^\alpha \in \mathfrak{g}^*$ is a weak regular value of $\mathbf{J}^\Phi_\alpha: P \rightarrow \mathfrak{g}^*$ for $\alpha=1,\ldots,k$ and $\bm\mu$ is a weak regular value of $\mathbf{J}^{\Phi-1}(\bm\mu)$. This implies that $\mathbf{J}^{\Phi-1}(\bm\mu)$ is a submanifold of $P$, however, the converse does not necessarily hold.

The following theorem plays an important role in our $k$-contact reduction (see \cite{LV_13, MRSV_15} for a proof). Recall that $S/\mathcal{F}$, for a submanifold $S$ and a foliation  $\mathcal{F}$ of $S$, stands for the space of leaves of the foliation in $S$.

\begin{theorem}
    \label{Th::RedGen}($k$-symplectic reduction by a submanifold.)
   Let $S$ be a submanifold of $P$ with an injective immersion $\jmath:S\hookrightarrow P$. Assume that $\ker \jmath^*\bm\omega$ has a constant rank for $(P,\bm\omega)$, the quotient space $S/\mathcal{F}_S$ is a manifold, where $\mathcal{F}_S$ is a foliation on $S$ given by $\ker\jmath^*\bm\omega$, and assume that the canonical projection $\pi: S\rightarrow S/\mathcal{F}_S$ is a submersion. Then, $(S/\mathcal{F}_S,\bm\omega_{S})$ is a $k$-symplectic manifold defined univocally by
   \[
   \jmath^*\bm\omega=\pi^*\bm\omega_S,
   \]
   and $\ker \jmath^*\bm\omega_p=\T_pS\cap\left( \T_p S\right)^{\perp_k}$ for any $p\in S$.
\end{theorem}
Let us recall the following lemma (see \cite{MRSV_15} for the proof).
\begin{lemma}
    Let $\bm\mu=(\mu^1,\ldots,\mu^k)\in(\mathfrak{g}^*)^k$ be a weak regular $k$-value of a $k$-symplectic momentum map $\mathbf{J}^\Phi:P\rightarrow (\mathfrak{g}^*)^k$ associated with a Lie group action $\Phi:G\times P\rightarrow P$ and $(P,\bm\omega)$. Then,
    \[
    G_{\bm\mu}=\bigcap^k_{\alpha=1}G_{\mu^\alpha},\qquad \mathfrak{g}_{\bm\mu}=\bigcap^k_{\alpha=1}\mathfrak{g}_{\mu^\alpha},
    \]
    where $G_{\bm\mu}$ is the isotropy subgroup of $\bm\mu\in(\mathfrak{g}^*)^k$ under the Lie  group action $\Ad^{*k}$ and $\mathfrak{g}_{\bm\mu}$ is its Lie algebra.
\end{lemma}



Let us recall the following well-known result from $k$-symplectic geometry, which is not exactly analogous to the symplectic setting. It is important that, in general, $((\T_xN)^{\perp_k})^{\perp_k}\neq \T_xN$, where $N$ is any submanifold of $P$ and $x\in N$. Indeed, this led to several errors in some attempts to devise a $k$-symplectic reduction \cite{Gun_87, MRSV_15}.

\begin{lemma}
\label{Lemm::NonAdPerpPS}
Let $\bm\mu\in(\mathfrak{g}^*)^k$ be a weak regular $k$-value of a $k$-symplectic momentum map ${\bf J}^\Phi:P\rightarrow (\mathfrak{g}^*)^k$. Then, for every $p\in {\bf J}^{\Phi-1}(\bm\mu)$, one has 
\begin{enumerate}[{\rm(1)}]
\item $\T_{p}(G_{\bm\mu} p) =\T_{p}(G p)\cap \T_{p}\left({\bf J}^{\Phi-1}({\bm\mu})\right)$, 
\item $\T_{p}({\bf J}^{\Phi-1}(\bm\mu)) = \T_{p}(Gp)^{\perp_k}$.
\end{enumerate}
\end{lemma}


\subsection{Marsden--Meyer--Weinstein reduction theorem for exact \texorpdfstring{$k$}{}-symplectic manifolds}

In this subsection, we present the proof of the modified $k$-symplectic MMW  reduction (Theorem \ref{Th::PolisymplecticReductionJ}). First, we recall a classical $k$-symplectic reduction theorem \cite{MRSV_15}. Then, we introduce a certain Lie subgroup of $G$ that allows for the reduction of $k$-contact manifolds and present its basic properties. Moreover, we examine an extension of Lemma \ref{Lemm::NonAdPerpPS} in the symplectic setting \cite[Lemma 4.3.2]{AM_78}. 

The following theorem is a standard $k$-symplectic MMW reduction theorem. Its proof is based on the restriction of Lemma \ref{Lemm::NonAdPerpPS} to the symplectic setting, i.e. when $k=1$, $(P,\omega)$ becomes symplectic, and then $((\T N)^{\perp_1})^{\perp_1}=\T N$ for any submanifold $N$ of $P$ (see \cite{CLRZ_23,MRSV_15} for details).


\begin{theorem}
\label{Th::PolisymplecticReductionJ}
    Let $(P,\bm\omega)$ be a $k$-symplectic manifold and let $\mathbf{J}^\Phi:P\rightarrow (\mathfrak{g}^*)^k$ be a $k$-symplectic momentum map associated with a $k$-symplectic Lie group action $\Phi\colon G\times P\rightarrow P$. Assume that $\boldsymbol\mu=(
    \mu^1,\ldots,
    \mu^k)\in (\mathfrak{g}^*)^k$ is a weak regular $k$-value of $\mathbf{J}^\Phi$ and $G_{\boldsymbol{\mu}}$ acts in a quotientable manner on $\mathbf{J}^{\Phi-1}(\boldsymbol\mu)$. Let $G_{\mu^\alpha}$ denote the isotropy subgroup at $\mu^\alpha$ of the Lie group action $\Ad^*\colon(g,\vartheta)\in G\times\mathfrak{g}^*\mapsto  \Ad^*(g,\vartheta)\in \mathfrak{g}^*$ for $\alpha=1,\ldots,k$. Moreover, let the following (sufficient) conditions be assumed
    \begin{equation}\label{Eq::symplecticReduction1eq}
        \ker (\T_p\mathbf{J}_\alpha^\Phi) = \T_p(\mathbf{J}^{\Phi-1}(\boldsymbol\mu))+\ker\omega^\alpha(p) + \T_p(G_{\mu^\alpha} p)\,,\qquad \alpha=1,\ldots,k\,,
    \end{equation}
    \begin{equation}\label{Eq::symplecticReduction2eq}
        \T_p(G_{\boldsymbol\mu} p) = \bigcap^k_{\alpha=1}\left(\ker\omega^\alpha(p)+\T_p(G_{\mu^\alpha}p)\right)\cap \T_p(\mathbf{J}^{\Phi-1}(\boldsymbol\mu))\,,
    \end{equation}
    for every $p\in {\bf J}^{\Phi-1}({\boldsymbol \mu})$. Then,  $(P_{\bm\mu}:=\mathbf{J}^{\Phi-1}(\boldsymbol\mu)/G_{\boldsymbol\mu},\bm\omega_{\boldsymbol\mu})$ is a $k$-symplectic manifold with ${\bm\omega}_{\boldsymbol \mu}\in\Omega^2(P_{\bm\mu},\R^k)$ being uniquely determined by
    \[ \pi_{\boldsymbol\mu}^*\bm\omega_{\boldsymbol\mu}=\jmath_{\boldsymbol\mu}^*\bm\omega\,,
    \]
    where $\jmath_{\boldsymbol\mu}\colon\mathbf{J}^{\Phi-1}(\boldsymbol\mu)\hookrightarrow P$ is the canonical immersion and $\pi_{\boldsymbol\mu}\colon \mathbf{J}^{\Phi-1}(\boldsymbol\mu)\rightarrow \mathbf{J}^{\Phi-1}(\boldsymbol\mu)/G_{\boldsymbol\mu}$ is the canonical projection.
\end{theorem}


Conditions \eqref{Eq::symplecticReduction1eq} and \eqref{Eq::symplecticReduction2eq} ensure that $\ker\jmath_{\bm\mu}^*\bm\omega_p=\T_p\mathbf{J}^{\Phi-1}(\bm\mu)\cap\left(\T_p\mathbf{J}^{\Phi-1}(\bm\mu)\right)^{\perp_k}=\T_p(G_{\bm\mu}p)$ (see \cite[Theorem 3.17]{MRSV_15} for a proof). Moreover, \cite{CLRZ_23} demonstrates that these conditions are mutually independent, and sufficient, but not necessary. Necessary and sufficient conditions were given by C.\, Blacker in \cite{Bla_19}, and due to some almost irrelevant issues, restated and analysed in \cite{CLRZ_23, GM_23}.

Our approach repeats the procedure devised in \cite{MRSV_15}, which leads to Theorem \ref{Th::PolisymplecticReductionJ} but in a slightly different setting, namely we consider $\widetilde{N}=\mathbf{J}^{\Phi-1}(\R^{\times k}\bm\mu)$ instead of taking $N=\mathbf{J}^{\Phi-1}(\bm\mu)$, where $\R^\times=\R\setminus{\{0\}}$ and $\R^{\times k}\bm\mu$ is an invariant set with respect to dilations in each component of $\mu^\alpha\in \mathfrak{g}^*$ for $\alpha=1,\ldots,k$, namely
\[
\mathbf{J}^{\Phi-1}(\R^{\times k}\bm\mu)=\{ p\in P\,\mid\, \exists \lambda_1,\ldots,\lambda_k\in\R^\times,\,\, \mathbf{J}^\Phi(p)=(\lambda_1\mu^1,\ldots,\lambda_k \mu^k)\}.
\]
In other words, $\mathbf{J}^{\Phi-1}(\R^{\times k}\bm\mu)$ is the pre-image of the orbit of $\bm\mu\in(\mathfrak{g}^*)^k$ relative to the action
\[
(\R^\times)^k\times(\mathfrak{g}^*)^k\ni(\lambda_1,\ldots,\lambda_k;\mu^1,\ldots,\mu^k)\longmapsto (\lambda_1\mu^1,\ldots,\lambda_k\mu^k)\in (\mathfrak{g}^*)^k.
\]
It is worth stressing that, according to our assumptions, if $\bm\mu$ is a weak regular $k$-value, the spaces $\mathbf{J}^{\Phi-1}(\R^{\times k}\bm\mu)$ and $\mathbf{J}^{\Phi-1}_\alpha(\R^\times\mu^\alpha)$ are submanifolds of $P$.

One can expect that the Lie subgroup of $G$ that quotients $\mathbf{J}^{\Phi-1}(\R^{\times k}\bm\mu)$ may satisfy some new condition compared to the $k$-symplectic case in Theorem \ref{Th::PolisymplecticReductionJ} due to dimensional considerations (see Section \ref{Sec:Correction}). In this regard, let us present the following proposition that is a starting point for the modified $k$-symplectic MMW reduction.
\begin{proposition}
\label{Prop::Kgroup}
    Let $\mathfrak{k}_{[\mu]}:=\ker\mu\cap\mathfrak{g}_{[\mu]}$, where $\ker\mu=\left\langle\mu\right\rangle^\circ$ and $\mathfrak{g}_{[\mu]}=\{\xi\in \mathfrak{g}\,\mid\,\ad^{*}_{\xi}\mu\wedge \mu =0\}$ for some $\mu\in\mathfrak{g}^*$. Then, $\mathfrak{k}_{[\mu]}$ is a Lie subalgebra of $\mathfrak{g}$.
\end{proposition}
\begin{proof}
    Note that $\mathfrak{k}_{[\mu]}$ is a linear space. If $\xi,\nu\in\mathfrak{k}_{[\mu]}$, then $\ad_\xi^*\mu=\lambda\mu$ and $\ad^*_\nu\mu=\kappa\mu$ for some $\lambda,\kappa\in\R$. Thus,
    \[
    \ad^*_{[\xi,\nu]}\mu=\ad^*_\nu\ad^*_\xi\mu-\ad^*_\nu\ad^*_\xi\mu=(\lambda\kappa-\kappa\lambda)\mu=0,\qquad \langle \ad^*_\xi\mu,\nu\rangle=\langle \mu,[\xi,\nu]\rangle=\langle \lambda\mu,\nu\rangle=0.
    \]
    The first equality shows that $[\xi,\nu]\in\mathfrak{g}_{[\mu]}$ and the second that $[\xi,\nu]$ belongs to $\ker\mu$.
    Therefore, $[\xi,\nu]\in \mathfrak{k}_{[\mu]}$ and $\mathfrak{k}_{[\mu]}$ is a Lie subalgebra of $\mathfrak{g}$.
\end{proof}

Proposition \ref{Prop::Kgroup} implies that there exists a unique and simply connected Lie subgroup of $G$, denoted as $K_{[\bf \mu]}$, whose Lie algebra is $\mathfrak{k}_{[\mu]}$ for $\mu\in\mathfrak{g}^*$. The following lemma presents the properties of $\mathfrak{k}_{[\bm\mu]}$ and $K_{[\bm\mu]}$ in the $k$-symplectic setting, where $\ker\bm\mu=\cap^k_{\alpha=1}\ker\mu^\alpha$ and $\mathfrak{k}_{[\bm\mu]}=\ker\bm\mu\cap\mathfrak{g}_{[\bm\mu]}$.

\begin{lemma}
\label{Lemm::SubgroupinJ}
    Let $(P,\bm\Theta)$ be a $k$-symplectic manifold and let $\bm\mu\in(\mathfrak{g}^*)^k$ be a weak regular $k$-value of an exact $k$-symplectic momentum map $\mathbf{J}^\Phi_{\bm\Theta}\colon P\rightarrow (\mathfrak{g}^*)^k$ associated with a Lie group action $\Phi\colon G\times P\rightarrow P$. Then,
    \begin{equation}
    \label{Eq::kKproperties}
    K_{[\bm\mu]}=\bigcap^k_{\alpha=1}K_{[\mu^\alpha]},
 \qquad \mathfrak{k}_{[\bm\mu]}=\bigcap^k_{\alpha=1}\mathfrak{k}_{[\mu^\alpha]}.
    \end{equation}
    Moreover, $\T_p(K_{[\bm\mu]}p)\subseteq \ker \jmath_{[\bm\mu]}^*\bm\omega(p)$ for the natural embedding $\jmath_{[\bm\mu]}\colon \mathbf{J}^{\Phi-1}_{\bm\Theta}(\R^{\times k}\bm\mu)\hookrightarrow P$ and every $p\in \mathbf{J}^{\Phi-1}_{\bm\Theta}(\R^{\times k}\bm\mu)$.
\end{lemma}
\begin{proof}
    The first statement in \eqref{Eq::kKproperties} follows from Definition \ref{Def::symMomentumMap} and the fact that if $g\in K_{[\bm\mu]}$, then $g\in K_{[\mu^\alpha]}$ for $\alpha=1,\ldots,k$ and vice versa. The identity for the Lie algebra then follows. Second, for any $\xi\in\mathfrak{k}_{[\bm\mu]}$, one has
    \[
    \T\mathbf{J}^\Phi_{\bm\Theta}(\xi_P)=\frac{\d}{\d t}\bigg|_{t=0}\mathbf{J}^\Phi_{\bm\Theta}\circ \Phi_{\exp(t\xi)}=\frac{\d}{\d t}\bigg|_{t=0}\Ad^{*k}_{\exp(-t\xi)}\mathbf{J}^\Phi_{\bm\Theta}=-\ad^{*k}_\xi\mathbf{J}^\Phi=-(\lambda_1\mathbf{J}_{\bm\Theta 1}^\Phi,\ldots,\lambda_k\mathbf{J}_{\bm\Theta k}^\Phi)
    \]
for some $\lambda_1,\ldots,\lambda_k\in\R$. This yields that $\T_p(K_{[\bm\mu]}p)\subseteq \T_p(\mathbf{J}^{\Phi-1}_{\bm\Theta}(\mathbb{R}^{\times k}\bm\mu))$ for any $p\in \mathbf{J}^{\Phi-1}_{\bm\Theta}(\R^{\times k}\bm\mu)$. Next, for any $v_p\in\T_p(\mathbf{J}^{\Phi-1}_{\bm\Theta}(\mathbb{R}^{\times k}\bm\mu))$, one has,  for some $\tilde{\lambda}_1,\ldots,\tilde{\lambda}_n\in\R$, that
\[
(\jmath^*_{[\bm\mu]}\bm\omega)(p)(v_p,\xi_{\mathbf{J}^{\Phi-1}_{\bm\Theta}(\R^{\times k}\bm\mu)}(p))=\bm\omega(p)(\T_p\jmath_{[\bm\mu]}v_p,\xi_P(p))=\langle \T_p\mathbf{J}_{\bm\Theta}^\Phi(v_p),\xi\rangle=\langle \tilde{\lambda}_\alpha\mu^\alpha\oplus e_\alpha,\xi\rangle=0,
\]
for any $\xi\in\mathfrak{k}_{[\bm\mu]}$ and $p\in\mathbf{J}^{\Phi-1}_{\bm\Theta}(\R^{\times k}\bm\mu)$, where we denoted by $v_p$ both a vector $v_p\in\T_p\mathbf{J}_{\bm\Theta}^{\Phi-1}(\R^\times\bm\mu)$ and its induced $v_p\in \T_pP$. Therefore, $\T_p(K_{[\bm\mu]}p)\subseteq \ker(\jmath^*_{[\bm\mu]}\bm\omega)(p)$ for every $p\in\mathbf{J}_{\bm\Theta}^{\Phi-1}(\R^\times\bm\mu)$.

\end{proof}
Therefore, Lemma \ref{Lemm::SubgroupinJ} and  Theorem \ref{Th::RedGen}, taking $S=\mathbf{J}^{\Phi-1}_{\bm\Theta}(\R^{\times k}\bm\mu)$, show that
\[
\T_p(K_{[\bm\mu]}p)\subseteq \ker(\jmath^*_{[\bm\mu]}\bm\omega)(p)=\T_p(\mathbf{J}_{\bm\Theta}^{\Phi-1}(\R^{\times k}\bm\mu))\cap\left(\T_p(\mathbf{J}_{\bm\Theta}^{\Phi-1}(\R^{\times k}\bm\mu))\right)^{\perp_k},\quad \forall p\in\mathbf{J}_{\bm\Theta}^{\Phi-1}(\R^{\times k}\bm\mu).
\]
In general, the converse does not hold, as detailed in \cite{MRSV_15}. Consequently, analogously to \cite{MRSV_15}, one may ask under which conditions $\T_p(K_{[\bm\mu]}p)= \ker(\jmath^*_{[\bm\mu]}\bm\omega)(p)$ for any $p\in\mathbf{J}_{\bm\Theta}^{\Phi-1}(\R^\times\bm\mu)$. The answer follows essentially as in \cite{MRSV_15}, but with a significant difference given in Lemma \ref{Lemm::SymplecticLemma}. 

Recall that, if $k=1$, then $(P,\omega)$ is a symplectic manifold. Now, let us assume that $(P,\omega=\d\Theta)$ is an exact symplectic manifold.
\begin{lemma}
\label{Lemm::SymplecticLemma}
    Let $(P,\Theta)$ be an exact symplectic manifold and let $G_{[\mu]}=\{g\!\in\! G\!\mid\!\Ad^*_{g^{-1}}\mu\wedge\mu=0\}$. Assume that $J^\Phi_{\Theta}(p)=\mu\in\mathfrak{g}^*$ is a weak regular value of an exact symplectic momentum map $J_{\Theta}^\Phi\colon  P\rightarrow \mathfrak{g}^*$ associated with a Lie group action $\Phi\colon  G\times P\rightarrow P$. Then, for any $p\in {J}_{\Theta}^{\Phi-1}(\R^\times\mu)$, one has
    \begin{enumerate}[{\rm(1)}]
            \item $\T_p(G_{[\mu]}p)=\T_p(Gp)\cap\T_p({J}_{\Theta}^{\Phi-1}(\R^\times\mu))$,
            \item $\T_p({J}_{\Theta}^{\Phi-1}(\R^\times\mu))=\left(\T_p(Gp)\cap\ker\Theta_p\right)^{\perp_\omega}$,
    \end{enumerate}
    where $^{\perp_\omega}$ denotes the symplectic orthogonal.
\end{lemma}
\begin{proof}\phantom{.}
\begin{enumerate}[{\rm(1)}]
        \item First, for any $\xi\in \mathfrak{g}$, one has that 
        \begin{equation}
        \label{Eq::LemmaProof}
        \T_pJ_{\Theta}^{\Phi}(\xi_P(p))=\frac{\d}{\d t}\bigg|_{t=0}\!\!{J}_{\Theta}^\Phi\!\circ\! \Phi_{\exp(t\xi)}(p)=\frac{\d}{\d t}\bigg|_{t=0}\left(\Ad^*_{\exp(-t\xi) } {J}_{\Theta}^\Phi\right)(p)=-\ad^*_{\xi}\mu.
        \end{equation}
        Let us prove that $\T_p(G_{[\mu]}p)\subset \T_p(J_{\Theta}^{\Phi-1}(\mathbb{R}^\times \mu))$. Using the above equality, for $\xi_P(p)\in \T_p\left(G_{[\mu]}p\right)$, i.e. $\xi\in\mathfrak{g}_{[\mu]}$,  it follows from \eqref{Eq::LemmaProof} that
        \[
        0=\mu\wedge\ad^*_\xi\mu=-\mu\wedge \T_pJ_\Theta^\Phi(\xi_P(p)),
        \]
        and hence $\xi_P(p)\in \T_p{J}_{\Theta}^{\Phi-1}(\R^\times\mu)$.

        Let us now show that  $\T_p(G_{[\mu]}p)\supset \T_pJ_{\Theta}^{\Phi-1}(\mathbb{R}^\times \mu)\cap \T_p(Gp)$. If $v\in \T_p(Gp)\cap\T_p{J}_{\Theta}^{\Phi-1}(\R^\times\mu)$, then $v=\xi_P(p)\in\T_p{J}_{\Theta}^{\Phi-1}(\R^\times\mu)$ for some $\xi\in\mathfrak{g}$ and, by \eqref{Eq::LemmaProof}, one gets
        \[
        0=\mu\wedge\T_p{J}_\Theta^\Phi(\xi_P(p))=-\mu\wedge\ad^*_\xi\mu.
        \]
        Therefore, $v=\xi_P(p)\in\T_p(G_{[\mu]}p)$. This proves (1).

        \item  Recall that, by Definition \ref{Def::MomentumMap1homo}, if $\xi_P(p)\in \ker\Theta_p$ for some $p\in J_{\Theta}^{\Phi-1}(\R^\times\mu)$, then  $\xi\in \ker\mu$. Let $v\in \left(\T_p(Gp)\cap\ker\Theta_p\right)^{\perp_\omega}$. Then,
        \[
        0=\iota_v(\iota_{\xi_P}\omega)_p=-\iota_v\d\langle J^\Phi_\Theta,\xi\rangle(p)=\langle \T_p{J}_\Theta^\Phi(v),\xi\rangle,\qquad \forall\xi\in \ker \mu\,. 
        \]
        Hence, $v\in\T_p{J}_\Theta^{\Phi-1}(\R^\times\mu)$.

        Conversely, let $v\in \T_p{J}_\Theta^{\Phi-1}(\R^\times\mu)$. Then, for every $\xi\in\ker\mu$, one has
        \[
        0=\langle\T_p{J}_\Theta^\Phi(v),\xi\rangle=-\iota_v(\iota_{\xi_P}\omega)_p
        \]
        and $v\in \left(\T_p(Gp)\cap\ker\Theta_p\right)^{\perp_\omega}$.
    \end{enumerate}
\end{proof}

Let $(P,\bm\Theta)$ be an exact
$k$-symplectic manifold and let $\bm\mu\in (\mathfrak{g}^*)^k$ be a weak regular $k$-value of an exact $k$-symplectic momentum $\mathbf{J}^\Phi_{\bm\Theta}\colon P\rightarrow (\mathfrak{g}^*)^k$ associated with an exact $k$-symplectic Lie group action $\Phi\colon G\times P\rightarrow P$ that acts in a quotientable manner on $\mathbf{J}_{\bm\Theta}^{\Phi-1}(\R^{\times k}\bm\mu)$. Using Lemma \ref{Lemm::SymplecticLemma}, let us provide conditions under which equality $\T_p(K_{[\bm\mu]}p)= \ker(\jmath^*_{[\bm\mu]}\bm\omega)(p)$ holds for every $p\in \mathbf{J}^{\Phi-1}_{\bm\Theta}(\R^{\times k}\bm\mu)$. The proof consists of two steps. 
\begin{enumerate}[{\rm(1)}]
    \item The vector space
    \[
    V^p_\alpha:=\frac{\left(\frac{\T_p(\mathbf{J}^{\Phi-1}_{\bm\Theta\alpha}(\R^\times\mu^\alpha))}{\ker \omega^\alpha_p}\right)}{\left\{[\xi_P(p)]\,\mid\,\xi\in\mathfrak{k}_{[\mu^\alpha]}\right\}},
    \]
    is a symplectic vector space, where $\pr^P_\alpha\colon \T P\rightarrow \frac{\T P}{\ker\omega^\alpha}$ is the canonical vector bundle projection (over the base $P$) and $[\xi_P(p)]:=\pr_\alpha^P(\xi_P(p))$.
    \item The linear surjective morphisms
    \[
    \Pi^\alpha_p\colon \T_{\pi_{[\bm\mu]}(p)}\left(\mathbf{J}_{\bm\Theta}^{\Phi-1}(\mathbb{R}^{\times k}\bm\mu)/K_{[\bm\mu]}\right)\longrightarrow \frac{\left(\frac{\T_p(\mathbf{J}^{\Phi-1}_{\bm\Theta\alpha}(\R^\times\mu^\alpha))}{\ker \omega^\alpha_p}\right)}{\left\{[\xi_P(p)]\,\mid\,\xi\in\mathfrak{k}_{[\mu^\alpha]}\right\}}\,,\qquad\alpha=1,\ldots,k\,,
    \]
    satisfy $\bigcap^k_{\alpha=1}\ker\Pi^\alpha_p=0$, where $\pi_{[\bm\mu]}\colon \mathbf{J}_{\bm\Theta}^{\Phi-1}(\mathbb{R}^{\times k}\bm\mu)\rightarrow \mathbf{J}_{\bm\Theta}^{\Phi-1}(\mathbb{R}^{\times k}\bm\mu)/K_{[\bm\mu]}$ is the canonical projection.
\end{enumerate}

Assuming that the above steps are fulfilled, the following immediate lemma implies that $\ker(\jmath^*_{[\bm\mu]}\bm\omega)(p)=\T_p(K_{[\bm\mu]}p)$ and $\mathbf{J}_{\bm\Theta}^{\Phi-1}(\mathbb{R}^{\times k}\bm\mu)/K_{[\bm\mu]}$ is an exact $k$-symplectic manifold.

\begin{lemma}
\label{Lemm::PolysymVA}
    Let $\pi_\alpha\colon V_p\rightarrow V^p_\alpha$ be surjective linear morphisms and let $(V^p_\alpha,\d\Theta^\alpha(p))$ be symplectic vector spaces for $\alpha=1,\ldots,k$. If $\cap^k_{\alpha=1}\ker \pi_\alpha=0$, then $(V_p,\d\bm\Theta(p)=\sum^k_{\alpha=1}(\d\pi_\alpha^*\Theta^\alpha)(p)\otimes e_\alpha)$ is a $k$-symplectic vector space.
\end{lemma}

Let us move on to the proofs of the aforementioned steps. They essentially follow the same ideas as in \cite{MRSV_15}. The diagram in Figure \ref{fig:diagramRed} helps us illustrate the process.
\begin{figure}
    \centering
    \begin{center}
\begin{tikzcd}
    \left(\T_p(\mathbf{J}^{\Phi-1}_{\bm\Theta\alpha}(\R^\times\mu^\alpha)),\omega_{\mathbf{J}^\Phi_{\bm\Theta\alpha}}(p)\right) \arrow[dd,"\pr^{\mathbf{J}_{\bm\Theta\alpha}^\Phi}"]\arrow[rr,hook,"\jmath^\alpha_p"]& & \left(\T_pP,\omega^\alpha(p)\right)\arrow[dd,"\pr^P_\alpha"]\\
    & & \\
    \left(\frac{\T_p(\mathbf{J}^{\Phi-1}_{\bm\Theta\alpha}(\mathbb{R}^\times \mu^\alpha))}{\ker\omega^\alpha_p},\widetilde{\omega_{\mathbf{J}^\Phi_{\bm\Theta\alpha}}(p)}\right)\arrow[dd,"\widetilde{\pr^\alpha}"]\arrow[rr,hook,"\widetilde{\jmath^\alpha_p}"]& & \left(\frac{\T_pP}{\ker\omega^\alpha_p},\widetilde{\omega^\alpha(p)}\right)\\
    & & \\
    \left(\frac{\left(\frac{\T_p(\mathbf{J}^{\Phi-1}_{\bm\Theta\alpha}(\R^\times\mu^\alpha))}{\ker \omega^\alpha_p}\right)}{\left\{[\xi_P(p)]\,\mid\,\xi\in\mathfrak{k}_{[\mu^\alpha]}\right\}},\omega_{[\mu^\alpha]}(p)\right).
