\subsection{Category-Based Alpha Selection}
\label{sec:appendix 4}
Algorithm \ref{alg:cap} delineates a systematic methodology for alpha selection in quantitative investment strategies, employing a category-based approach to ensure diversification across multiple financial factors. The procedure operates on a structured set of alpha categories \(\mathcal{C}\), each representing distinct market phenomena such as momentum, mean reversion, or volatility. For each category, the algorithm identifies superior alpha factors through the SelectBestAlphas function, which presumably evaluates historical performance metrics. The innovation lies in the subsequent dual-agent evaluation system: the RiskPreferenceAgent assesses each alpha's risk characteristics, while the ConfidenceScoreAgent evaluates the statistical robustness of its historical performance. These complementary evaluations are synthesized using weight parameters \(w_r\) and \(w_c\) to compute a comprehensive Final Score. Only alphas exceeding a predefined confidence threshold \(X\) are incorporated into the final selection set \(\mathcal{A}\). This methodical approach ensures that the resulting alpha portfolio exhibits both category diversification and individual signal quality, potentially enhancing risk-adjusted returns while mitigating exposure to specific market regimes or factor deterioration.


\begin{algorithm}[!htbp]
\caption{Category-Based Alpha Selection}\label{alg:cap}
\begin{algorithmic}[1]
\Require categories \( \mathcal{C} = \{C_1, ..., C_m\} \), each \( C_i \) containing a set of Alphas, confidence threshold \( X \)
\State Initialize selected Alphas \( \mathcal{A} = \{\} \)
\For{each category \( C_i \in \mathcal{C} \)}
    \State \( \mathcal{A}_i = \text{SelectBestAlphas}(C_i) \)
    \For{each \( \alpha \in \mathcal{A}_i \)}
        \State \( \text{Risk Score} = \text{RiskPreferenceAgent}(\alpha) \)
        \State \( \text{Confidence Score} = \text{ConfidenceScoreAgent}(\alpha) \)
        \State \( \text{Final Score} = w_r \cdot \text{Risk Score} + w_c \cdot \text{Confidence Score} \)
        \If{$\text{Final Score} > X$}
            \State \( \mathcal{A} = \mathcal{A} \cup \{\alpha\} \)
        \EndIf
    \EndFor
\EndFor
\State \textbf{return} \( \mathcal{A} \)
\end{algorithmic}
\end{algorithm}


\newpage

\subsection{Dynamic
Alpha Strategy Construction}
\vspace*{-0.4cm}

\begin{algorithm}[H]
\caption{Overall Framework Algorithm}
\label{overall ago}
\begin{spacing}{0.97}
\begin{algorithmic}[1]
\Require Multimodal financial data $\mathcal{D}$, market conditions $\mathcal{M}^{(t)}$, stocks $\mathcal{S}$, confidence threshold $\tau$
\Ensure Optimized alpha strategy $\alpha^{(t)}$
\Statex \textcolor{blue}{\textbf{/* Phase 1: SAF /}}
\State Initialize empty Seed Alpha Factory $\mathcal{F} \gets \emptyset$
\For{each document $d \in \mathcal{D}$}
\State $\text{filtered content} \gets \text{LLM}.\text{Filter}(d)$
\State $\text{categories} \gets \text{LLM}.\text{Categorize}(\text{filtered content})$
\For{each category $c \in \text{categories}$}
\State $\text{seed\_alphas} \gets \text{LLM}.\text{GenerateAlphas}(c)$
\State $\mathcal{F}c \gets \mathcal{F}_c \cup \text{seed\_alphas}$
\EndFor
\EndFor
\Statex \textcolor{blue}{\textbf{/* Phase 2: Multi-Agent Evaluation /}}
\State Initialize selected alphas $\mathcal{A} \gets \emptyset$
\For{each category $c \in \mathcal{F}$}
\For{each alpha $\alpha_{ij} \in \mathcal{F}c$}
\State $\theta_{ij} \gets \text{ConfidenceScoreAgent}(\alpha_{ij}, \mathcal{M}^{(t)})$ \Comment{Statistical evaluation}
\State $\rho_{ij} \gets \text{RiskPreferenceAgent}(\alpha_{ij}, \mathcal{M}^{(t)})$ \Comment{Risk assessment}
\State $\text{score}{ij} \gets w_c \cdot \theta{ij} + w_r \cdot \rho_{ij}$ \Comment{Combined score}
\If{$\text{score}{ij} > \tau$}
\State $\mathcal{A}c \gets \mathcal{A}_c \cup \{\alpha{ij}\}$
\EndIf
\EndFor
\If{$\mathcal{A}c \neq \emptyset$}
\State $\alpha_c^* \gets \arg\max_{\alpha_{ij} \in \mathcal{A}c} \text{score}{ij}$ \Comment{Select best alpha in category}
\State $\mathcal{A} \gets \mathcal{A} \cup \{\alpha_c^\}$
\EndIf
\EndFor
\Statex \textcolor{blue}{\textbf{/* Phase 3: Weight Optimization /}}
\State Initialize MLP with architecture $\{|\mathcal{A}|, 10, 1\}$ \Comment{Input, hidden, output layers}
\State $\mathbf{X}{\text{train}} \gets \text{ComputeHistoricalAlphas}(\mathcal{A}, \mathcal{S}, t{\text{start}}$, $t_{\text{end}})$
\State $\mathbf{y}{\text{train}} \gets \text{FutureReturns}(\mathcal{S}, t{\text{start}}+1, t_{\text{end}}+1)$
\State $\mathbf{w} \gets \text{TrainMLP}(\mathbf{X}{\text{train}}, \mathbf{y}{\text{train}})$ \Comment{Learn optimal weights}
\For{each stock $S_i \in \mathcal{S}$}
\State $\alpha_i^{(t)} \gets \sum_{j=1}^{|\mathcal{A}|} w_j \cdot \alpha_{ij}^(t)$ \Comment{Compute composite alpha}
\EndFor
\State \Return $\alpha^{(t)} = \{\alpha_1^{(t)}, \alpha_2^{(t)}, \ldots, \alpha_n^{(t)}\}$ \Comment{Final alpha strategy}
\end{algorithmic} 
\end{spacing}
\end{algorithm} 

