\section{Detailed discussion of Eq.~\eqref{eq-ETH-new1}}\label{sec-appendixb}
To illustrate the scaling of $f(\overline{E},\omega)$ with $\hbar_{\text{eff}}$ indicated in Eq.~\eqref{eq-ETH-new}, let us consider the auto-correlation function of ${\cal O}$ 
\begin{equation}
   C(t)=\frac{1}{{\cal D}}\text{Tr}[{\cal O}(t){\cal O}]=\frac{1}{{\cal D}}\sum_{\alpha\beta}|{\cal O}_{\alpha\beta}|^{2}e^{-i(E_{\beta}-E_{\alpha})t/\hbar_{\text{eff}}} . 
\end{equation}
In the semiclassical limit $\hbar_{\text{eff}} \rightarrow 0$, 
\begin{equation}
    C(t)\simeq C_{\text{cl}}(t)\equiv\frac{1}{(4\pi)^{2}}\int d\boldsymbol{z}d\boldsymbol{\theta}{\cal O}^{\text{cl}}(\boldsymbol{z}(t),\boldsymbol{\theta}(t)){\cal O}^{\text{cl}}(\boldsymbol{z}(0),\boldsymbol{\theta}(0)) .
\end{equation}
Particularly, we are interested in 
\begin{equation}
    \widetilde{C}(t)=C(t)-C(\infty) = \frac{1}{{\cal D}}\sum_{\alpha\neq\beta}|{\cal O}_{\alpha\beta}|^{2}e^{-i(E_{\beta}-E_{\alpha})t/\hbar_{\text{eff}}} ,
\end{equation}
and its Fourier transform
\begin{align}
    \text{FT}\left[\widetilde{C}(t)\right] & =\frac{1}{{\cal D}}\sum_{\alpha\beta}|{\cal O}_{\alpha\beta}|^{2}\int d\omega e^{-i(E_{\beta}-E_{\alpha})t/\hbar_{\text{eff}}+i\omega t} \nonumber \\
    & = \frac{2\pi}{{\cal D}}\sum_{\alpha\beta}|{\cal O}_{\alpha\beta}|^{2}\delta(\nu-(E_{\beta}-E_{\alpha})/\hbar_{\text{eff}}) .
\end{align}
Inserting Eq.~\eqref{eq-ETH-new0}, one obtains
\begin{align}
\text{FT}\left[\widetilde{C}(t)\right]\simeq&\frac{2\pi}{{\cal D}}\int d\overline{E}d\omega\frac{\rho(\overline{E}+\omega/2)\rho(\overline{E}-\omega/2)}{\rho(\overline{E})}|f(\overline{E},\omega)|^{2} \nonumber \\
    & \cdot \delta(\nu-\omega/\hbar_{\text{eff}}) \nonumber \\
    = &  \frac{2\pi\hbar_{\text{eff}}}{{\cal D}}\int d\overline{E}\frac{\rho(\overline{E}+\hbar_{\text{eff}}\nu/2)\rho(\overline{E}-\hbar_{\text{eff}}\nu/2)}{\rho(\overline{E})}|f(\overline{E},\hbar_{\text{eff}}\nu)|^{2} \nonumber \\
    \simeq & \frac{2\pi\hbar_{\text{eff}}}{{\cal D}}\int d\overline{E}\rho(\overline{E})|f(\overline{E},\hbar_{\text{eff}}\nu)|^{2} \nonumber \\
    = & 2\pi \hbar_{\text{eff}} \overline{|f(\overline{E},\hbar_{\text{eff}}\nu)|^{2}}
\end{align}
where
\begin{equation}
    \overline{|f(\overline{E},\hbar_{\text{eff}}\nu)|^{2}}\equiv\frac{1}{{\cal D}}\int d\overline{E}\rho(\overline{E})|f(\overline{E},\hbar_{\text{eff}}\nu)|^{2} .
\end{equation}
In the semi-classical limit $\hbar_{\text{eff}} \rightarrow 0$,
\begin{equation}
\text{FT}\left[\widetilde{C}(t)\right]\simeq\text{FT}\left[\widetilde{C}_{\text{cl}}(t)\right]\equiv F_{\text{cl}}(\nu) ,
\end{equation}
which leads to
\begin{equation}\label{eq-f2}
    \overline{|f(\overline{E},\hbar_{\text{eff}}\nu)|^{2}}\simeq\frac{1}{2\pi\hbar_{\text{eff}}}F_{\text{cl}}(\nu) .
\end{equation}
Letting $\omega = \hbar_{\text{eff}} \nu$, Eq.~\eqref{eq-f2} becomes
\begin{equation}
    \overline{|f(\overline{E},\omega)|^{2}}\simeq\frac{1}{2\pi\hbar_{\text{eff}}}F_{\text{cl}}(\omega/\hbar_{\text{eff}}),
\end{equation}
which supports the scaling of $f(\overline{E}, \omega)$ given in Eq.~\eqref{eq-ETH-new}.
\section{Deviation from Eq.~\eqref{eq-Deltak-DE} in extremely small energy window in the chaotic case} 
\label{app-2}
In this section, we provide further discussion on the reason for the deviations from Eq.~\eqref{eq-Deltak-DE} in extremely small energy window in the chaotic case, observed in Fig.~\ref{Fig-FC} and Fig.~\ref{Fig-FCB}. To this end, we construct a unitary invariant ensemble, 
$\widetilde{\cal O}_{\Delta E} = U^\dagger {\cal O}_{\Delta E} U$, where $U$ is a $d_{\Delta E} \times d_{\Delta E}$ Haar random unitary operator. Practically, we choose the ``seed" operator ${\cal O}_{\Delta E} = {\cal A}_{\Delta E} = P_{\Delta E} {\cal A} P_{\Delta E}$ which is considered in Fig.~\ref{Fig-FC}. The energy window consists of $d_\text{U}=d_{\Delta E} = 1000$ eigenstates with energy $E\approx 0$ and we choose $j = 5000$. 


We apply a unitary transformation $\widetilde{{\cal A}}_\text{U}=U^{\dagger}{\cal A}_{\Delta E}U$, and then project it onto smaller subspace with dimension $d$, defining ${\cal A}_d = P_d \widetilde{{\cal A}}_{\text{U}} P_d$. 
Since dimension is more essential in the discussion of UIE, we denote the projection operator and the truncated operator using $d$ instead of the energy scale. 
If $d$ is sufficiently large, the ensemble average of free cumulants of ${\cal A}_d$ follows Eq.~\eqref{eq-fca} 
\begin{equation}\label{eq-uim-d}
     {\Delta_{k}^{d}}=\alpha^{k-1}{\Delta_{k}^{U}},\ \alpha = d/d_\text{U} . 
\end{equation}
The is confirmed by the numerical results in Fig.~\ref{Fig-FCR} for $\alpha\gtrsim 0.5$ ($d\gtrsim 500$).
However, when $\alpha$ (as well as $d$) is sufficiently small, i.e., $\alpha\lesssim0.2$ ($d\lesssim200$), deviations from Eq.~\eqref{eq-uim-d} become visible, similar to the deviations found in Figs.~\ref{Fig-FC} and ~\ref{Fig-FCB}. 
This suggests that the deviations from the UIM prediction observed at extremely small energy window in the main text are due to the small dimension of the energy window, rather than indicating the absence of unitary symmetry. 










