\textbf{The Hochschild cohomology} of an associative $\kk$-algebra $A$ was originally defined using the following projective bimodule resolution known as the bar resolution. It is given by
\begin{equation}\label{bar}
\mathbb{B}_{\bullet}(A):  \qquad\cdots \rightarrow A^{\ot (m+2)}\xrightarrow{\;\delta_m\; }A^{\ot (m+1)}\xrightarrow{\delta_{m-1}} \cdots \xrightarrow{\;\delta_2\;}A^{\ot 3}\xrightarrow{\;\delta_1\;}A^{\ot 2}\;(\;\xrightarrow{\mu} A)
\end{equation}
where $\mu$ is multiplication and the differentials $\delta_m$ are given by
\begin{equation}\label{bar-diff}
\delta_n(a_0\otimes a_1\otimes\cdots\otimes a_{m+1}) = \sum_{i=0}^m (-1)^i a_0\otimes\cdots\otimes a_ia_{i+1}\otimes\cdots\otimes a_{m+1}
\end{equation}
for all $a_0, a_1,\ldots, a_{m+1}\in A$. Each $A$-bimodule $A^{\ot (m+1)}$ is a left modules over the enveloping algebra $A^e = A\ot A^{op}$, where $A^{op}\cong A$ with reverse multiplication as an algebra. The resolution is sometimes written $\mathbb{B}_{\bullet}\xrightarrow{\mu}\Lambda$ with $\mu$ referred to as the augmentation map. The Hochschild cohomology of $A$ with coefficients in $A$ denoted $ \HH^*(A)$ is obtained by applying the functor $\HHom_{A^e}(-,A)$ to the complex $\mathbb{B}_{\bullet}(A)$, and then taking the cohomology of the resulting cochain complex. That is 
$$ \HH^*(A) := \bigoplus_{j\geq 0} \HH^j(A)=\bigoplus_{j\geq 0} \text{H}^j(\HHom_{A^e}(\mathbb{B}_{m}(A),A)). $$

Let $\chi\in\HHom_{A^e}(\mathbb{B}_m,A)$ be a cocycle, that is, $(\delta^{*}(\chi))(\cdot) := \chi\delta(\cdot)=  0.$ There is an isomorphism of the abelian groups $\HHom_{A^e}(\mathbb{B}_m(A),A)\cong\HHom_{k}(A^{\otimes m},A),$ so we can also view $\chi$ as an element of $\HHom_{k}(A^{\otimes m},A)$.


\textbf{The cup product:} We obtain the multiplicative structure on Hochschild cohomology using the following.
\begin{definition}\label{cup-definition}
Let $A$ be a $\kk$-algebra. Let $\Delta_{\mathbb{B}}:\mathbb{B}\xrightarrow{}\mathbb{B}\ot_{A}\mathbb{B}$ be the comultiplicative map lifting the identity map on $A \cong A\ot_{A} A$. Let $f\in\HHom_{\kk}(A^{\otimes m},A)$ and $g\in \HHom_{\kk}(A^{\otimes n},A)$ be cocycles of degree $m$ and $n$ respectively. The cup product $f\smallsmile g$ at the chain level is an element of $\HHom_{\kk}(A^{\otimes (m+n)},A)$ given by
\begin{equation*}\label{cup-equ-1}
f\smallsmile g = \tilde{\pi} (f\ot g)\Delta_{\mathbb{B}},
\end{equation*}
where $\tilde{\pi}$ is multiplication, and $\Delta_{\mathbb{B}}$ is given by 
\begin{equation}\label{diag-bar}
\Delta_{\mathbb{B}}(a_0\otimes\cdots\otimes a_{n+1}) = \sum_{i=0}^n (a_0\otimes\cdots\otimes a_i\ot 1)\ot_{A}( 1\ot a_{i+1}\otimes\cdots\otimes a_{n+1}).
\end{equation}
\end{definition}



\textbf{The projective bimodule resolution $\mathbb{Q}_{\bullet}$:} We now describe the projective bimodule resolution $\mathbb{Q}_{\bullet}$ that was used to obtain the result of \cite[Theorem 4.10]{furuya2012projective}. 

For ease of notations and computations, in $\mathcal{Q}$, we label $e_0=f_0$, $e_2=f_2$ and $a_2=b_2$ so that a path of length three from $e_0$ to $e_0$ could be written as $a_0a_1a_2$ for the upper triangle of the quiver and as $b_0b_1b_2$ for the lower triangle of the quiver. Throughout, we will have all indices $i$ for $e_i,f_i, a_i$ and $b_i$ to be given modulo 3. 

We first define a set of uniform paths of length $i$ given as $\mathcal{G}^i$, for $i=0,1,2,\ldots$ in the following ways. Note that the path $(a_0a_1a_2)^na_0a_1$ of length $3n+2$ can also be written as $a_0(a_1a_2a_0)^na_1$.
\begin{gather*}
\mathcal{G}^0 =\{\text{vertices}\} =  \{R^0=e_0=f_0 , S^0=e_1, T^0=f_1, U^0=e_2=f_2\},\\
\mathcal{G}^1 =\{\text{arrows}\} =  \{R^1_0=a_0, R^1_1=b_0 , S^1=a_1, T^1=b_1, U^1=a_2=b_2\},\\
\mathcal{G}^2 =\{\text{minimal generating set for $I_n$}\} =  \{R^2=a_0(a_1a_2a_0)^na_1-b_0b_1, \\
S^2=a_1(a_2a_0a_1)^na_2, T^2=b_1b_2,  U^2_0=a_2(a_0a_1a_2)^na_0, U^2_1=b_2b_0\},
\end{gather*}
and in general,
\begin{equation}\label{uniform-paths}
\mathcal{G}^i = \begin{cases} \{R^i, S^i_0, S^i_1, T^i_0, T^i_1, U^i\}  & \text{ if } i\equiv 0 \pmod{3}, \\ 
\{R^i_0, R^i_1, S^i, T^i, U^i\}  & \text{ if } i\equiv 1 \pmod{3},\\
\{R^i, S^i, T^i, U^i_0, U^i_1\}  & \text{ if } i\equiv 2 \pmod{3}, \end{cases}
\end{equation}
where the uniform paths $\{R^i_j, S^i_j, T^i_j, U^i_j\}$ are defined recursively as follows;
\begin{enumerate}
\item[(R)] \begin{align*}
R^{6i+1}_j = \begin{cases} R^{6i}a_0 & \text{ if } j=0 \\  R^{6i}b_0 & \text{ if } j=1 \end{cases}, \quad  & R^{6i+2} = R^{6i+1}_0(a_1a_2a_0)^na_1 - R^{6i+1}_1b_1,\\
R^{6i+3} = R^{6i+2}a_2 = R^{6i+2}b_2, \quad & R^{6i+4}_j = \begin{cases} R^{6i+3}(a_0a_1a_2)^na_0 & \text{ if } j=0 \\  R^{6i+3}b_0 & \text{ if } j=1 \end{cases} \\
 R^{6i+5} = R^{6i+4}_0a_1 - R^{6i+4}_1b_1, \quad & R^{6i+6} = R^{6i+5}(a_2a_0a_1)^na_2.
\end{align*}
\item[(S)] \begin{align*}
 S^{6i+1} = S^{6i}_0a_1 - S^{6i}_1b_1, \quad & S^{6i+2} = S^{6i+1}(a_2a_0a_1)^na_2, \\
S^{6i+3}_j = \begin{cases} S^{6i+2}a_0 & \text{ if } j=0 \\  S^{6i+2}b_0 & \text{ if } j=1 \end{cases}, \quad  & S^{6i+4} = S^{6i+3}_0(a_1a_2a_0)^na_1 - S^{6i+3}_1b_1,\\
S^{6i+5} = S^{6i+4}a_2 = S^{6i+4}b_2, \quad & S^{6i+6}_j = \begin{cases} S^{6i+5}(a_0a_1a_2)^na_0 & \text{ if } j=0 \\  S^{6i+5}b_0 & \text{ if } j=1 \end{cases}.
\end{align*}
\end{enumerate}

\begin{enumerate}
\item[(T)] \begin{align*}
 T^{6i+1} = T^{6i}_0(a_1a_2a_0)^na_1 - T^{6i}_1b_1, \quad & T^{6i+2} = T^{6i+1}a_2  = T^{6i+1}b_2, \\
T^{6i+3}_j = \begin{cases} T^{6i+2}(a_0a_1a_2)^na_0 & \text{ if } j=0 \\  T^{6i+2}b_0 & \text{ if } j=1 \end{cases}, \quad  & T^{6i+4} = T^{6i+3}_0a_1 - T^{6i+3}_1b_1,\\
T^{6i+5} = T^{6i+4}(a_2a_1a_0)^na_2, \quad & T^{6i+6}_j = \begin{cases} T^{6i+5}a_0 & \text{ if } j=0 \\  T^{6i+5}b_0 & \text{ if } j=1 \end{cases}.
\end{align*}
\end{enumerate}

\begin{enumerate}
\item[(U)] \begin{align*}
U^{6i+1} = U^{6i}a_2 = U^{6i}b_2, \quad & U^{6i+2}_j = \begin{cases} U^{6i+1}(a_0a_1a_2)^na_0 & \text{ if } j=0 \\  U^{6i+1}b_0 & \text{ if } j=1 \end{cases} \\
U^{6i+3} = U^{6i+2}_0a_1 - U^{6i+2}_1b_1, \quad & U^{6i+4} = U^{6i+3}(a_2a_0a_1)^na_2, \\
U^{6i+5}_j = \begin{cases} U^{6i+4}a_0 & \text{ if } j=0 \\  U^{6i+4}b_0 & \text{ if } j=1 \end{cases}, \quad  & U^{6i+6} = U^{6i+5}_0(a_1a_2a_0)^na_1 - U^{6i+5}_1b_1.
\end{align*}
\end{enumerate}

For all elements $g\in\mathcal{G}^i$, the following are $\Lambda_n$-bimodules;
$$\mathbb{Q}_{m} = \bigoplus_{g\in\mathcal{G}^m} \Lambda_n \mfo(g)\ot \mft(g)\Lambda_n.$$
Note that for $g_1\neq g_2$ in $\mathcal{G}^m$, $\mfo(g_1)\ot \mft(g_1)\neq \mfo(g_2)\ot \mft(g_2)$ and a generating set of $\mathbb{Q}_m$ is $\{\mfo(g)\ot \mft(g)\}_{g\in\mathcal{G}^m} = \{e_r\ot e_s, f_r\ot e_s, e_r\ot f_s, f_r\ot f_s\}$ where $r,s =0,1,2$. For example, 
\begin{align*}
\mathbb{Q}_0 &=  \Lambda_n \mfo(R^0)\ot \mft(R^0)\Lambda_n \oplus  \Lambda_n \mfo(S^0)\ot \mft(S^0)\Lambda_n \\
& \oplus \Lambda_n \mfo(T^0)\ot \mft(T^0)\Lambda_n \oplus  \Lambda_n \mfo(U^0)\ot \mft(U^0)\Lambda_n  \\
& =  (\Lambda_n e_0\ot e_0\Lambda_n) \oplus  (\Lambda_n e_1\ot e_1\Lambda_n) \oplus (\Lambda_n f_1\ot f_1\Lambda_n) \oplus  (\Lambda_n e_2\ot e_2\Lambda_n),
\end{align*}
so a generating set for $\mathbb{Q}_0$ as a bimodule is $\{e_0\ot e_0, e_1\ot e_1, f_1\ot f_1, e_2\ot e_2\}$. Note that this consists of all paths of length zero from vertex $i$ to $i$. Similarly, $\mathbb{Q}_1$ will be generated by paths of length 1 from vertex $i$ to $j$, $\mathbb{Q}_2$ will be generated by paths of length 2 from vertex $i$ to $j$ and so on. No new $e_i\ot e_j$ is obtain when we consider paths of length greater than or equal four. Therefore, a basis for the generating set for $\mathbb{Q}_m$ occurs mode 3 in one of the following cases for $m\geq 0$.
\begin{itemize}
\item $\mathbb{Q}_{3m}$, generated by $\{e_0\ot e_0, e_1\ot e_1, e_1\ot f_1, f_1\ot e_1, f_1\ot f_1, e_2\ot e_2\}$,
\item $\mathbb{Q}_{3m+1}$, generated by $\{e_0\ot e_1, e_0\ot f_1, e_1\ot e_2, f_1\ot e_2, e_2\ot e_0\}$.
\item $\mathbb{Q}_{3m+2}$, generated by $\{e_0\ot e_2, e_1\ot e_0, f_1\ot e_0, e_2\ot e_1, e_2\ot f_1\}$,
\end{itemize}

Although basis elements are presented for $\mathbb{Q}_{3m}, \mathbb{Q}_{3m+1}$ and $\mathbb{Q}_{3m+2}$, the differentials occur in mode 6, so the chain complex has the following form;
$$\cdots \xrightarrow{}\mathbb{Q}_{3m+5}\xrightarrow{\partial^{6j+5} }\mathbb{Q}_{3m+4}\xrightarrow{\partial^{6j+4}}\mathbb{Q}_{3m+3}\xrightarrow{\partial^{6j+3}}\mathbb{Q}_{3m+2}=$$
$$=\mathbb{Q}_{3m+2}\xrightarrow{ \partial^{6j+2}}\mathbb{Q}_{3m+1}\xrightarrow{ \partial^{6j+1}}\mathbb{Q}_{3m}\xrightarrow{ \partial^{6j}}\mathbb{Q}_{3m-1}\xrightarrow{}\cdots$$
We now present a theorem that formally state these results.

\begin{theorem}\cite[Theorem 3.3]{furuya2012projective}\label{major-res}
Let $\Lambda_n = \kk\mathcal{Q}/I_n$ be a family of quiver algebras described in \eqref{family} and let $\mathcal{G}^i$ be a set of uniform relations described by \eqref{uniform-paths}. A minimal projective bimodule resolution of $\Lambda_n$  is given by
\begin{equation*}
\mathbb{Q}_{\bullet}(\Lambda_n):  \quad\cdots \rightarrow \mathbb{Q}_{3m}\xrightarrow{\;\partial^{6j}\; }\mathbb{Q}_{3m-1}\xrightarrow{\partial^{6j-5}} \cdots \xrightarrow{\;\partial^2\;}\mathbb{Q}_{1}\xrightarrow{\;\partial^1\;}\mathbb{Q}_{0}\;(\;\xrightarrow{\;\partial^0\;} \Lambda_n)
\end{equation*}
for $m\geq 0$, where the differentials $\partial^{\bullet}:\mathbb{Q}_{3m}\xrightarrow{}\mathbb{Q}_{3m-1}$ applied to the generators of each bimodule $\mathbb{Q}_{3m}$ are given in Definition \eqref{differentials} and $\partial^0$ is multiplication.
\end{theorem}

\begin{definition}\label{differentials}
\begin{enumerate}[label=(\roman*)]\ \\
\item For $j=0$, we take $\partial^{6j}=\partial^0$ and for $j\geq 1$, and $l=0,1,2$\begin{equation*}
