\textbf{Module structure compatibility:} Suppose that $A$ and $B$ are $\kk$-algebras, $M$ is a left $A$-module and $N$ is a left $B$-module. Then the tensor product $M\ot_{A\ot B} N$ is a left $A\ot B$ module and we have the following module structure
$(A\ot B)\times (M\ot_{A\ot B} N) \rightarrow M\ot_{A\ot B} N$ given by $(a\ot b)\cdot (m\ot n) \mapsto am\ot bn$ for every $a\in A, b\in B, m\in M$ and $n\in N.$ 


Let $A\ot A^{op}\cong A^e$ be the enveloping algebra of $A$ where $(A^{op},\cdot_{op})$ is the opposite algebra of $A$ with opposite multiplication given by $a\cdot_{op}b =ba$ for every $a,b\in A$. If $M$ is a left $A^e$-module, then we have the following module structure $A^e\times M\rightarrow M$ given by $(a\ot a')\cdot m = ama'$. If $N$ is also a left $A^e$-module, then $M\ot_{A^e} N := M\ott N$ is a left $A^e\ot A^e$-module and the module structure $(A^e\ot A^e)\times (M\ot_{A^e} N) \rightarrow M\ot_{A^e} N$ is given by $(r\ot s)\cdot (m\ott n) = r\cdot m\ott s\cdot n$ for every $r, s\in A^e, m\in M$ and $n\in N$. Since $A^e\ot A^e \cong A^e$, then $M\ot_{A^e} N$ is also a left $A^e$-module and the module structure $A^e\times (M\ot_{A^e} N) \rightarrow M\ot_{A^e} N$ is given by $(r\ot r')\cdot (m\ott n) = rm\ott nr'$ for every $r, r'\in A, m\in M$ and $n\in N$. Since these module structures are compatible for these algebras, we have in particular, for $r_1, r_2, s_1, s_2\in A$, 
\begin{align}\label{mod1}
(r_1\ot s_1)(r_2\ot s_2)\cdot (m\ott n) = (r_1r_2\ot s_2s_1)\cdot (m\ott n) = r_1r_2m \ott ns_2s_1,
\end{align}
and when we use the module structure for $(A^e\ot A^e)\times (M\ot_{A^e} N) \rightarrow M\ot_{A^e} N$ earlier given, we obtain
\begin{align}\label{mod2}
(r_1\ot s_1)(r_2\ot s_2)\cdot (m\ott n) = ((r_1\ot s_1)\cdot m) \ott ((r_2\ot s_2) \cdot n) = r_1m s_1 \ott r_2ns_2
\end{align}
since both $M$ and $N$ are left $A^e$-modules.

\begin{remark}
Let $\Lambda_n$ be the family of quiver algebras in \eqref{family} and let $\lambda_1,\lambda_2, \beta_1, \beta_2\in \Lambda_n$. Let $\mathbb{Q}_a$ and $\mathbb{Q}_b$ be left $\Lambda_n^e$-modules having basis elements $e_i\ot e_j$ and $e_l\ot e_s$ respectively. Using the module structure of \eqref{mod1} and \eqref{mod2}, we have the following module structure compatibility.

\begin{equation}\label{modulestructure}
    \lambda_1(e_i\ot e_j)\beta_1 \ott\lambda_2(e_l\ot e_s) \beta_2 \simeq \lambda_1\lambda_2(e_i\ot e_j)\ott(e_l\ot e_s)\beta_2\beta_1.
\end{equation}
\end{remark}


\section{Main results}\label{Main results}
We denote the total complex obtained from the tensor product complex $\mathbb{Q}_{\bullet}\ot_{\Lambda_n}\mathbb{Q}_{\bullet}$ by $\mathbb{P}_{\bullet}$, so that $\Delta:\mathbb{Q}_{\bullet}\xrightarrow{}\mathbb{P}_{\bullet}$ is the comultiplicative map lifting the identity map $\Lambda_n\cong\Lambda_n\ott\Lambda_n$. We define $\displaystyle{\mathbb{P}_{m}: =\bigoplus_{a+b=m} \mathbb{Q}_a\ott \mathbb{Q}_b},$
and for $x\ot y\in \mathbb{Q}_a\ott \mathbb{Q}_b \in \mathbb{P}_m$, the differential $d^m:\mathbb{P}_m\rightarrow \mathbb{P}_{m-1}$ is given by
$$d^m(x\ot y)= \partial^{m-1}(x)\ot y + (-1)^{a} x\ot \partial^{m-1}(y)$$
provided $\partial^{m-1}(x)$ or  $\partial^{m-1}(y)$ are non-zero. We seek maps $\Delta_{\bullet}$ for which the following diagrams are commutative. As previously noted, the generating set for the free modules $\mathbb{Q}_{\bullet}$ are the same for modules in degrees $3m, 3m+1$ and $3m+2$ respectively. 
$$\begin{tikzcd}
\mathbb{Q}_{\bullet}: =\arrow{d}{\Delta_{\bullet}} \cdots \arrow{r}{}
    & \mathbb{Q}_{3m+2}\arrow{d}{\Delta_{3m+2}}\arrow{r}{\partial^{6j+2}}
        & \mathbb{Q}_{3m+1} \arrow{d}{\Delta_{3m+1}} \arrow{r}{\partial^{6j+1}}
            & \mathbb{Q}_{3m} \arrow{d}{\Delta_{3m}} \arrow{r}{\partial^{6j}}
                & \cdots \\
\mathbb{P}_{\bullet}:= \cdots \arrow{r}{d^*}
    & \mathbb{P}_{3m+2} \arrow{r}{d^*}
        & \mathbb{P}_{3m+1} \arrow{r}{d^*}
            & \mathbb{P}_{3m} \arrow{r}{d^*}
                & \cdots
\end{tikzcd}$$

Moreso, the differentials occur in mode 6, so the chain complex has the following forms;
$$\cdots \xrightarrow{}\mathbb{Q}_{3m+2}\xrightarrow{\partial^{6j+5}, \partial^{6j+2}}\mathbb{Q}_{3m+1}\xrightarrow{\partial^{6j+4}, \partial^{6j+1}}\mathbb{Q}_{3m}\xrightarrow{\partial^{6j+3}, \partial^{6j}}\mathbb{Q}_{3m-1}\xrightarrow{}\cdots$$
but it is sufficient to define the comultiplicative map in degrees $3m, 3m+1$ and $3m+2$.
