\begin{lemma}\label{deltap-chain_map}
Let $\Lambda_n = \kk Q/I_n$, ($char(\kk)\neq 2$) be the family of quiver algebras of \eqref{family} and let $\mathcal{G}^i$ be a set of uniform relations described by uniform-paths. Let $w,w_i,w_j$ be any idempotent in the set $\{e_0,e_1,f_1,e_2\}.$ A chain map 
$\displaystyle{\Delta^{'}_{n,\bullet}: \mathbb{Q}_{\bullet} \rightarrow \mathbb{Q}_{\bullet}\ott \mathbb{Q}_{\bullet}},$ lifting the map $\pi:\Lambda_n\rightarrow\Lambda_n$ given by $x\mapsto 2x$ for every $x\in\Lambda_n$ can be given by
\begin{align*}
\Delta^{'}_{n,\ast}(w_i\ot w_j) &= (w_i\ot w_i) \bar{\ot} (w_i\ot w_j) + (w_i\ot w_j) \bar{\ot} (w_j\ot w_j) \\
& + (w_i\ot w_j) \bar{\ot} (w_i\ot w_i) + (w_j\ot w_j) \bar{\ot} (w_i\ot w_j) \\
& + \sum_{w\neq w_i,w_j} (w\ot w) \bar{\ot} (w_i\ot w_j) + (w_i\ot w_j) \bar{\ot} (w\ot w) \qquad \text{and}\\
\Delta^{'}_{n,\ast}(w_i\ot w_i) &= (w_i\ot w_i) \bar{\ot} (w_i\ot w_i) + (w_i\ot w_i) \bar{\ot} (w_i\ot w_i) \\
& + \sum_{w\neq w_i} (w\ot w) \bar{\ot} (w_i\ot w_i) + (w_i\ot w_i) \bar{\ot} (w\ot w)
\end{align*}
where $\bar{\ot} =\ot_{\Lambda_n}$.
\end{lemma}

\begin{proof}
Since the generating set for modules in the resolution occurs periodically, we will prove that the result holds in the case $m=0$. That is, we show commutativity of the first, second and third squares in the following diagram. $$\begin{tikzcd}
 \cdots \arrow{r}{\partial^{3}}
    & \mathbb{Q}_{2}\arrow{d}{\Delta^{'}_{n,2}}\arrow{r}{\partial^{2}}
        & \mathbb{Q}_{1} \arrow{d}{\Delta^{'}_{n,1}} \arrow{r}{\partial^{1}}
         & \mathbb{Q}_{0} \arrow{d}{\Delta^{'}_{n,0}} \arrow{r}{\partial^{0}}
            & \Lambda_n \arrow{d}{\pi} \\
\cdots \arrow{r}{d^*}
    & (\mathbb{Q}_2\ott \mathbb{Q}_0)\oplus(\mathbb{Q}_1\ott\mathbb{Q}_1) \oplus(\mathbb{Q}_0\ott\mathbb{Q}_2) \arrow{r}{d^2}
        & \stackrel{\stackrel{(\mathbb{Q}_1\ott \mathbb{Q}_0)}{\oplus}}{ (\mathbb{Q}_0\ott \mathbb{Q}_1)} \arrow{r}{d^1}
            & (\mathbb{Q}_0\ott\mathbb{Q}_0) \arrow{r}{\partial^0\ot\partial^0}
               &\Lambda_n\ott \Lambda_n &
\end{tikzcd}$$
To prove that the diagram is commutative in the first three squares, we will show that (i) $\pi\partial^{0} = (\partial^0\ot\partial^0)\Delta^{'}_{n,0}$, (ii) $\Delta^{'}_{n,0}\partial^{1} = d^{1}\Delta^{'}_{n,1}$ and (iii) $\Delta^{'}_{n,1}\partial^{2} = d^{2}\Delta^{'}_{n,2}.$ \\
\noindent \textbf{Case (i):}  We now show for basis element $e_0\ot e_0$ that $\pi\partial^{0}(e_0\ot e_0) = (\partial^0\ot\partial^0)\Delta^{'}_{n,0}(e_0\ot e_0)$ and a similar proof can be applied to other basis elements of $\mathbb{Q}_0.$ The left hand side of the expression becomes $\pi\partial^{0}(e_0\ot e_0) = \pi(e_0^2)= \pi(e_0)= 2(e_0\ot e_0)=2e_0$ after applying multiplication. Since $e_0$ is an idempotent. The right hand side becomes
\begin{align*}
&(\partial^0\ot\partial^0)\Delta^{'}_{n,0}(e_0\ot e_0) = \partial^0\ot\partial^0 \big(e_0\ot e_0\bar{\ot}e_0\ot e_0 + e_0\ot e_0\bar{\ot}e_0\ot e_0 \\
    &+ e_1\ot e_1\bar{\ot}e_0\ot e_0 + e_0\ot e_0\bar{\ot}e_1\ot e_1 + e_2\ot e_2 \bar{\ot}e_0\ot e_0 + e_0\ot e_0 \bar{\ot} e_2\ot e_2 \\
    &+ f_1\ot f_1\bar{\ot}e_0 \ot e_0 + e_0\ot e_0 \bar{\ot}f_1\ot f_1\big)\\
    &=e_0\ott e_0 + e_0\ott e_0 + e_1\ott e_0 + e_0\ott e_1 + e_2\ott e_0 + e_0\ott e_2 +f_1\ott e_0 + e_0\ott f_1\\
    &= e_0 + e_0 =2e_0 = \pi\partial^{0}(e_0\ot e_0).
\end{align*}
