\\ \partial(e_0\ot e_1)\ott e_1\ot e_1 -e_0\ot e_1\ott \partial(e_1\ot e_1) +\\ \partial(e_1\ot e_1)\ot e_0\ot e_1 +e_1\ot e_1\ott \partial(e_0\ot e_1)+\\ \partial(e_0\ot e_1)\ott f_1\ot f_1 -e_0\ot e_1\ott \partial(f_1\ot f_1)+\\ \partial(f_1\ot f_1)\ott e_0\ot e_1 + f_1\ot f_1\ott \partial(e_0\ot e_1)
\end{multline*}
\begin{multline*}
=0+ e_2\ot e_2\ott[e_0\ot a_0 -a_0\ot e_1]+ [e_0\ot a_0 -a_0 \ot e_1]\ott e_2\ot e_2 - 0 + 0+ e_0\ot e_0\ott [e_0\ot a_0 - a_0\ot e_1] +\\
