    e_l\ot e_{l+2} \mapsto 0 & i\neq l\\
    f_1\ot e_0 \mapsto 0\\
    e_2\ot f_1\mapsto 0\\
    f_1\ot f_1\mapsto 0
\end{cases} \qquad \eta:\begin{cases}
    e_0\ot e_2\mapsto (a_0a_1a_2)^na_0a_1\\
    e_s\ot e_l\mapsto 0 & s\neq l\\
    f_1\ot e_0\mapsto 0\\
    e_2\ot f_1\mapsto 0
\end{cases}$$


The following lemma presents a summary of the above result.
\begin{lemma}\cite[]{furuya2012projective}\label{Hochschild_dim}
For $n\geq 0$ and $m\geq 0$, the generators for $\HHom_{\Lambda_n^e}(\mathbb{Q}_{*},\Lambda_n)$ are given as follows:
\begin{enumerate}
\item A $\kk$-basis for $\HHom_{\Lambda_n^e}(\mathbb{Q}_{0},\Lambda_n)$ is the set $$\{\alpha_s^t, \beta |\; s=0,1,2,\; t=0,1,2,\ldots,n\}$$
\item A $\kk$-basis for $\HHom_{\Lambda_n^e}(\mathbb{Q}_{3m},\Lambda_n)$ is the set $$\{\phi_i^t, \psi |\; i=0,1,2,\; t=0,1,2,\ldots,n\}$$
\item A $\kk$-basis for $\HHom_{\Lambda_n^e}(\mathbb{Q}_{3m+1},\Lambda_n)$ is the set $$\{\mu_i^t, \nu_s |\; i=0,1,2,\; t=0,1,2,\ldots,n,\; s=0,1\}$$
\item A $\kk$-basis for $\HHom_{\Lambda_n^e}(\mathbb{Q}_{3m+2},\Lambda_n)$ is the set $$\{\theta_i^t, \eta |\; i=0,1,2,\; t=0,1,2,\ldots,n-1\}$$
\end{enumerate}
\end{lemma}

The multiplicative structure on Hochschild cohomology $\HH^*(\Lambda_n)$ for this family involves using the cup product of Definition \eqref{cup-definition}. This involves the composition of the following maps at the chain level in which for any $f \in \HHom_{\Lambda_n^e}(\mathbb{Q}_{a},\Lambda_n)$ and $g \in \HHom_{\Lambda_n^e}(\mathbb{Q}_{b},\Lambda_n)$, $f\smallsmile g\in \HHom_{\Lambda_n^e}(\mathbb{Q}_{a+b},\Lambda_n)$ is given by the following composition of maps;
$$\mathbb{Q}{\bullet}\xrightarrow{\Delta} \mathbb{Q}_{\bullet}\ot_{\Lambda_n} \mathbb{Q}_{\bullet} \xrightarrow{f\ot g} \Lambda_n \ot_{\Lambda_n}\Lambda_n \xrightarrow{} \Lambda_n,$$
that is $f\smallsmile g:= (f\ot g)\Delta_{n,a+b}$ where the last map is multiplication. We use the fact that Hochschild cohomology is graded commutative to evaluate $g\smallsmile f= (-1)^{ab}f\smallsmile g$. Furthermore, define the relationship between the cup product and the star product in degree $a+b=m$ as
\begin{align*}\label{cup-product-delta}
    f\smallsmile g &= (f\ot g)\Delta_{n,m}\\
    =&(f\ot g)(\Delta'_{n,\bullet} + \hh^{m-1}\partial^m+d^{m+1}\hh^m)\\
    =& f\star g +(f\ot g)(\hh^{m-1}\partial^m+d^{m+1}\hh^m)
\end{align*}
We obtain a general result for the star product $f\star g$ in Theorem \ref{comultiplicative_structure} and present the cup product on Hochschild cohomology for $\Lambda_0$. We will need the following definition in order to present $\HH^*(\Lambda_0).$
\begin{definition}\label{contracting-homo-exam}
Let $\Lambda_n = \kk Q/I_n$ be the family of quiver algebras of \eqref{family} and let $w_i$ be any idempotent in the set $\{e_0,e_1,f_1,e_2\}$ with the index $i$ given mode 3. Then a chain homotopy $\hh^{\bullet}$ given as $\hh^*:\Lambda_n\rightarrow \mathbb{P}_{1}$, $\hh^0:\mathbb{Q}_{3m}\rightarrow \mathbb{P}_{3m+1}$, $\hh^1:\mathbb{Q}_{3m+1}\rightarrow \mathbb{P}_{3m+2}$ and $\hh^2:\mathbb{Q}_{3m+2}\rightarrow \mathbb{P}_{3m}$ can be defined in the following ways;
\begin{align*}
\hh^*(w_i) &=\begin{cases} -(w_i\ot w_i) \bar{\ot} (w_i\ot w_{i})a_i, & \mfo(a_i)=w_i\\
(w_i\ot w_i) \bar{\ot} (w_i\ot w_{i})b_i, & \mfo(b_i)=w_i
\end{cases}\\
\hh^0(w_i\ot w_i) &= (w_i\ot w_i) \bar{\ot} (w_i\ot w_{i+1}) \\
\hh^1(w_i\ot w_{i+1}) &= (w_i\ot w_i) \bar{\ot} (w_i\ot w_{i+2}) \\
\hh^2(w_i\ot w_{i+2}) &= (w_i\ot w_i) \bar{\ot} (w_i\ot w_{i+3}).
\end{align*}
\end{definition}

