\begin{example}\label{example-of-chain-map}
The following are some examples of images of chain maps $\Delta_{n,\bullet}$ and $\Delta^{'}_{n,\bullet}$ ($n=0$) on some basis elements. We make use of homotopy chain maps of Definition \ref{contracting-homo-exam}.
\begin{align*}
&\Delta_{n,0}(e_0\ot e_0) = (\Delta^{'}_{n,0}+d^1\hh^0 + \hh^*\partial^0)(e_0\ot e_0)\\
&= \Delta^{'}_{n,0}(e_0\ot e_0) + d^1((e_0\ot e_0)\ott (e_0\ot e_1)) + \hh^*(e_0) \\
&= \Delta^{'}_{n,0}(e_0\ot e_0) + (e_0\ot e_0)\ott (e_0\ot e_0a_0 - a_1e_1\ot e_1)\\
&- (e_0\ot e_0)\ott (e_0\ot e_0)a_0 \\
&= \Delta^{'}_{n,0}(e_0\ot e_0) + (e_0\ot e_0)\ott (e_0\ot e_0)a_0 - a_1(e_0\ot e_0)\ott (e_0\ot e_0) \\
&- (e_0\ot e_0)\ott (e_0\ot e_0)a_0 \\
&= \Delta^{'}_{n,0}(e_0\ot e_0).
\end{align*}

Similar computations show that
\begin{align*}
\Delta_{n,0}(e_1\ot e_1)&=\Delta'_{n,0}(e_1\ot e_1)\\
\Delta_{n,0}(e_2\ot e_2)&=\Delta'_{n,0}(e_2\ot e_2)\\
\Delta_{n,0}(f_1\ot f_1)&=\Delta'_{n,0}(f_1\ot f_1)+(f_1\ot f_1)\ott (f_1\ot e_1) a_1
\end{align*}
and at degree one, we have
\begin{align*}
&\Delta_{n,1}(e_1\ot e_2)=(\Delta_{n,1}'+d^2\hh^1+\hh^0\partial^1)(e_1\ot e_2)\\
&=\Delta_{n,1}'(e_1\ot e_2)+d^2((e_1\ot e_1)\ott (e_1\ot e_0))+\hh^0(e_1\ot e_1a_1- a_1e_2\ot e_2)\\
&=\Delta'_{n,1}(e_1\ot e_2)+(\partial\ot 1 +(-1)^\ast 1\ot \partial) (e_1\ot e_1)\ott (e_1\ot e_0) \\
&+\hh^0(e_1\ot e_1)a_1-a_1\hh^0(e_2\ot e_2)\\
&=\Delta_{n,1}'(e_1\ot e_2)+0+ (-1)^0(e_1\ot e_1)\ott \partial (e_1\ot e_0)+(e_1\ot e_1\ott e_1\ot e_2)a_1\\
&-a_1(e_2\ot e_2\ott e_2\ot e_0)\\
&= \Delta_{n,1}'(e_1\ot e_2)+(e_1\ot e_1)\ott (e_1\ot e_2)a_2 - a_1(e_1\ot e_1)\ott (e_2\ot e_0) \\
&+ (e_1\ot e_1\ott e_1\ot e_2)a_1-a_1(e_2\ot e_2\ott e_2\ot e_0)\\
&= \Delta_{n,1}'(e_1\ot e_2)+(e_1\ot e_1)\ott (e_1\ot e_2)a_2 -a_1(e_2\ot e_2\ott e_2\ot e_0)
\end{align*}

Similar computations show that
\begin{align*}
\Delta_{n,1}(e_0\ot e_1)&=\Delta'_{n,1}(e_0\ot e_1) + (e_0\ot e_0)\ott (e_0\ot e_1) a_1 \\
&- (e_0\ot e_0)\ott (e_0\ot f_1) b_1 
 - a_0(e_1\ot e_1)\ott (e_1\ot e_2).\\
\Delta_{n,1}(e_0\ot f_1)&=\Delta'_{n,1}(e_0\ot f_1) + (e_0\ot e_0)\ott (e_0\ot f_1)b_1 + b_0(f_1\ot f_1\ott f_1\ot e_2)
\end{align*}
\begin{align*}
\Delta_{n,1}(e_2\ot e_0)&=\Delta'_{n,1}(e_2\ot e_0)+ (e_2\ot e_2)\ott (e_2\ot e_0)a_0 - a_2(e_0\ot e_0\ott e_0\ot e_1) \\
\Delta_{n,1}(f_1\ot e_2)&=\Delta'_{n,1}(f_1\ot e_2)+ (f_1\ot f_1)\ott (f_1\ot e_0)b_0 - b_1(e_2\ot e_2\ott e_2\ot e_0).
\end{align*}
\end{example}

\begin{Proposition}\label{cohomology-L-0}
    $$\HH^*(\Lambda_0) = \kk\langle x, y, z\rangle /(x^2-2x,xy-y,yx-y,zx-z, xz-z,z^2-x, y^2, yz, zy)$$ 
    where the degrees of $x,y,z$ are $0,1$ and $6$ respectively.
\end{Proposition}
\begin{proof}
We have $\Lambda_0 = \kk\mathcal{Q}/\langle  a_0a_1-b_0b_1, a_1a_2,a_2a_0, b_1b_2, b_2b_0 \rangle$. From Lemma \ref{Hochschild_dim}, the set of maps $\{\alpha_0^0,\alpha_1^0, \alpha_2^0, \beta\}$ forms a generating set for $\HHom(\mathbb{Q}_0,\Lambda_0)$. Moreover for $t\in\mathbb{Q}_1$, $t$ is a linear combination of basis elements. Write $t=e_0\ot e_1+e_0\ot f_1+ e_1\ot e_2 + f_1\ot e_2 + e_2\ot e_0$, calculations shows that
\begin{align*}
&(\alpha_0^0+\alpha_1^0+\alpha_2^0+\beta)(\partial^1(t)) = (\alpha_0^0+\alpha_1^0+\alpha_2^0+\beta)(e_0\ot e_0a_0 - a_0 e_1\ot e_1 \\
&+ e_0\ot e_0b_0 - b_0 f_1\ot f_1 + e_1\ot e_1a_1 - a_1 e_2\ot e_2 + f_1\ot f_1b_1 - b_1 e_2\ot e_2 \\
&+ e_2\ot e_2a_2 - a_2 e_0\ot e_0) = e_0a_0 - a_0e_1 + f_0b_0-b_0f_1+e_1a_1-a_1e_2\\
&+f_1b_1-b_1f_2+e_2a_2-a_2e_0 = 0,
\end{align*}
showing that $(\alpha_0^0+\alpha_1^0+\alpha_2^0+\beta):=x$ generates $\HH^0(\Lambda_0)$. Further calculations shows that $(\mu_0^0+\nu_0):=y$ generates $\HH^1(\Lambda_0)$, and
$(\phi_0^0+\phi_1^0+\phi_2^0-\psi):=z$ generates $\HH^6(\Lambda_0)$ when $char(\kk)\neq 2$ \cite[Proposition 4.9]{furuya2012projective}. The second, third, fourth and fifth Hochschild cohomology groups are zero i.e. $\HH^2(\Lambda_0) = \HH^3(\Lambda_0) = \HH^4(\Lambda_0) = \HH^5(\Lambda_0) = 0$. Using $\Delta_{n,m}$ of Example \ref{example-of-chain-map}, we obtain the following table of multiplication at the chain level
\begin{tabular}{|c|c|c|c|} \hline
& $x\in\HHom(\mathbb{Q}_{0},\Lambda_0)$ & $y\in \HHom(\mathbb{Q}_{1},\Lambda_0)$ & $z\in\HHom(\mathbb{Q}_{6},\Lambda_0)$ \\\hline
$x\in\HHom(\mathbb{Q}_{0},\Lambda_0)$ & 2x & y & z \\\hline
$y\in\HHom(\mathbb{Q}_{0},\Lambda_0)$ & y & 0 & 0 \\\hline
$z\in\HHom(\mathbb{Q}_{0},\Lambda_0)$ & z & 0 & x \\\hline
\end{tabular}
So we have $\HH^*(\Lambda_0) = \kk\langle x, y, z\rangle /(x^2-2x,xy-y,yx-y,zx-z, xz-z,z^2-x, y^2, yz, zy)$ where the degrees of $x$ is $0$, degree of $y$ is 1 and the degree of $z$ is 6.
\end{proof}
We present the following general star product for chain maps $f$ and $g$, $(f\star g)(e_i\ot e_j) = (f\ot g)\Delta_{n,*}')(e_i\ot e_j)$ which can be used to define the cup product on Hochschild cohomology. That is
\begin{equation}
f\smallsmile g = f\star g + (f\ot g)(d\hh + \hh\partial).
\end{equation}

\begin{theorem}\label{comultiplicative_structure}
Let $\Lambda_n = \kk Q/I_n$ be the family of quiver algebras of \eqref{family} with projective bimodule resolution $\mathbb{Q}_{\bullet}$. Suppose that a $\kk$-basis for $\HHom_{\Lambda_n^e}(\mathbb{Q}_{0},\Lambda_n)$ is
$\{\alpha_s^t, \beta |\; s=0,1,2,\; t=0,1,2,\ldots,n\}$,
a basis for $\HHom_{\Lambda_n^e}(\mathbb{Q}_{3m},\Lambda_n)$ is
$\{\phi_i^t, \psi |\; i=0,1,2,\; t=0,1,2,\ldots,n\}$,
a basis for $\HHom_{\Lambda_n^e}(\mathbb{Q}_{3m+1},\Lambda_n)$ is
$\{\mu_i^t, \nu_s |\; i=0,1,2,\; t=0,1,2,\ldots,n,\; s=0,1\}$
and a $\kk$-basis for\\ $\HHom_{\Lambda_n^e}(\mathbb{Q}_{3m+2},\Lambda_n)$ is 
$\{\theta_i^t, \eta |\; i=0,1,2,\; t=0,1,2,\ldots,n-1\}$. 
The following gives the star product $(f\star g):= (f\ot g)\Delta_{n,*}'$ at the chain level for any $f,g\in\HHom_{\Lambda_n^e}(\mathbb{Q}_{a},\Lambda_n)$, $a=3m,3m+1,3m+2.$
\end{theorem}
$$
f\star\alpha_{s'}^{t'} = \begin{cases} 
\alpha_s^{t+t'}, & \quad f=\alpha_s^t, \quad s=s'\\
\phi_s^{t+t'}, & \quad f=\phi_i^t, \quad i=s'\\
\mu_s^{t+t'}, & \quad f=\mu_i^t, \quad i=s'\\
\nu_1, & \quad f=\nu_1,\\
\theta_s^{t+t'}, & \quad f=\theta_i^t, \quad i=s'\\
\eta, & \quad f=\eta,\\
0 & \quad \text{otherwise}
\end{cases},
f\star\phi_{i'}^{t'} = \begin{cases} 
\phi_i^{t+t'}, & \quad f=\phi_i^t, \quad i=i'\\
\mu_i^{t+t'}, & \quad f=\mu_i^t, \quad i=i'\\
\nu_1, & \quad f=\nu_1,\\
\theta_i^{t+t'}, & \quad f=\theta_i^t, \quad i=i'\\
\eta, & \quad f=\eta,\\
0 & \quad \text{otherwise}
\end{cases}
$$
$$
f\star\beta = \begin{cases} 
\beta, & \quad f=\beta\\
\psi, & \quad f=\psi\\
\nu_0, & \quad f=\nu_0\\
0 & \quad \text{otherwise}
\end{cases}
f\star\psi = \begin{cases} 
\psi, & \quad f=\psi\\
\nu_0, & \quad f=\nu_0\\
0 & \quad \text{otherwise}
\end{cases}.
$$
\begin{proof}
We will present the star product computations for $f\star \alpha_{s'}^{t'}$ and $f\star \beta$ for each $f\in\HHom_{\Lambda_n^e}(\mathbb{Q}_{*},\Lambda_n)$ using $(f\ot g)\Delta'_{n,*}$. The other computations are done in similar ways. We have
\begin{align*}
&(\alpha_s^t\star \alpha_{s'}^{t'})(e_l\ot e_l) = (\alpha_s^t\ot\alpha_{s'}^{t'})\Delta'(e_l\ot e_l)\\
&= (\alpha_s^t\ot\alpha_{s'}^{t'})[(e_l\ot e_l)\ott (e_l\ot e_l) + \sum_{w\neq e_l} (w\ot w)\ott (e_l\ot e_l) + (e_l\ot e_l)\ott (w\ot w) ]\\
&= (\alpha_s^t(e_l\ot e_l)\ot\alpha_{s'}^{t'}(e_l\ot e_l)) = (a_sa_{s+1}a_{s+2})^t(a_sa_{s+1}a_{s+2})^{t'} = (a_sa_{s+1}a_{s+2})^{t+t'}\\
&= \alpha_s^{t+t'}(e_l\ot e_l),
\end{align*}
provided $t+t'\leq n$. We note that $(\alpha_s^t\star \alpha_{s'}^{t'})(e_l\ot e_l) =0$ if $s\neq s'$ or $t+u>n$. so $(\alpha_s^t\star \alpha_{s'}^{t'})= \alpha_{s}^{t+t'}, (s=s')$. In similar fashion,
\begin{align*}
&(\alpha_s^t\star \beta)(e_l\ot e_l) = (\alpha_s^t\ot\beta)\Delta'(e_l\ot e_l)\\
&= (\alpha_s^t\ot\beta)[(e_l\ot e_l)\ott (e_l\ot e_l) + \sum_{w\neq e_l} (w\ot w)\ott (e_l\ot e_l) + (e_l\ot e_l)\ott (w\ot w)]\\
&= (\alpha_s^t(e_l\ot e_l)\ot\beta(f_1\ot f_1)) = (a_sa_{s+1}a_{s+2})^tf_1 = 0,
\end{align*}
so $(\alpha_s^t\star \beta)= 0$, since the terminal vertex of $a_sa_{s+1}a_{s+2}$ is either vertex $e_1$ or $e_2$. For this case, 
\begin{align*}
&(\beta\star \beta)(f_1\ot f_1) = (\beta\ot\beta)(\Delta')(f_1\ot f_1)\\
&= (\beta\ot\beta)[(f_1\ot f_1)\ott (f_1\ot f_1) + \sum_{w\neq f_1} (w\ot w)\ott (f_1\ot f_1) + (f_1\ot f_1)\ott (w\ot w)]\\
&= (\beta(f_1\ot f_1)\ot\beta(f_1\ot f_1)) = f_1f_1 = f_1 = \beta(f_1\ot f_1).
\end{align*}
\begin{align*}
    &(\mu_i^t \star \alpha_{s'}^{t'})(e_l\ot e_{l+1})=(\mu_i^t\ot\alpha_{s}^{t'})\Delta'(e_{l}\ot e_{l+1})\\
    &=(\mu_i^t\ot \alpha_{s}^{t'})[(e_l\ot e_l)\ott (e_l\ot e_{l+1}) + (e_{l}\ot e_{l+1})\ott (e_{l+1}\ot e_{l+1}) + \\&(e_l\ot e_{l+1})\ott (e_l\ot e_l)+ (e_{l+1}\ot e_{l+1})\ott (e_l\ot e_{l+1}) \\
    & + \sum_{w\neq e_l, e_{l+1}}(w\ot w)\ott (e_l\ot e_l) + (e_l\ot e_l)\ott (w\ot w)]\\
    &=(\mu_i^t(e_l\ot e_{l+1})\ott \alpha_{s'}^{t'}(e_{l+1}\ot e_{l+1})
    +\mu_i^t(e_l\ot e_{l+1})\ott \alpha_{s'}^{t'}(e_l\ot e_l))
\end{align*}
\begin{itemize}
\item Case 1: If $i=l$ and $s'=l+1$, we have,
$((a_la_{l+1}a_{l+2})^ta_l(a_{l+1}a_{l+2}a_{l})^{t'}+0)=(a_la_{l+1}a_{l+2})^{t+t'}a_l=\mu_i^{t+t'}(e_l\ot e_{l+1})$, so $(\mu_i^t\smallsmile \alpha_{s'}^{t'})= \mu_{i}^{t+t'}, (i=l)$.
