\begin{align*}
    &(\mu_i^t\star \beta)(e_l\ot e_{l+1})=\pi(\mu_i^t\ot \beta)\Delta'(e_l\ot e_{l+1})\\
    &=(\mu_i^t\ot \beta)[(e_l\ot e_l)\ott (e_l\ot e_{l+1}) + (e_{l}\ot e_{l+1})\ott (e_{l+1}\ot e_{l+1}) + \\&(e_l\ot e_{l+1})\ott (e_l\ot e_l)+ (e_{l+1}\ot e_{l+1})\ott (e_l\ot e_{l+1}) \\
    &+ \sum_{w\neq e_l, e_{l+1}}(w\ot w)\ott (e_l\ot e_l) + (e_l\ot e_l)\ott (w\ot w)]\\
    &=(\mu_i^t(e_l\ot e_{l+1})\ott \beta(e_{l+1}\ot e_{l+1})+\mu_i^t(e_l\ot e_{l+1})\ott \beta(e_l\ot e_l))\\
    &=0,\text{so we have} \;(\mu_i^t\star \beta)= 0.
\end{align*}
\begin{align*}
    &(\mu_i^{t} \star \mu_{i'}^{t'})(e_l\ot e_{l+1})=\pi(\mu_i^t\ot \mu_{i'}^{t'})\Delta'(e_{l}\ot e_{l+1})\\
    &=(\mu_i^t\ot \mu_{i'}^{t'})[(e_l\ot e_l)\ott (e_l\ot e_{l+1}) + (e_{l}\ot e_{l+1})\ott (e_{l+1}\ot e_{l+1}) + \\&(e_l\ot e_{l+1})\ott (e_l\ot e_l)+ (e_{l+1}\ot e_{l+1})\ott (e_l\ot e_{l+1})\\
    &+ \sum_{w\neq e_l, e_{l+1}}(w\ot w)\ott (e_l\ot e_l) + (e_l\ot e_l)\ott (w\ot w)]\\
