\end{align*}
\begin{align*}
&(\theta_i^t\star \alpha_{s'}^{t'})(e_l\ot e_{l+2})=\pi(\theta_i^t \ot \alpha_{s'}^{t'})\Delta'(e_l\ot e_{l+2})\\
&=(\theta_i^t\ot \alpha_{s'}^{t'})[(e_l\ot e_l)\ott (e_l\ot e_{l+2})+(e_l\ot e_{l+1})\ott (e_{l+1}\ot e_{l+2})\\
