    &=(\theta_i^t\ot \beta)[(e_l\ot e_l)\ott (e_l\ot e_{l+2})+(e_l\ot e_{l+1})\ott (e_{l+1}\ot e_{l+2})\\
    & +(e_l\ot e_{l+2})\ott (e_{l+2}\ot e_{l+2})]+\\
&(e_{l+2}\ot e_{l+2})\ott (e_l\ot e_{l+2})+ (e_{l+1}\ot e_{l+2})\ott (e_l\ot e_{l+1})+ (e_l\ot e_{l+2})\ott (e_{l}\ot e_{l})\\ &+\sum_{w\neq e_l,e_{l+1}, e_{l+2}} w\ot w\ott e_l\ot e_l + e_l\ot e_l \ott w\ot w]=0, (\theta_i^t\smallsmile \beta)=0.
\end{align*}
\begin{align*}
    &(\nu_0\star \alpha_{s'}^{t'})(e_0\ot f_1)=(\nu_0\ot \alpha_{s'}^{t'})\Delta'(e_0\ot f_1)\\
    &=(\nu_0\ot \alpha_{s'}^{t'})[(e_0\ot e_0)\ott (e_0\ot f_1) + (e_0\ot f_1)\ott (f_1\ot f_1) + \\
    &(e_0\ot f_1)\ott (e_0\ot e_0) + (f_1\ot f_1)\ott (e_0\ot f_1)\\
    & + \sum_{w\neq e_0, f_1} (w\ot w) \ott (e_l\ot e_l) + (e_l\ot e_l) \ott (w\ot w)]\\
    &=((\nu_0(e_0\ot f_1)\ott \alpha_{s'}^{t'}(e_0\ot e_0))=b_0(a_0a_{1}a_{2})^t=0, \text{so we have  }\;(\nu_0\star \alpha_{s'}^{t'}) = 0.
\end{align*}
\begin{align*}
    &(\nu_0 \star \beta)(e_0\ot f_1)=(\nu_0\ot \beta)\Delta'(e_0\ot f_1)\\
    &=(\nu_0\ot \beta)[(e_0\ot e_0)\ott (e_0\ot f_1) + (e_0\ot f_1)\ott (f_1\ot f_1) + \\
    &(e_0\ot f_1)\ott (e_0\ot e_0) + (f_1\ot f_1)\ott (e_0\ot f_1) \\
    &+ \sum_{w\neq e_0, f_1} (w\ot w) \ott (e_l\ot e_l) + (e_l\ot e_l) \ott (w\ot w)]\\
    &=(\nu_0(e_0\ot f_1)\ott \beta (f_1\ot f_1)=b_0f_1 =b_0=\nu_0(e_0\ot f_1)
\end{align*}
\begin{align*}
    &(\phi_i^t \star \alpha_{s'}^{t'})(e_l\ot e_l)=\pi(\phi_i^t \ot \alpha_{s'}^{t'})\Delta'(e_l\ot e_l)\\
    &=(\phi_i^t\ot \alpha_{s'}^{t'})[e_l\ot e_l\ott e_l\ot e_l + \sum_{w\neq e_l} w\ot w\ott e_l\ot e_l + e_l\ot e_l\ott w\ot w]\\
    &=(\phi_i^t(e_l\ot e_l)\ot \alpha_{s'}^{t'}(e_l\ot e_l))\\
    &=((a_ia_{i+1}a_{i+2})^t\ot (a_{s'}a_{s'+1}a_{s'+2})^{t'})=(a_ia_{i+1}a_{i+2})^t(a_{s'}a_{s'+1}a_{s'+2})^{t'}\\
    &=(a_ia_{i+1}a_{i+2})^{t+t'}=\phi_i^{t+t'}(e_l\ot e_l), \text{ so } (\phi_i^t \star \alpha_{s'}^{t'})=\phi_i^{t+t'}.
\end{align*}
The second last equality follows from the fact that $i$ and $s'$ needs to be equal for the cup product $(\phi_i^t\star \alpha_{s'}^{t'})$ to be non-zero and the last equality holds as $\phi_i^t\star \alpha_{s'}^{t'}\in \mathbb{Q}_{3m}$.
\begin{align*}
    & (\phi_i^t\star \beta)(e_l\ot e_l)=(\phi_i^t\ot \beta)\Delta'(e_l\ot e_l)\\
    =& (\phi_i^t\ot \beta)[e_l\ot e_l\ott e_l\ot e_l + \sum_{w\neq e_l} w\ot w\ott e_l\ot e_l + e_l\ot e_l\ott w\ot w]\\
    &=(\phi_i^t(e_l\ot e_l)\ot \beta (f_1\ot f_1)) =(a_ia_{i+1}a_{i+2})^tf_1=0.
\end{align*}
\begin{align*}
    &(\psi \star \alpha_{s'}^{t'})(e_l\ot e_l)=(\psi \ot \alpha_{s'}^{t'})\Delta'(e_l\ot e_l))\\
    &=(\psi \ot \alpha_{s'}^{t'})[e_l\ot e_l\ott e_l\ot e_l + \sum_{w\neq e_l} w\ot w\ott e_l\ot e_l + e_l\ot e_l\ott w\ot w]\\
    &=(\psi(f_1\ot f_1)\ot \alpha_{s'}^{t'}(e_l\ot e_l))=f_1(a_{s'}a_{s'+1}a_{s'+2})^{t'}=0
\end{align*}
\begin{align*}
    &(\psi\star \beta)(e_l\ot e_l)=(\psi\ot \beta)\Delta'(e_l\ot e_l)\\
    &=(\psi\ot \beta)[e_l\ot e_l\ott e_l\ot e_l + \sum_{w\neq e_l} w\ot w\ott e_l\ot e_l + e_l\ot e_l\ott w\ot w]\\
    &=(\psi(f_1\ot f_1) \ot \beta(f_1\ot f_1))=f_1f_1=f_1, \text{so we have} \; (\psi\star \beta)=\psi.
\end{align*}
\begin{align*}
    &(\eta\star \alpha_{s'}^{t'})(e_0\ot e_2)=(\eta\ot \alpha_{s'}^{t'})\Delta'(e_0\ot e_2)\\
    &=(\eta\ot \alpha_{s'}^{t'})[(e_0\ot e_0)\ott (e_0\ot e_{2})+(e_0\ot e_{2})\ott (e_{2}\ot e_{2})]\\
    &+(e_{2}\ot e_{2})\ott (e_0\ot e_{2})+ (e_0\ot e_{2})\ott (e_{0}\ot e_{0})+\\
    &\sum_{w\neq e_0, e_{2}} (w\ot w)\ott (e_l\ot e_l) + (e_l\ot e_l) \ott (w\ot w)]\\
    &=(\eta(e_0\ot e_2)\ot \alpha_{s'}^{t'}(e_2\ot e_2) + \eta(e_0\ot e_2) \ot \alpha_{s'}^{t'}(e_0\ot e_0)+\eta(e_0\ot e_2)\ot \alpha_{s'}^{t'}(e_1\ot e_1)),\\
&\text{so we have  }\;(\eta\star \alpha_{s'}^{t'})= \eta, (i'=2)\; \text{from the following cases}.
\end{align*}
\begin{itemize}
\item Case 1: If $s'=2$ we have 
 $(a_0a_1a_2)^na_0a_1(a_2a_0a_1)^{t'}=(a_0a_1a_2)^{n+t'}a_0a_1=\eta(e_0\ot e_2).$
\item Case 2: If $s'= 1, 3$, we get $0$.
\end{itemize}
\begin{align*}
    &(\eta \star \beta)(f_1\ot f_1)=(\eta \ot \beta)\Delta'(f_1\ot f_1)\\
    &=(\eta \ot \beta)[(f_1\ot f_1)\ott (f_1\ot f_1)\\
    &+\sum_{w\neq f_1}(w\ot w)\ott (f_1\ot f_1)+(f_1\ot f_1)\ott (w\ot w)] &=0
\end{align*}
\begin{align*}
    &(\nu_1\star \alpha_{s'}^{t'})(f_1\ot e_2)=(\nu_1\ot \alpha_{s'}^{t'})\Delta'(f_1\ot e_2)\\
    &=(\nu_1\ot \alpha_{s'}^{t'})[(f_1\ot f_1)\ott (f_1\ot e_2) + (f_1\ot e_2)\ott (f_1\ot f_1) + \\
    &(f_1\ot e_2)\ott (e_2\ot e_2) + (e_2\ot e_2)\ott (f_1\ot e_2)\\
    &+ \sum_{w\neq f_1, e_2} (w\ot w) \ott (e_l\ot e_l) + (e_l\ot e_l) \ott (w\ot w)]\\
    &=((\nu_1(f_1\ot e_2)\ott \alpha_{s'}^{t'}(e_2\ot e_2))=b_1(a_2a_{0}a_{1})^t=b_1, \;\text{ so }(\nu_1\star \alpha_{s'}^{t'}) = \nu_1, (s'=2, t'=0).
\end{align*}
\begin{align*}
    &(\nu_1\star \beta)(f_1\ot e_2)=(\nu_1\ot \beta)\Delta'(f_1\ot e_2)\\
    &=\pi(\nu_1\ot \beta)[(f_1\ot f_1)\ott (f_1\ot e_2) + (f_1\ot e_2)\ott (f_1\ot f_1) + \\
    &(f_1\ot e_2)\ott (e_2\ot e_2) + (e_2\ot e_2)\ott (f_1\ot e_2)+ \sum_{w\neq f_1, e_2} (w\ot w) \ott (e_l\ot e_l) + (e_l\ot e_l) \ott (w\ot w)]\\
    &=(\nu_1(f_1\ot e_2)\ott \beta(f_1\ot f_1))=b_1f_1=0, \text{ so }\;(\nu_1\star \beta)=0.
\end{align*}
\end{proof}

