\section{Zonotopal statement of the Lonely Runner Conjecture}
\label{sec:zonotopes}

A \emph{zonotope} is any polytope obtained as the Minkowski sum of finitely many line segments.
As such, any zonotope $Z$ can be written as
\[
\cc + \sum_{i=1}^n [\oo, \uu_i] =\left\{\cc + \sum_{i=1}^n \lambda_i \uu_i : \lambda_i \in [0,1]\ \forall i\right\}
\]
for a certain finite set $\uu_1,\dots,\uu_n \in \RR^d$ of vectors, called the \emph{generators} of $Z$ and a certain point $\cc$.
The point $\cc$ is not important for us, since all we do is invariant under translation.
One natural choice is $\cc=\oo$ but often a more convenient choice is $\cc = -\tfrac12 \sum_{i=1}^n \uu_i$, since it
 makes the zonotope become $Z= \tfrac12\sum_{i=1}^n [-\uu_i, \uu_i]$ and be centrally symmetric around the origin.

\subsection{Lonely runner zonotopes and their volume vectors}
\label{subsec:lrz-volume-vector}

\begin{definition}[Lonely runner zonotopes, volume vector]
    \label{def:lrz_volume_vector}
    A \emph{Lonely Runner zonotope (LR zonotope)}
    is any zonotope $Z\subset \RR^{n-1}$ generated by a set of $n$ integer vectors $\mathbf U=\{\uu_i: 1 \le i \le n\}\subset \ZZ^{n-1}$ in linear general position;
    that is, such that every $n - 1$ of them are a linear basis of $\RR^{n-1}$.

    The \emph{volume vector} of $Z$ is the vector
    $\vv =(v_1, \dots, v_n)\in \ZZ_{>0}^n$ defined by
    \begin{equation}
         \label{eq:volume_vector_condition}
       v_i \coloneqq |\det(\mathbf U \setminus \{\uu_i\} )|.
    \end{equation} 
    When all entries of the volume vector are distinct, we say that $Z$ is a \emph{strong Lonely Runner zonotope (sLR zonotope)}.
\end{definition}

We call $\vv$ the {volume vector} of $Z$, because its entries are
the volumes of the $n$ parallelepipeds that make up $Z$.
In particular, we have that $\vol(Z) = \sum_{i=1}^n v_i$ (see details, e.g., in~\cite{Malikiosis2024LinExpCheckingLRC}).
The generators and the volume vector satisfy
\begin{equation} \label{eq:volume_vector}
v_1 \uu_1 \pm \cdots \pm v_n \uu_n =0
\end{equation}
for some choice of signs.
In fact, this equation (together with positivity) characterizes $\vv$ for given generators, up to a scalar factor.
Indeed, for each $j\in 1,\dots, n-1$, consider the determinant:
\[
    \begin{vmatrix}
      u_{1,j} & u_{2,j} & \cdots & u_{n,j}\\
      u_{1,1} & u_{2,1} & \cdots & u_{n,1} \\
      u_{1,2} & u_{2,2} & \cdots & u_{n,2} \\
      \vdots    & \vdots    & \ddots & \vdots    \\
      u_{1,n-1} & u_{2,n-1} & \cdots & u_{n,n-1} \
    \end{vmatrix},
\]
where $\uu_i=( u_{i,1},\dots,u_{i,n-1})$.
This determinant is zero because it has a repeated row, and it equals the $j$-th coordinate of~\eqref{eq:volume_vector} via Laplace's expansion of the determinant along its first row.
Since any $n-1$ of the vectors in $U$ are independent, Equation~\eqref{eq:volume_vector} has a $1$-dimensional space of solutions.
In this sense, Equation~\ref{eq:volume_vector} characterizes $\vv$ up to signs and scalar multiplication.

In the following result and the rest of the paper, a unimodular transformation is an
affine transformation with integer coefficients and determinant $\pm1$.
That is, an element of $\operatorname {AGL}(n,\ZZ) \coloneqq \ZZ^n \rtimes \operatorname {GL} (n,\ZZ)$.

\begin{proposition}[\cite{Malikiosis2024LinExpCheckingLRC}]
\label{prop:lSRZ_by_volume_vectors}
    For every integer vector $\vv=(v_1, \dots, v_n) \in \ZZ_{>0}^n$, there is some LR zonotope with
    integer generators and with volume vector $\vv$.
    If $\gcd(v_1, \dots, v_n) = 1$, then any two such zonotopes are equivalent by a unimodular
    transformation.
\end{proposition}

The following proof is paraphrased from~\cite{Malikiosis2024LinExpCheckingLRC}.
Algorithm~\ref{alg:slrz_from_vv} in Section~\ref{subsec:enumerating_slrzs} uses the ideas in the proof to
compute generators for a LR zonotope from its volume vector.


\begin{proof}
Start with the LR zonotope $Z'$ generated by $\uu'_i=-\ee_i$ for $i=1,\dots,n-1$ and $\uu'_n=\tfrac1{v_n}(v_1,\dots,v_{n-1})$.
It has volume vector $\tfrac1{v_n} \vv$.
Let $\Lambda'$ be the superlattice of $\ZZ^{n-1}$ generated by $\{\uu'_i: i \in [n]\}$ and let $T$ be a linear transformation bijecting $\Lambda'$ to $\ZZ^{n-1}$.
Then $T(Z')$ has volume vector $\tfrac1{m} \vv$, where $m=\gcd(v_1,\dots,v_n)$.
If $m\ne 1$, scale one coordinate up by a factor $m$ to get the correct volume vector.

To show uniqueness, let $Z$ and $Z'$ be two integer LR zonotopes both with volume vector $\vv$.
Let $\mathbf U=\{\uu_1,\dots,\uu_n\}$ and $\mathbf U'=\{\uu'_1,\dots,\uu'_n\}$ be their sets of generators.
Assuming $\gcd(v_1,\dots,v_n)=1$ implies that both $\mathbf U$ and $\mathbf U'$ span $\ZZ^n$ as a lattice.
%
Since changing the sign of a generator in a zonotope is a unimodular transformation (namely a translation), there is no loss of generality in assuming that
\[
    v_1 \uu_1+\cdots + v_n \uu_n = 0 = v_1 \uu'_1+\cdots + v_n \uu'_n.
\]
This
formula implies that the linear map sending $\uu_i$ to $\uu'_i$ for $i=1,\dots,n-1$ also sends $\uu_n$ to $ \uu'_n$, and the fact that $\mathbf U$ and $\mathbf U'$ span $\ZZ^n$ implies that this map is a unimodular transformation.
\end{proof}

\subsection{Covering radius and the sLRC}
\label{subsec:cov-radius-and-slrc}
A \emph{convex body} in $\RR^d$ is a convex compact subset.
We will always assume that our convex bodies are \emph{nondegenerate}, that is, that they have a non-empty interior.
This includes all bounded full-dimensional polytopes.

\begin{definition}[Covering radius]
    Let $C \subseteq \RR^d$ be a convex body.
    The \emph{covering radius of $C$}, denoted $\mu(C)$, is
    the smallest dilation factor $\rho > 0$ such that 
    \[
    \rho C + \ZZ^d = \RR^d.
    \]
\end{definition}

The covering radius is invariant under real translations and unimodular transformations of $C$, since they amount to translations and unimodular transformations of $\rho C + \ZZ^d$, respectively.

The following zonotopal restatement of the \emph{Shifted Lonely Runner Conjecture} is taken from~\cite{Malikiosis2024LinExpCheckingLRC} but the result is implicit in~\cite{zonorunners}, and also in~\cite{sLRC, Cslovjecsek2022CovRadiusPolytope}.

\begin{proposition}[\cite{zonorunners}, see also~\protect{\cite[Proposition 1.8]{Malikiosis2024LinExpCheckingLRC}}]
\label{prop:zono_sLRZ}
    Let $\vv = (v_1, \dots, v_n) \in \ZZ_{>0}^n$ with pairwise distinct entries
    and $\gcd(v_1, \dots, v_n) = 1$.
    Then, the following are equivalent:
    \begin{enumerate}
        \item The velocity vector $\vv$ satisfies the Shifted Lonely Runner Conjecture (Conjecture~\ref{conj:slrc}) for every choice of $(s_1,\dots,s_n)$.
        \item The sLR zonotope $Z$ with volume vector $\vv$ has $\mu(Z) \le \tfrac{n-1}{n+1}$.
    \end{enumerate}
%\pacoS{added the case of equality, although it is not explicitly stated anywhere (afaik)}
Moreover, the velocity vector $\vv$ is tight if and only if $\mu(Z) = \tfrac{n-1}{n+1}$.
\end{proposition}

The problem of exactly computing the covering radius of a rational polytope $P$ was first addressed by Kannan~\cite{Kannan1992LatTranslatesPolytope},
who proved it to be $NP$-hard and designed an algorithm that is doubly-exponential in the input size.
A better algorithm, singly exponential in the input size and polynomial (of degree $2d^3$) in fixed dimension $d$,
was designed in~\cite{Cslovjecsek2022CovRadiusPolytope}; we sketch another one in Remark~\ref{rem:exact_mu}.

But in order to use the zonotopal rephrasing to prove the sLRC one does not really need to
\emph{compute} the covering radius, only to check whether a certain number $\rho$ is a bound for it.
This checking is computationally much less expensive, and amounts to finding a fundamental domain inside a scaled copy $\rho P$ of $P$, or proving that none exists.

Recall that a \emph{fundamental domain} of $\RR^d$ (with respect to $\ZZ^d$) is a set containing exactly one representative of each coset $\pp + \ZZ^d$, $\pp \in \RR^d$.
The definition of covering radius easily translates to the following statements:

\begin{lemma}
    \label{lemma:cov_radius_ub_if_contains_fundamental_domain}
    \label{lemma:cov_radius_lb_iff_not_exists_open_representative_of_quotient}
    \label{lemma:cov_radius_lb_iff_not_exists_representative_of_quotient}
    Let $C$ be a convex body in $\RR^d$ and $\rho>0$.
    Then, the following are equivalent:
    \begin{enumerate}
        \item $\mu(C) \le \rho$.
        \item $\rho C$ contains a representative of each class in $\RR^d/\ZZ^d$.
        \item $\rho C$ contains a fundamental domain.
        \item There is no open set $W \in \RR^d$ with $\rho C \cap (W + \ZZ^d) = \emptyset$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    The implications $(1)\Leftrightarrow(2)\Leftrightarrow(3)$ and $(2)\Rightarrow(4)$ are obvious.
    Let us prove $(4)\Rightarrow(1)$.
    $\mu(C) > \rho$ implies there is a $\pp \not\in \rho C + \ZZ^d$.
    Since $\rho C + \ZZ^d$ is closed, its complement $W \coloneqq \RR^d\setminus \rho C$ is open and
    \[
    \rho C \cap (W + \ZZ^d) \subset
    (\rho C \cap (\RR^d\setminus \rho C)) + \ZZ^d = \emptyset.
    \qedhere
    \]
\end{proof}

\medskip

Since tight instances of the sLR Conjeture correspond in Proposition~\ref{prop:zono_sLRZ} to sLR zonotopes $Z$ with $\mu(Z)$ exactly equal to $\tfrac{n-1}{n+1}$, the following result from~\cite{Malikiosis2024LinExpCheckingLRC} says that sLR $3$-zonotopes of volume at least 196 not only satisfy the sLR conjecture (Theorem~\ref{thm:thm_e}) but also that they are never tight:%
\footnote{This result is not in the currently public version of~\cite{Malikiosis2024LinExpCheckingLRC} (arXiv.v1) but it is to be included in a forthcoming version.}

\begin{theorem}[\cite{Malikiosis2024LinExpCheckingLRC}]
\label{thm:no_big_tight}
Every sLR $3$-zonotope $Z$ of volume at least $196$ has $\mu(Z) < \frac35$.
\end{theorem}


\subsection{The denominator of the covering radius}
\label{subsec:cov-radius-denominator}

It is well-known and easy to show that the covering radius of a rational polytope is rational (see, e.g.,~\cite[Proposition 5.1]{Kannan1992LatTranslatesPolytope}).
In this section we prove an explicit bound for its denominator in terms of the defining equations, where the denominator of a rational number $\rho$ is defined as the minimum positive integer $s$ such that $s\rho$ is an integer.
Having a bound for the denominator allows our algorithms to certify an exact upper bound for $\mu(P)$ from an approximate one, as follows.

\begin{proposition}
\label{prop:cov_radius_safe_interval}
    Let $P$ be a rational polytope and let $D\in \NN$ be an upper bound for the denominator of $\mu(P)$.
    (For example, but not necessarily, a bound obtained by Corollary~\ref{cor:cov_radius_size_bound} below).
    Let $\rho= r/s$ with $r,s\in \ZZ$ and $s>0$.
    Then, the following equivalences hold:
    \begin{enumerate}
        \item $\mu(P) \le \rho$ if and only if $\mu(P) < \rho + \frac{1}{sD}$.
        \item $\mu(P) \ge \rho$ if and only if $\mu(P) > \rho - \frac{1}{sD}$.
    \end{enumerate}
\end{proposition}

\begin{proof}
    One direction is obvious in both cases.
    For the other one, we know that $\mu(P) = \tfrac{r'}{s'}$ for integers $r',s'$ with $0< s'\le D$.
    Assuming $\tfrac{r'}{s'} \ne \tfrac{r}{s}$ we have that
    \[
        \abs{\mu(P) - \rho} = \abs{\tfrac{r'}{s'} - \tfrac{r}{s}} = \abs{\tfrac{r' s-rs'}{s's}} \ge \tfrac1{ss'} \ge \tfrac1{sD}.
    \]
    Hence, either $\mu(P) = \rho$, $\mu(P) \ge \rho + \frac1{sD}$ or $\mu(P) \le \rho - \frac1{sD}$.
\end{proof}


Our bound for the denominator uses the concept of last covered point.

\begin{definition}[Last covered point~\cite{CodenottiSantosSchymura, Cslovjecsek2022CovRadiusPolytope}]
    Let $C \subseteq \RR^d$ be a convex body.
    A \emph{last covered point} for $C$ is any $\pp \in \RR^d$ with
    $\pp \notin (\mu(C)\,C)^{\circ} + \ZZ^d$, where $C^\circ$ denotes the interior of $C$.
\end{definition}

Since $\mu(C)$ is invariant under translation,
we may assume $\oo \in C^\circ$ without loss of generality.
This simplifies some arguments because it implies that $\rho C +\qq$ is monotone increasing in $\rho$;
once a point is covered by some copy $\rho C + \qq$, it is also covered by $\rho' C + \qq$ for any $\rho' > \rho$.

The set of last covered points is always non-empty.
%
Indeed, assuming without loss of generality $\oo\in C^\circ$, for each point $\pp\in \RR^d$ let $\rho_{\pp} = \inf (\{\rho\in \RR_{\geq 0} : \pp \in (\rho C)^{\circ} + \ZZ^d\})$ be the \emph{covering time} of the point $\pp$.
The covering time is invariant by integer translations, and continuous.
Since $\RR^d / \ZZ^d$ is compact, there must be points $\pp$ with maximal covering time, i.e.\ $\rho_{\pp}=\mu(C)$.
These are precisely the last covered points.

In the rest of the section, $P\subseteq \RR^d$ is a polytope defined by the system of inequalities $Ax\le b$ for some matrix $A\in \RR^{m\times d}$ and vector $b \in \RR^m$.
For an element $i\in [m]$ or subset $I\subset [m]$, $A_i$, $b_i$, $A_I$, $b_I$, etc.
denote the restriction of a matrix or vector to the rows labeled by $i$ or $I$.

\begin{lemma}[\protect{\cite[Lemma 3.1]{Cslovjecsek2022CovRadiusPolytope}}]
\label{lemma:last-covered}
    Let $P=\{Ax\le b\}$ be a polytope with non-empty interior.
    Then, there is
    \begin{itemize}
        \item a subset $R\subset [m]$ of rows with $|R|=d+1$ and $\det(A_R|b_R) \ne 0$, and
        \item a lattice point $\qq_i\in \ZZ^d$ for each $i\in R$,
    \end{itemize}
    such that the system
    \begin{equation}
    \label{eq:last-covered}
      A_R (\xx-\qq_i) = t \,b_R
    \end{equation}
    has a unique solution in $\RR^{d+1}$ and this solution is of the form $(\xx,t) = (\pp,\mu(P))$, where $\pp$ is a last covered point.
\end{lemma}

\begin{proof}
  Let $\rho=\mu(P)$.
  As above, assume without loss of generality that $\oo\in P^\circ$, or
  equivalently, that $b_i > 0$ for all $i\in [m]$.

  Each facet of a translated polytope $\{\rho P+\qq: \qq \in \ZZ^d\}$ is labeled by a point $\qq\in \ZZ^d$ and an index $i\in [m]$.
  For each last covered point $\pp$, let $R_\pp$ be the set of indices $i$ such that $\pp$ lies in the $i$-th facet of $\rho P+\qq_i$ for some $\qq_i\in \ZZ^d$.
  Observe that $\pp$ lies in the affine subspace $L_\pp\coloneqq \cap_{i\in R_{\pp}}\{\xx\in \RR^d| A_i (\xx -\qq_i) = \rho b_i \}$, since
  $A_i (\xx -\qq_i) = \rho b_i$ is the facet equation for the $i$-th facet of $\rho P+\qq_i$.

  Choose a last covered point $\pp$ so that $R_\pp$ is maximal.
  Maximality implies that $L_\pp=\{\pp\}$, since otherwise, moving the point within $L_\pp$ until an extra facet of some $\{\rho P+\qq: \qq \in \ZZ^d\}$ is met (which happens at the latest when we
  are about to leave a certain $\rho P+\qq_i$ containing $\pp$), gives us a last covered point $\pp'$ with $R_{\pp'}$ strictly containing $R_\pp$.

  The fact that $L_\pp=\{\pp\}$ implies that the matrix $A_{R_\pp}$ consisting of rows used in $R_\pp$ has full rank, equal to $d$.

  Now, observe that the vectors $A_i$ for $i\in R_\pp$ must have a positive linear dependence.
  Otherwise, by (one of many versions of) Farkas' lemma, there is a vector $\vv\in \RR^d$ such that $\langle A_i, \vv\rangle >0$ for all $i\in R_\pp$.
  Then, $\pp$ would not be last covered, as $\pp+\varepsilon \vv$ would not be covered by any $P+\qq_i$.
  Locally, these are the only translated copies of $P$ that could potentially cover any point in a neighborhood of $\pp$ because $\pp$ cannot be in the interior of any translated copy of $P$.
  %
  Therefore no translated copy of $P$ covers $\pp+\varepsilon \vv$, so $\pp+\varepsilon \vv$ would have larger covering time than $\pp$, contradicting the assumption of $\pp$ being last covered.

  The positive linear dependence among the vectors $\{A_i : i\in R_\pp\}$ implies that the system of equalities 
  \begin{align}
  \label{eq:system}
  A_i \,(\xx - \qq_i) = t b_i, \quad i \in R_\pp,
  \end{align}
  where $t$ is considered an extra variable, has no solution with $t\ne \rho$.
  Indeed, let $\lambda_i\in \RR_{\geq 0}$ for $i \in R_\pp$ be the coefficients of the linear dependence.
  Then,
  %
  \begin{align}
    A_i\,(\xx-\qq_i) &= t b_i, & \forall i \in R_\pp,\nonumber \qquad \Rightarrow\\
    A_i\,(\xx-\pp) + A_i\,(\pp-\qq_i) &= \rho b_i + (t-\rho) b_i & \forall i \in R_\pp, \nonumber  \qquad \Rightarrow\\
    A_i\,(\xx-\pp) &=  (t-\rho) b_i & \forall i \in R_\pp, \nonumber  \qquad \Rightarrow
  \end{align}
  \begin{align}
   0 = \sum_{i\in R_\pp} \lambda_i A_i(\xx-\pp) & = \sum_{i\in R_\pp} \lambda_i (t-\rho) b_i % \nonumber  \\
    = (t-\rho) \left( \sum_{i\in R_\pp} \lambda_i b_i\right). \nonumber
  \end{align}

  But since the $\lambda_i$ are non-negative (and not all of them are zero) and the $b_i$ are positive, then it must be that $t=\rho$.

  Thus, the system~\eqref{eq:system} has only solutions of the form $(\xx, \rho)$.
  Since $A_{R_\pp}$ has rank $d$, it only has the solution $(\pp,\rho)$.
  This implies that the matrix $(A_{R_\pp} |$ $-b_{R_\pp})$ has rank $d+1$.
  %
  Choose as $R$ any basis for the rows of $(A_{R_\pp} | b_{R_\pp})$.
\end{proof}

\begin{corollary}
    \label{cor:cov_radius_size_bound}
    Let $P$ be a rational polytope described by $A\,\xx\le b$ with $A\in \ZZ^{m\times d}$ and $b\in \ZZ^m$.
    Then $\mu(P)$ is a rational number and its denominator is bounded by
        \[\max_{R\in {[m]\choose d+1}} \abs{\det\left(A_R|b_R\right)}.\]
\end{corollary}

\begin{proof}
    Apply Cramer's rule to the variable $t$ in the system of Lemma~\ref{lemma:last-covered}.
\end{proof}

\begin{remark}
Cauchy-Binet implies that $\sqrt{\det\left((A|b)^T(A|b)\right)}$ is a more compact (but worse) bound.
Indeed:
    \[
        \max_{R\in {[m]\choose d+1}} \det(A_R|b_R)^2 \leq  \sum_{R\in {[m]\choose d+1}} \det(A_R|b_R)^2 =
        \det\left((A|b)^T(A|b)\right).
    \]
\end{remark}


\section{An algorithm to bound the covering radius of a rational polytope}
\label{sec:algorithms}

\subsection{Enumeration, construction, and preprocessing of sLR zonotopes}
\label{subsec:enumerating_slrzs}

According to Proposition~\ref{prop:zono_sLRZ}, to obtain Theorem~\ref{thm:main} and Corollary~\ref{coro:main}, we need to enumerate sLR zonotopes up to volume 195 and bound their covering radius by $3/5$.
We first construct the list of possible volume vectors, that is, the $4$-tuples $v=(v_1, \dots,v_4)\in \ZZ^4$ with $0<v_1<v_2<v_3<v_4$ and $\gcd(v_1,v_2,v_3,v_4)=1$.
Enumerating such $4$-tuples is algorithmically trivial and took less than a second in a standard PC:

\begin{proposition}
    \label{prop:volume_vector_count}
    There are exactly $2\,133\,561$ vectors $(v_1, v_2, v_3, v_4) \in \ZZ^4$ with $1 \le v_1 < v_2 < v_3 < v_4$, $\gcd(v_1, v_2, v_3, v_4) = 1$ and $\sum v_i \le 195$.
\end{proposition}


