To generate a representative zonotope from each volume vector $v$, we use Algorithm~\ref{alg:slrz_from_vv}, which follows the `existence' part of the proof of Proposition~\ref{prop:lSRZ_by_volume_vectors}.
Although we apply it to \emph{strong} lonely runner zonotopes, the algorithm works for arbitrary LR zonotopes, as long as the volume vector satisfies $\gcd(v_1,\dots,v_n)$=1.
That is, it needs the $v_i$ to be neither different, positive, nor ordered.

Step 1 in the algorithm creates an integer matrix $M'\in \ZZ^{(n-1)\times n}$ whose columns generate a LR zonotope with volume vector a scalar multiple of $(v_1,\dots,v_n)$.
Step 2 uses a column-wise Hermite normal form of $M'$ to construct a basis (the columns of the matrix $B$ in the algorithm) of the lattice $\Lambda$ generated by the columns of $M'$.
Observe that $\operatorname{rk}(M')=n-1$ implies that the last column of its Hermite normal form $H$ is zero, and $B$ is simply equal to $H$ without that column.

Now, $B^{-1}$ is the matrix of a linear isomorphism $\Lambda \xrightarrow{\cong} \ZZ^{n-1}$, so the columns of $B^{-1} M'$ would already be valid generators for a LR zonotope with volume vector $(v_1,\dots,v_n)$.
%
However, the generators obtained in this way typically have some large entries, resulting in `long and skinny' zonotopes that are poorly conditioned for computing their covering radii.
To overcome this, we preprocess the generators in step 3, by performing an LLL lattice basis reduction to the rows of $B^{-1} M'$.%
\footnote{We have implemented the LLL algorithm with $\delta=3/4$. Higher values of $\delta \in (0,1)$ would give better zonotopes, but would increase the running time.}
This produces a matrix $M$ whose columns are unimodularly equivalent to those of $B^{-1} M'$, but with smaller entries.

\begin{algorithm}
\SetAlgoHangIndent{0pt}
    \caption{Compute generators for a LR zonotope from its volume vector.}
    \label{alg:slrz_from_vv}

    \DontPrintSemicolon
    \SetKwInOut{Input}{Input}
    \SetKwInOut{Output}{Output}

     \Input{$v=(v_1, \dots, v_n)\in \ZZ_{>0}^n$, with $\gcd(v_1,\dots,v_n)=1$.}
    \Output{A matrix $M=(\uu_1 ,\dots,\uu_n)\in \ZZ^{(n-1)\times n}$ such that $\uu_1,\dots,\uu_n$ generate a LR zonotope with volume vector $v$.}

    \SetKw{And}{and}
    Let
   $
   M' \coloneqq
       \left(\begin{array}{c c c|c}
          -v_{n} &        &          & v_1    \\
                 & \ddots &          & \vdots \\
                 &        & -v_{n} & v_{n-1}
    \end{array}\right)
    \in \ZZ^{(n-1)\times n}.
    $\;
    Let $H\in \ZZ^{(n-1)\times n}$ be the column-wise Hermite normal form of $M$, and let $B \in \ZZ^{(n-1)\times (n-1)}$ consist of the first $n-1$ columns of $H$.

     Apply an LLL-reduction to the rows of $B^{-1} M'$ and let $M\in \ZZ^{(n-1)\times n}$ have as rows the resulting reduced vectors.\;
    \Return $M$.
\end{algorithm}

\medskip

For our covering radius algorithm, we need to convert the generators of the zonotope into an inequality description of it.
This, for an arbitrary zonotope $Z\subset \RR^d$ with generators $U=\{\uu_1,\dots,\uu_n\}$ is done as follows,
where we are identifying $\bigwedge^{d-1} \RR^d \cong (\RR^d)^*$ in the natural way.

\begin{proposition}
Let $Z= \tfrac12 \sum_{i=1}^n [-\uu_i,\uu_i]$ be the $\oo$-symmetric zonotope with generators $\uu_1,\dots,\uu_n$.
Then
\[
Z = \left \{\xx\in \RR^d : - {b_S} \le A_S \xx \le {b_S} : S \in \binom{[n]}{d-1} \right \},
\]
where 
\[
A_S \coloneqq \bigwedge_{i\in S} \uu_i \in (\RR^d)^*
\qquad\text{and}\qquad
b_S \coloneqq \frac{1}{2} \sum_{i=1}^n  \abs{A_S\, \uu_i}.
\]
\end{proposition}

\begin{proof}
Each facet of a zonotope is a zonotope itself, generated by the $\uu_i$ contained in, and spanning, a linear hyperplane.
Hence, every normal vector is indeed of the form $A_S $ for some $(d-1)$-subset $S$ of $U$.%
\footnote{%We are here identifying $\bigwedge^{d-1} \RR^d \cong (\RR^d)^*$ in the natural way. 
If the $\uu_i$ are not in general position, some of the $A_S$ may be zero, but that is not an issue; it just creates trivial inequalities.}

By central symmetry, there are two parallel facets with normal vectors $\pm A_S$.
The corresponding facet inequalities are $ - b_S \le A_S \xx \le b_S$, since $\pm b_S$ are the minimum and maximum values taken by $A_S$ in the set
\[
\left\{ \sum_{i=1}^n \pm \uu_i \right\},
\]
which contains all vertices of $Z$.
\end{proof}

\subsection{Certifying an upper bound for the covering radius}\label{subsec:certifying-cov-radius}
We here give an algorithm to decide whether a facet-defined polytope $P=\{\xx\in \RR^d : A\xx \le b\}$ contains a fundamental domain.
By Lemma~\ref{lemma:cov_radius_ub_if_contains_fundamental_domain}, this computational problem is equivalent to that of certifying a given upper bound $\rho$ for the covering radius of a polytope.

We consider a special family of fundamental domains of the integer lattice, given by unions of \emph{dyadic voxels}.

\begin{definition}
\label{def:dyadic}
A \emph{dyadic $d$-voxel} of \emph{level $\ell\in \ZZ_{\ge 0}$} is a half-open cube of the form
\[
\cc + \frac{1}{2^\ell} [0,1)^d,
\]
for some dyadic point $\cc\in \tfrac{1}{2^\ell} \ZZ^d$.
The integer point
$
\floor{\cc}\coloneqq(\floor{\cc_1},\dots, \floor{\cc_d}) \in \ZZ^d
$
 is the \emph{displacement} of the voxel, and the difference 
 \[
 2^\ell(\cc - \floor{\cc}) \in \{0,\dots, 2^\ell-1\}^d
 \]
  is the \emph{type} of the voxel.
 \end{definition}

All dyadic voxels of the same type are equivalent by integer translation, and the voxel types are naturally arranged as an infinite rooted $2^d$-ary tree with the voxels of level $\ell$ at depth $\ell$.
We call this the infinite dyadic tree.%
\footnote{One can represent each type of level $\ell$ as a vector $\tau=(\tau_1,\dots,\tau_d)$ where each $\tau_i$ is a binary string of length $\ell$. In this representation $\tau$ is an ancestor of $\tau'$ in the infinite dyadic tree if and only if each $\tau_i$ is an initial segment, or prefix, of the corresponding $\tau'_i$. Equivalently, if the voxel of type $\tau$ with zero displacement is contained in that of type $\tau'$.}

 A \emph{dyadic fundamental domain} is a fundamental domain obtained as a finite union of dyadic voxels. 
 Since two voxels of the same type are equivalent by integer translation, in order to decide whether a set of voxels defines a fundamental domain only their types matter, and no type can appear more than once in the set.
Moreover, we have the following equivalences:

\begin{proposition}
\label{prop:dyadic_fundamental_domains}
Let $S$ be a collection of dyadic $d$-voxels with no repeated types.
The following are equivalent:
\begin{enumerate}
    \item $S$ is a dyadic fundamental domain.
    \item The voxels of the types in $S$ with zero displacement cover $[0,1)^\ell$ without overlap.
          (We say that they form a dyadic subdivision of $[0,1)^\ell$).
    \item The nodes of the infinite dyadic tree corresponding to types in $S$ are the leaves of a full subtree containing the root.%
    \footnote{An $m$-ary rooted tree is called \emph{full} if every element has either $0$ or $m$ children.}
\end{enumerate}
\end{proposition}

\begin{proof}
The equivalence of (1) and (2) follows from the fact that voxels of the same type are equivalent by translation.
The equivalence of (2) and (3) is easy by induction on the number of internal nodes in the tree.
Induction starts with the tree with zero internal nodes, whose only leaf is the root, indeed a fundamental domain.
The inductive step comes from noting that substituting a leaf with its $2^d$ children amounts to subdividing the corresponding dyadic voxel.
\end{proof}

That is to say, every dyadic fundamental domain can be expressed as (the leaves of) a full-subtree of the infinite dyadic tree, with leaves labeled by their displacements.

This suggests a simple algorithm to construct a dyadic fundamental domain contained in a polytope $P$ via a search in the infinite dyadic tree, starting at the root:
If a node represents a type that fits (up to lattice translation) in $P$, add it to the fundamental domain you are constructing; if it doesn't, then add its $2^d$ children to the list of nodes to be processed.
%
This algorithm needs checking whether a given voxel admits a lattice translation contained in $P$, which amounts to the feasibility of an integer
linear program:
\begin{proposition}
    \label{prop:dyadic_voxel_in_polytope}
    Let $P=\{A\xx \le b\}\subset \RR^d$ be a polytope and let $V = \cc + [0, \epsilon)^d$ be a voxel.
    Then, $P$ contains an integer translation of $V$ if and only if the following Integer Linear Program is feasible:
    \begin{align}
    \label{eq:dyadic_voxel_in_polytope}
         \text{\rm find}       \;\;\xx \in \ZZ^d \qquad
         \text{\rm subject to} \;\;A \xx  \le b - A  \cc  - A_{\ge 0}\, {\boldsymbol \epsilon},
    \end{align}
    Here $\boldsymbol \epsilon \in \RR^d$ is the vector with all entries equal to $\epsilon$ and $A_{\ge 0}$ denotes the matrix with $(i,j)$-th entry equal to $\max\{0,A_{ij}\}$, for every $(i,j)$.
\end{proposition}

\begin{proof}
A half-open voxel is contained in $P$ if and only of the closed voxel is, that is, if and only of all the vertices of the translated closed voxel are in $P$.
Hence, for a given $\xx \in \ZZ^d$, the voxel $\xx + V =  \xx + \cc + [0, \epsilon)^d$ is contained in $P$ if and only if all the points $\yy\in \{0,\epsilon\}^d$ satisfy the inequalities $A(\yy+\cc +\xx) \le b$.
Now, for each row $A_i$ of $A$, the maximum value of the functional $A_i$ on the set $\{0,\epsilon\}^d$ is precisely $(A_i)_{\ge 0} \,{\boldsymbol \epsilon}$.
\end{proof}

Now, the search algorithm we have described has two issues:
on the one hand, if $P$ does not contain a dyadic fundamental domain then the search does not terminate;
on the other hand, this may happen even if $\mu(P) \le 1$, since $P$ may contain a fundamental domain but not a dyadic one.
%
For rational polytopes we can solve both issues resorting to Proposition~\ref{prop:cov_radius_safe_interval}.

\begin{theorem}
\label{thm:cov_radius_dyadic}
    Let $P$ be a rational polytope and let $D$ be an upper bound for the denominator of $\mu(P)$.
    Let $\rho=r/s$ with $r,s\in \ZZ$ and $s>0$.
    Let $P^+ = \left(\rho + \frac1{2sD}\right) P$.
    \begin{enumerate}
        \item If $\mu(P) \le \rho$, then $P^+$ contains a dyadic fundamental domain.
        \item If $\mu(P) > \rho$, then there is an $\ell \in \ZZ_{\ge 0}$ and a dyadic point $\cc\in \tfrac{1}{2^\ell}\{0,\dots, 2^\ell-1\}^d$ such that $P^+$ does not intersect $\cc +\ZZ^d$.
    \end{enumerate}
\end{theorem}

\begin{proof}
    For part (1) we use that
    \[
    \mu(P^+) = \frac{\mu(P)}{\rho + \frac1{2sD}} \le \frac{\rho}{\rho + \frac1{2sD}} <1.
    \]
    For each $\ell\in \NN$, let $D_\ell$ be the union of all the dyadic voxels of depth $\ell$ contained in $P^+$.
    Since $D_\ell$ converges (e.g., in the Hausdorff metric) to $P^+$ when $\ell$ goes to infinity, we have that $\mu(D_\ell)$ converges to $\mu(P^+)$.
    In particular, there is an $\ell$ such that $\mu(D_\ell) <1$.
    Hence, $D_\ell$ contains a fundamental domain, and this fundamental domain can be obtained taking one representative for each type of voxel in the union $D_\ell$.

    For part (2) we use that $\mu(P) > \rho$ implies (by Proposition~\ref{prop:cov_radius_safe_interval}) that $\mu(P) \ge \rho + \frac1{sD}$.
    Hence
    \[
    \mu(P^+) = \frac{\mu(P)}{\rho + \frac1{2sD}} \ge 
    \frac{\rho + \frac1{sD}}{\rho + \frac1{2sD}} >1.
    \]
    The statement then follows from the density of the dyadic
    points $\ZZ[\tfrac{1}{2}]^d$ in $\RR^d$ and Lemma~\ref{lemma:cov_radius_lb_iff_not_exists_open_representative_of_quotient},
    which asserts the existence of an open set $W \subset \RR^d \setminus (P^+ + \ZZ^d)$.
\end{proof}

The condition in part (2) can be tested for each $\cc$ with a variation of Eq.~\eqref{eq:dyadic_voxel_in_polytope} of Proposition~\ref{prop:dyadic_voxel_in_polytope}, simply taking $\epsilon=0$.
Since there are finitely many possible $\cc$ up to each $\ell$ and a dyadic fundamental domain has a bounded depth, Algorithm~\ref{alg:decide_covering_radius} successfully decides whether $\mu(P)\le \rho$, since it checks the cosets of all dyadic points for each $\ell$ in increasing order.

\begin{algorithm}[h]
    \caption{Decide whether $\mu(P)$ is bounded by $\rho$.}
    \label{alg:decide_covering_radius}

    \DontPrintSemicolon
    \SetKwInOut{Input}{Input}
    \SetKwInOut{Output}{Output}

    \Input{A rational polytope $P=\{A\xx\le b\}$ (with $A$ and $b$ integer) and a rational number $\rho=r/s$, with $r,s\in \ZZ$ and $s>0$.}
    \Output{A dyadic fundamental domain $S$ or a dyadic point $\cc$ certifying whether $\mu(P) \le \rho$ or not, as in Theorem~\ref{thm:cov_radius_dyadic}.}

    \SetKw{And}{and}
    \SetKw{Is}{is}
    Let $D$ be a bound on the denominator of $\mu(P)$, e.g., the one in Corollary~\ref{cor:cov_radius_size_bound}.\;
    Let 
    \[
        P^+=\left(\rho + \frac1{2sD}\right) P =\left\{A \xx \le \left(\rho + \frac1{2sD}\right) b\right\}
    \]\;
    Initialise a queue $N$ of `nodes to be processed' containing the root\;
    Initialise an empty list $S$ of `voxels in the fundamental domain'\; 
    \While {there are nodes in $N$} {
        Let $V = \cc +[0,\tfrac1{\ell^d})^d$ be one such node of minimum depth.\;
        Delete $V$ from $N$ and\;
        \eIf {$P^+$ does not intersect $\cc +\ZZ^d$\label{line:lb_test}} {
            \Return $\cc$
        } {
            \eIf { $\exists\; \pp\in \ZZ^d$ with $\pp +V \subset P^+$}
                {add the voxel $\pp + V$ to $S$}
                {add the $2^d$ children of $V$ to $N$\label{line:else}}
        }
    }
    \Return{$S$}
\end{algorithm}


