\begin{theorem}
    \label{thm:alg_decide_cov_radius_sLRZ_correct}
    Algorithm~\ref{alg:decide_covering_radius} always terminates and it correctly decides whether
    $\mu(P) \le \rho$ for any lattice polytope $P$ and
    $\rho \in \QQ$.
\end{theorem}

\begin{proof}
    Observe that the algorithm returns a certificate in either case.
    Let us first show their correctness.

    If the algorithm finishes with a set of dyadic voxels, these voxels
    are a full subtree of the infinite dyadic tree by construction, and
    hence they form a dyadic fundamental domain.
    Furthermore, all of these voxels are contained in $P^+$, so
    $\mu(P) \le (\rho + \frac1{2sD})$ and
    Proposition~\ref{prop:cov_radius_safe_interval} implies $\mu(P) \le \rho$.

    On the other hand, if the algorithm finishes with a point
    $\cc$ such that $P^+$ does not intersect $\cc + \ZZ^d$,
    Lemma~\ref{lemma:cov_radius_lb_iff_not_exists_representative_of_quotient}
    implies $\mu(P) > (\rho + \frac1{2sD}) > \rho$.

    To prove that the algorithm terminates, we handle the two cases separately.

    If $\mu(P) \le \rho$, Theorem~\ref{thm:cov_radius_dyadic} guarantees the existence of a dyadic fundamental domain $D$ contained in $P^+$.
    Let $\ell$ be the maximum depth of the voxels in $D$.
    Then every voxel type of depth $\leq \ell$ has a representative contained in $P^+$, so the algorithm will never enter the ``else'' in line~\ref{line:else} with a voxel of depth $\leq \ell$.
    Hence, the algorithm can perform the while loop only finitely many times before $N$ becomes empty.

    If $\mu(P) > \rho$, Theorem~\ref{thm:cov_radius_dyadic} guarantees the existence of a dyadic point $\cc$ with $(\cc + \ZZ^d)\cap P^+=\emptyset$.
    Let $\ell$ be the minimal depth of such a point.
    Since the algorithm processes the infinite dyadic tree in a breadth-first search manner, it will check in a finite number of steps all the dyadic points of depth $\ell$ (either implicitly for those contained in voxels of depth $\le \ell$ and with $\pp + V \subset P^+$, or explicitly for those not contained in such voxels).
\end{proof}

% \begin{remark}
%     \label{rmk:dfs_termination}
%     Note how the proof of termination only requires that the algorithm explores
%     the dyadic tree in breadth-first order for the case where $\mu(P) > \rho$.
%     A depth-first search may only fail to terminate in such cases.
% \end{remark}

\begin{remark}
    \label{rmk:alg_decide_cov_radius_ge_sLRZ}
    Changing $\rho + \tfrac{1}{2dD}$ to $\rho - \tfrac{1}{2dD}$ in Algorithm~\ref{alg:decide_covering_radius} results in an
    algorithm that decides whether $\mu(P) \ge \rho$, with the same proof of correctness and termination:
%
    If the algorithm returns a dyadic fundamental domain then $\mu(P) < \rho$, otherwise
    Proposition~\ref{prop:cov_radius_safe_interval} implies $\mu(P) \ge \rho$.
\end{remark}


\begin{remark}
\label{rem:exact_mu}
    \label{rmk:alg_compute_cov_radius}
    Algorithm~\ref{alg:decide_covering_radius} can be adapted to 
    compute the exact covering
    radius of an arbitrary rational polytope $P$.
    We still perform a search in the dyadic tree so that at every step the leaves of the already explored tree form a
    dyadic fundamental domain, and then we iteratively subdivide leaves corresponding to voxel types that do not fit in the polytope, but we additionally do the following:
    \begin{itemize}
    \item For each voxel type $V$ (i.e., node in the dyadic tree) that we process we derive two bounds:
    A lower bound $\alpha_V$, given by the minimum $\rho$ such that the center of 
    some voxel of type $V$ is contained in $\rho P$, and an upper bound $\beta_V$
    given by the minimum $\rho$ such that some voxel of type $V$ is contained within $\rho P$.%
    \footnote{Both of these bounds are rational, but computing them precisely
    requires solving a Mixed Integer Linear Program with exact arithmetic related to the one of Proposition~\ref{prop:dyadic_voxel_in_polytope}}

    We let $\alpha =\max_V \alpha_V$ and $\beta = \max_V \beta_V$ where the $\max$ are
    taken over all the voxels in the current fundamental domain, so that $\mu(P)$ is guaranteed to lie in the interval $I=[\alpha, \beta]$.

    \item Instead of exploring the tree in breadth-first order, whenever we need to subdivide
    a voxel we do so with the one with the maximum $\beta_V$.\footnote{For efficiency, rather than looking for the maximum $\beta_V$ each time, one can maintain a priority queue of the voxel types.}

    \item At every step we let $\rho_I $ be the point of $I$ with the smallest denominator%
    \footnote{This point can be obtained as the highest node of the Stern-Brocot tree that is contained in the search
    interval $I$. For efficiency, rather than computing $\rho_I$ from scratch one can just descend in the Stern-Brocot tree from one $\rho_I$ to the next whenever $I$ changes.}.
    This $\rho_I$ is a candidate to be the exact covering radius, and it is declared to coincide with $\mu(P)$
    when the bounds from Proposition~\ref{prop:cov_radius_safe_interval}
    applied to $\rho_I$ discard all other elements of the interval $I$ from being the covering radius of $P$.
    \end{itemize}
        The algorithm returns the final $\rho_I=\mu(P)$ together with: the interval $I=[\alpha,\beta]$;
    the dyadic fundamental domain constructed, certifying that $\beta$ is an upper bound for $\mu(P)$;
    and the center of the voxel type with $\alpha_V = \alpha$, certifying that $\beta$ is a lower bound.
\end{remark}

