\subsection{Tierney and Kadane's approximation}
The Tierney and Kadane's approximation (T-K) method is an another approach to evaluate the ratio integral, which was introduced by \cite{tierney1986accurate}. Under this method, The posterior expectation $E\left(\zeta\left(\alpha, \beta\right)|x\right)$ can be written as
\begin{equation*}
	E\left[\zeta\left(\alpha, \beta\right)|x\right]=\frac{\int e^{n\psi^{*}\left(\alpha, \beta\right)}d\alpha d\beta}{\int e^{n\psi\left(\alpha, \beta\right)}d\alpha d\beta}.
\end{equation*}
where, $\psi\left(\alpha, \beta\right)=\left(\mathcal{L}\left(\alpha, \beta\right)+\phi\left(\alpha, \beta\right)\right)/n$ and $\psi^{*}\left(\alpha, \beta\right)=\psi\left(\alpha, \beta\right)+\frac{1}{n}\ln\zeta\left(\alpha, \beta\right).$\\
Here, $\mathcal{L}\left(\alpha, \beta\right)$ and $\phi\left(\alpha, \beta\right)$ same as defined in the last section.
Thus, the approximate value of posterior expectation of  $\zeta\left(\alpha, \beta\right)$ using T-K approximation method can be written as
\begin{equation}\label{tk_bayes}
	\hat{E}\left[\zeta\left(\alpha, \beta\right)\right]=\left(\frac{\det{\Sigma^{*}}}{\det{\Sigma}}\right)^{1/2}e^{n\left\{\psi^{*}\left(\hat{\alpha}^{*}, \hat{\beta}^{*}\right)-\psi\left(\hat{\alpha},\hat{\beta}\right)\right\}},
\end{equation}
where, $\left(\hat{\alpha}, \hat{\beta}\right)$ and $\left(\hat{\alpha}^{*}, \hat{\beta}^{*}\right)$ maximizes $\psi\left(\hat{\alpha},\hat{\beta}\right)$ and $\psi^{*}\left(\hat{\alpha}^{*}, \hat{\beta}^{*}\right)$ respectively. $\Sigma$ and $\Sigma^{*}$ are the inverse hessian matrices of $\psi\left(\alpha, \beta\right)$ and $\psi^{*}\left(\alpha^{*}, \beta^{*}\right)$ at $\left(\hat{\alpha}, \hat{\beta}\right)$ and $\left(\hat{\alpha}^{*}, \hat{\beta}^{*}\right)$, respectively.
In our case, we have
\begin{align}
	&\psi\left(\alpha, \beta\right)=\frac{1}{n}\left[C+\left(n+a_{1}-1\right)\ln\alpha+\left(n+a_{2}-1\right)\ln\beta-\alpha\left\{\sum_{i=1}^{n-1}\left(m_{i}+1\right)\left(-\ln x_{i}\right)^{\beta}\right.\right.\nonumber\\
	&\qquad\qquad+k\left.\left.\left(-\ln x_{n}\right)^{\beta}\right\}\right]+\frac{1}{n}\left[\left(\beta-1\right)\sum_{i=1}^{n}\ln\left(-\ln x_{i}\right)-\sum_{i=1}^{n}\ln x_{i}-\alpha b_{1}-\beta b_{2}\right]\nonumber
\end{align}
\begin{align}
	&\psi^{*}\left(\alpha, \beta\right)=\frac{1}{n}\left[C+\left(n+a_{1}-1\right)\ln\alpha+\left(n+a_{2}-1\right)\ln\beta-\alpha\left\{\sum_{i=1}^{n-1}\left(m_{i}+1\right)\left(-\ln x_{i}\right)^{\beta}\right.\right.\nonumber\\
	&\qquad\qquad\left.\left.+k\left(-\ln x_{n}\right)^{\beta}\right\}\right]+\frac{1}{n}\left[\left(\beta-1\right)\sum_{i=1}^{n}\ln\left(-\ln x_{i}\right)-\sum_{i=1}^{n}\ln x_{i}-\alpha b_{1}-\beta b_{2}+\zeta\left(\alpha, \beta\right)\right],\nonumber
\end{align}
where $C$ is a constant independent of parameters $\alpha$, $\beta$. Further, obtain $	\psi_{1}= \frac{\partial}{\partial\alpha}\psi\left(\alpha, \beta\right)$ and $	\psi_{2}= \frac{\partial}{\partial\beta}\psi\left(\alpha, \beta\right),$ then equate both of these quantities to 0. We get
\begin{align}
&\frac{1}{\alpha}-\frac{1}{n}\left[\sum_{i=1}^{n-1}\left(m_{i}+1\right)\left(-\ln x_{i}\right)^{\beta}+k\left(-\ln x_{n}\right)^{\beta}\right]=0 \label{mle1}\\
	&\frac{1}{\beta}-\frac{\alpha}{n}\left[\sum_{i=1}^{n-1}\left(m_{i}+1\right)\left(-\ln x_{i}\right)^{\beta}\ln\left(-\ln x_{i}\right) 
	+k\left(-\ln x_{n}\right)^{\beta}\ln\left(-\ln x_{n}\right)\right]\nonumber\\
	&\qquad\qquad\qquad\qquad+\frac{1}{n}\sum_{i=1}^{n}\ln\left(-\ln x_{i}\right)+\frac{a_{2}-1}{\beta}-b_{2}=0.\label{mle2}
\end{align}

Now $\hat{\alpha}$ and $\hat{\beta}$ can be obtained by solving \eqref{mle1} and \eqref{mle2}. Thus, the determinant for the negative of the inverse Hessian of $\psi\left(\alpha, \beta\right)$ evaluated at $\left(\hat{\alpha}, \hat{\beta}\right)$ is as:
\begin{equation*}
	\det\Sigma=\left(\psi_{11}\psi_{22}-\psi_{12}^{2}\right)^{-1},
\end{equation*}
where
\begin{align*}
\psi_{11}&= \frac{\partial^{2}}{\partial\alpha^{2}}\psi\left(\alpha, \beta\right)\bigg|_{\hat{\alpha},\hat{\beta}}=-\frac{1}{\hat{\alpha}^{2}}-\frac{a_{1}-1}{\hat{\alpha}^{2}}\\
\psi_{12}&= \frac{\partial^{2}}{\partial\alpha\partial\beta}\psi\left(\alpha, \beta\right)\bigg\vert_{\hat{\alpha}, \hat{\beta}}=\psi_{21} =-\frac{1}{n}\left[\sum_{i=1}^{n}\left(m_{i}+1\right)\left(-\ln x_{i}\right)^{\hat{\beta}}\ln\left(-\ln x_{i}\right) \right.\nonumber\\
&\qquad\qquad \qquad\qquad \qquad\qquad\qquad\qquad\left.+k\left(-\ln x_{n}\right)^{\hat{\beta}}\ln\left(-\ln x_{n}\right)\right]\\
\psi_{22}&= \frac{\partial^{2}}{\partial{\beta^{2}}}\psi\left(\alpha, \beta\right)\bigg|_{\hat{\alpha}, \hat{\beta}}=-\frac{1}{\hat{\beta^{2}}}-\frac{\hat{\alpha}}{n}\left[\sum_{i=1}^{n-1}\left(m_{i}+1\right)\left(-\ln x_{i}\right)^{\hat{\beta}}\left(\ln\left(-\ln x_{i}\right)^{2}\right)\right. \nonumber\\
&\qquad\qquad \qquad\qquad \qquad\qquad\qquad\qquad\left. + k\left(-\ln x_{n}\right)^{\hat{\beta}}\left(\ln\left(-\ln x_{n}\right)\right)\right]-\frac{a_{2}-1}{\hat{\beta^{2}}}.
\end{align*}
The determinant of $\Sigma$, i.e., $\left(\psi_{11}\psi_{22}-\psi_{12}^{2}\right)^{-1}$  will be same for estimates of parameters under all loss functions while determinant of $\Sigma^{*}$, i.e., $\left(\psi_{11}^{*}\psi_{22}^{*}-\psi_{12}^{*2}\right)^{-1}$ will not be same as it contains the term $\frac{1}{n}\ln\zeta\left(\alpha, \beta\right)$ which is different for each parameter and loss function. \par 
First we will find the Bayes estimators for $\alpha$, $\beta$ and $R(t)$ under SELF. For Bayes estimator of $\alpha$, we have $\zeta(\alpha,\beta)=\alpha$ this implies

\begin{equation}\label{tk_baye_alpha_self}
		\psi^{*}\left(\alpha, \beta\right)=\psi\left(\alpha, \beta\right)+\frac{1}{n}\ln\alpha.
\end{equation}
Now, differentiating \eqref{tk_baye_alpha_self} with respect to $\alpha$, $\beta$, we get
\begin{align*}
	\frac{\partial\psi\left(\alpha, \beta\right)}{\partial\alpha}+\frac{1}{n\alpha}=0\qquad \& \qquad\frac{\partial\psi\left(\alpha, \beta\right)}{\partial\beta}=0.
\end{align*}
Thus, the solution of first derivatives given above produces  the MLE's for $\alpha$ and $\beta$. Now, determinant for the negative of the inverse hessian matrix
of $\psi^{*}\left(\alpha, \beta\right)$ obtained at $\hat{\alpha}^*$ and $\hat{\beta}^*$ is  $\det\Sigma^{*}=\left(\psi^{*}_{11}\psi^{*}_{22}-\psi^{*2}_{12}\right)^{-1}$. The quantities $\psi^{*}_{11},$ $\psi^{*}_{12},$ and $\psi^{*}_{22}$ can be obtained by taking derivatives of $\psi^{*}\left(\alpha, \beta\right)$ as in the case of $\det \Sigma.$ Using the quantity $\det \Sigma$ and $\det \Sigma^*$ in equation \eqref{tk_bayes}, we get the Bayes estimate of $\alpha.$\par 
For the Bayes estimator of $\beta$, we have $\zeta\left(\alpha, \beta\right)=\beta$, this implies

\begin{equation}\label{tk_baye_beta_self}
	\psi^{*}\left(\alpha, \beta\right)=\psi\left(\alpha, \beta\right)+\frac{1}{n}\ln\beta.
\end{equation}
Now, differentiating \eqref{tk_baye_beta_self} with respect to $\alpha$, $\beta$, we get
\begin{align*}
	\frac{\partial\psi\left(\alpha, \beta\right)}{\partial\alpha}=0\qquad \& \qquad\frac{\partial\psi\left(\alpha, \beta\right)}{\partial\beta}+\frac{1}{n\beta}=0.
\end{align*}
Thus, the solution of first derivatives given above produces  the MLE's for $\alpha$ and $\beta$. Now, determinant for the negative of the inverse hessian matrix
of $\psi^{*}\left(\alpha, \beta\right)$ obtained at $\hat{\alpha}^*$ and $\hat{\beta}^*$ is  $\det\Sigma^{*}=\left(\psi^{*}_{11}\psi^{*}_{22}-\psi^{*2}_{12}\right)^{-1}$. Using the same idea of Bayes estimator of $\alpha$, we find the Bayes estimator of $\beta$. \par
Following in the same steps, we can find the Bayes estimator of $R(t)$. For the Bayes estimator of $R\left(t\right)$, we have $\zeta\left(\alpha, \beta\right)=1-e^{-\alpha\left(-\ln t\right)^{\beta}}$, this implies
\begin{align}\label{tk_baye_rel_self}
	\psi^{*}\left(\alpha, \beta\right)=\psi\left(\alpha, \beta\right)+\frac{1}{n}\ln\left(1-e^{-\alpha\left(-\ln t\right)^{\beta}}\right).
\end{align}
Now, differentiating \eqref{tk_baye_rel_self} with respect to $\alpha$, $\beta$, we get
\begin{align*}
	&\frac{\psi\left(\alpha, \beta\right)}{\partial\alpha}+\frac{\left(-\ln t\right)^{\beta}e^{\left(-\ln t\right)^{\beta}}}{n\left(1-e^{-\alpha\left(-\ln t\right)^{\beta}}\right)}=0\\
	&\frac{\psi\left(\alpha, \beta\right)}{\partial\beta}+\frac{\alpha\left(-\ln t\right)^{\beta}\ln\left(-\ln t\right)e^{\left(-\ln t\right)^{\beta}}}{n\left(1-e^{-\alpha\left(-\ln t\right)^{\beta}}\right)}=0.
\end{align*}
Thus, the solution of first derivatives given above produces  the MLE's for $\alpha$ and $\beta$. Now, determinant for the negative of the inverse hessian matrix
of $\psi^{*}\left(\alpha, \beta\right)$ obtained at $\hat{\alpha}^*$ and $\hat{\beta}^*$ is  $\det\Sigma^{*}=\left(\psi^{*}_{11}\psi^{*}_{22}-\psi^{*2}_{12}\right)^{-1}$, where

\begin{align*}
	&\psi^{*}_{11}=\frac{\partial^{2}\psi^{*}\left(\alpha, \beta\right)}{\partial\alpha^{2}}=\psi_{11}-\frac{\left(-\ln t\right)^{2\hat{\beta}}e^{-\alpha\left(-\ln t\right)^{\hat{\beta}}}}{n\left(1-e^{-\hat{\alpha}\left(-\ln t\right)^{\hat{\beta}}}\right)^{2}}\\
	&\psi^{*}_{12}=\frac{\partial\psi^{*}\left(\alpha, \beta\right)}{\partial\alpha\partial\beta}=\psi_{12}+\frac{\left(-\ln t\right)^{\hat{\beta}}\ln \left(-\ln t\right)\left[\left(\left(\hat{\alpha}\left(-\ln t\right)^{\hat{\beta}}\right)-1\right)e^{\hat{\alpha}\left(-\ln t\right)^{\hat{\beta}}}+1\right]}{n\left(1-e^{-\hat{\alpha}\left(-\ln t\right)^{\hat{\beta}}}\right)^{2}}\\
	&\psi^{*}_{22}=\frac{\partial\psi^{*}\left(\alpha, \beta\right)}{\partial\beta^{2}}=\psi_{22}+\frac{\hat{\alpha}\left(-\ln t\right)^{\hat{\beta}}\left(\ln \left(-\ln t\right)\right)^{2}\left[\left(\left(\hat{\alpha}\left(-\ln t\right)^{\hat{\beta}}\right)-1\right)e^{\hat{\alpha}\left(-\ln t\right)^{\hat{\beta}}}+1\right]}{n\left(1-e^{-\hat{\alpha}\left(-\ln t\right)^{\hat{\beta}}}\right)^{2}}.
\end{align*}
The quantities given in Table [\ref{tab:tk_estim_table}] are used for finding the Bayes estimators under LINEX and GE loss functions. The steps involved for obtaining the Bayes estimators are similar to SELF.
